          </CardHeader>
          <CardContent>
            <pre className="text-xs p-3 rounded-lg bg-secondary/40 overflow-auto max-h-96 font-mono">{tests}</pre>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

