            {patch.newFiles.map((f) => <Badge key={f} variant="success" className="text-[9px] font-mono">+ {f}</Badge>)}
            {patch.deletedFiles.map((f) => <Badge key={f} variant="danger" className="text-[9px] font-mono">- {f}</Badge>)}
