        {expanded && (
          <pre className="text-xs p-3 rounded-lg bg-secondary/40 overflow-auto max-h-64 font-mono mt-2">{patch.diff || "(empty)"}</pre>
        )}
      </CardContent>
    </Card>
  );
}

