          <h2 className="text-[11pt] font-bold uppercase tracking-wider mb-2 pb-1 border-b border-slate-300" style={{ color: accent }}>Professional Experience</h2>
          <div className="space-y-3">
            {resume.experience.map((e) => (
              <div key={e.id}>
