                <ul className="space-y-1">
                  {e.bullets.map((b, i) => (
                    <li key={i} className="text-[9.5pt] text-slate-700 pl-5 relative text-justify">
                      <span className="absolute left-0 font-bold" style={{ color: accent }}>▸</span>
                      {b}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </section>
      )}

      <div className="grid grid-cols-2 gap-4">
