              <div className="space-y-1">
                {resume.projects.slice(0, 3).map((p) => (
                  <div key={p.id} className="text-[9pt]">
                    <div className="font-bold text-slate-900">{p.name}</div>
                    {p.description && <div className="text-slate-600">{p.description}</div>}
                  </div>
                ))}
              </div>
            </section>
          )}
        </div>
      </div>
    </div>
  );
}

// ---- Classic template ----
