}

// ── Section: Skills ────────────────────────────────────────────────

function SkillsDiff({
  original,
  optimized,
  mode,
}: {
  original: ResumeData;
  optimized: ResumeData;
  mode: ViewMode;
}) {
  const skillDiff = useMemo(() => {
    const origSkills = new Map(original.skills.map((s) => [s.name.toLowerCase(), s]));
    const optSkills = new Map(optimized.skills.map((s) => [s.name.toLowerCase(), s]));
    const allNames = new Set([...origSkills.keys(), ...optSkills.keys()]);

    const added: typeof original.skills = [];
    const removed: typeof original.skills = [];
    const same: typeof original.skills = [];

    for (const name of allNames) {
      const o = origSkills.get(name);
      const n = optSkills.get(name);
      if (o && !n) removed.push(o);
      else if (!o && n) added.push(n);
      else if (o && n) same.push(o);
    }

    return { added, removed, same };
  }, [original, optimized]);

  const hasChanges = skillDiff.added.length > 0 || skillDiff.removed.length > 0;

  if (mode === "side-by-side") {
    return (
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Original</div>
          <div className="flex flex-wrap gap-1.5">
            {original.skills.length === 0 && <span className="text-sm text-muted-foreground italic">(none)</span>}
            {original.skills.map((s) => (
              <span
                key={s.id}
                className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${
                  !optimized.skills.some((n) => n.name.toLowerCase() === s.name.toLowerCase())
                    ? "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300 line-through"
                    : "bg-secondary text-secondary-foreground"
                }`}
              >
                {s.name}
                {s.category && <span className="opacity-60">({s.category})</span>}
              </span>
            ))}
          </div>
        </div>
        <div className="space-y-2">
          <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Optimized</div>
          <div className="flex flex-wrap gap-1.5">
            {optimized.skills.length === 0 && <span className="text-sm text-muted-foreground italic">(none)</span>}
            {optimized.skills.map((s) => (
              <span
                key={s.id}
                className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${
                  !original.skills.some((o) => o.name.toLowerCase() === s.name.toLowerCase())
                    ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
                    : "bg-secondary text-secondary-foreground"
                }`}
              >
                {s.name}
                {s.category && <span className="opacity-60">({s.category})</span>}
              </span>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Unified mode
  return (
    <div className="space-y-3">
      {hasChanges && (
        <div className="flex flex-wrap gap-1.5">
          {skillDiff.added.length > 0 && (
            <div className="w-full text-xs text-emerald-600 dark:text-emerald-400 font-medium mb-1">Added</div>
          )}
          {skillDiff.added.map((s) => (
            <span
              key={s.id}
              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
            >
              + {s.name}
              {s.category && <span className="opacity-60">({s.category})</span>}
            </span>
          ))}
          {skillDiff.removed.length > 0 && (
            <div className="w-full text-xs text-red-600 dark:text-red-400 font-medium mb-1 mt-2">Removed</div>
          )}
          {skillDiff.removed.map((s) => (
            <span
              key={s.id}
              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300 line-through"
            >
              − {s.name}
              {s.category && <span className="opacity-60">({s.category})</span>}
            </span>
          ))}
        </div>
      )}
      {skillDiff.same.length > 0 && (
        <div>
          <div className="text-xs text-muted-foreground font-medium mb-1">Unchanged ({skillDiff.same.length})</div>
          <div className="flex flex-wrap gap-1.5">
            {skillDiff.same.map((s) => (
              <span
                key={s.id}
                className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-secondary text-secondary-foreground"
              >
                {s.name}
                {s.category && <span className="opacity-60">({s.category})</span>}
              </span>
            ))}
          </div>
        </div>
      )}
      {!hasChanges && skillDiff.same.length === 0 && (
        <div className="text-sm text-muted-foreground italic py-4 text-center">No skills to compare.</div>
      )}
    </div>
  );
}

// ── Section: Languages ─────────────────────────────────────────────

function LanguagesDiff({
  original,
  optimized,
  mode,
}: {
  original: ResumeData;
  optimized: ResumeData;
  mode: ViewMode;
}) {
  const langDiff = useMemo(() => {
    const origLang = new Map(original.languages.map((l) => [l.name.toLowerCase(), l]));
    const optLang = new Map(optimized.languages.map((l) => [l.name.toLowerCase(), l]));
    const allNames = new Set([...origLang.keys(), ...optLang.keys()]);

    const added: typeof original.languages = [];
    const removed: typeof original.languages = [];
    const modified: { orig: typeof original.languages[0]; next: typeof original.languages[0] }[] = [];
    const same: typeof original.languages = [];

    for (const name of allNames) {
      const o = origLang.get(name);
      const n = optLang.get(name);
      if (o && !n) removed.push(o);
      else if (!o && n) added.push(n);
      else if (o && n) {
        if (o.proficiency !== n.proficiency) modified.push({ orig: o, next: n });
        else same.push(o);
      }
    }

    return { added, removed, modified, same };
  }, [original, optimized]);

  const hasChanges = langDiff.added.length > 0 || langDiff.removed.length > 0 || langDiff.modified.length > 0;

  if (mode === "side-by-side") {
    return (
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Original</div>
          {original.languages.length === 0 && <span className="text-sm text-muted-foreground italic">(none)</span>}
          {original.languages.map((l) => {
            const inOpt = optimized.languages.some((n) => n.name.toLowerCase() === l.name.toLowerCase());
            return (
              <div
                key={l.id}
                className={`flex items-center justify-between text-sm px-2 py-1 rounded ${
                  !inOpt ? "bg-red-100 dark:bg-red-900/30 line-through text-red-700 dark:text-red-300" : ""
                }`}
              >
                <span>{l.name}</span>
                <span className="text-xs text-muted-foreground">{l.proficiency}</span>
              </div>
            );
          })}
        </div>
        <div className="space-y-2">
          <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Optimized</div>
          {optimized.languages.length === 0 && <span className="text-sm text-muted-foreground italic">(none)</span>}
          {optimized.languages.map((l) => {
            const inOrig = original.languages.some((o) => o.name.toLowerCase() === l.name.toLowerCase());
            return (
              <div
                key={l.id}
                className={`flex items-center justify-between text-sm px-2 py-1 rounded ${
                  !inOrig ? "bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300" : ""
                }`}
              >
                <span>{l.name}</span>
                <span className="text-xs text-muted-foreground">{l.proficiency}</span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // Unified mode
  return (
    <div className="space-y-2">
      {langDiff.added.length > 0 && (
        <div>
          <div className="text-xs text-emerald-600 dark:text-emerald-400 font-medium mb-1">Added</div>
          {langDiff.added.map((l) => (
            <div
              key={l.id}
              className="flex items-center justify-between text-sm px-2 py-1 rounded bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300"
            >
              <span>+ {l.name}</span>
              <span className="text-xs">{l.proficiency}</span>
            </div>
          ))}
        </div>
      )}
      {langDiff.removed.length > 0 && (
        <div>
          <div className="text-xs text-red-600 dark:text-red-400 font-medium mb-1">Removed</div>
          {langDiff.removed.map((l) => (
            <div
              key={l.id}
              className="flex items-center justify-between text-sm px-2 py-1 rounded bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 line-through"
            >
              <span>− {l.name}</span>
              <span className="text-xs">{l.proficiency}</span>
            </div>
          ))}
        </div>
      )}
      {langDiff.modified.length > 0 && (
        <div>
          <div className="text-xs text-amber-600 dark:text-amber-400 font-medium mb-1">Modified</div>
          {langDiff.modified.map((l) => (
            <div
              key={l.orig.id}
              className="flex items-center justify-between text-sm px-2 py-1 rounded bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300"
            >
              <span>
                <span className="line-through opacity-60">{l.orig.name}</span>
                {" → "}
                <span>{l.next.name}</span>
                <span className="text-xs ml-1 text-muted-foreground">({l.orig.proficiency} → {l.next.proficiency})</span>
              </span>
            </div>
          ))}
        </div>
      )}
      {langDiff.same.length > 0 && (
        <div>
          <div className="text-xs text-muted-foreground font-medium mb-1">Unchanged ({langDiff.same.length})</div>
          {langDiff.same.map((l) => (
            <div key={l.id} className="flex items-center justify-between text-sm px-2 py-1">
              <span>{l.name}</span>
              <span className="text-xs text-muted-foreground">{l.proficiency}</span>
            </div>
          ))}
        </div>
      )}
      {!hasChanges && langDiff.same.length === 0 && (
        <div className="text-sm text-muted-foreground italic py-4 text-center">No languages to compare.</div>
      )}
    </div>
  );
}

// ── Section summary counts ─────────────────────────────────────────

function useSectionCounts(original: ResumeData, optimized: ResumeData) {
  return useMemo(() => {
    const sections: Record<SectionKey, number> = {
      summary: (original.summary || "") !== (optimized.summary || "") ? 1 : 0,
      experience: countChanged(original.experience, optimized.experience),
      education: countChanged(original.education, optimized.education),
      skills: countChanged(original.skills, optimized.skills),
      languages: countChanged(original.languages, optimized.languages),
    };
    return sections;
  }, [original, optimized]);
}

function countChanged<T extends { id: string }>(orig: T[], opt: T[]): number {
  const origMap = new Map(orig.map((o) => [o.id, o]));
  const optMap = new Map(opt.map((o) => [o.id, o]));
  let changes = 0;
  const allIds = new Set([...origMap.keys(), ...optMap.keys()]);
  for (const id of allIds) {
    const o = origMap.get(id);
    const n = optMap.get(id);
    if (!o || !n || JSON.stringify(o) !== JSON.stringify(n)) changes++;
  }
  return changes;
}

// ── Main DiffPreview component ─────────────────────────────────────

export function DiffPreview({
  original,
  optimized,
}: {
  original: ResumeData;
  optimized: ResumeData;
}) {
  const [viewMode, setViewMode] = useState<ViewMode>("side-by-side");
  const [activeSection, setActiveSection] = useState<SectionKey>("summary");
  const counts = useSectionCounts(original, optimized);

  const totalChanges = Object.values(counts).reduce((a, b) => a + b, 0);

  const sectionLabel: Record<SectionKey, string> = {
    summary: "Summary",
    experience: "Experience",
    education: "Education",
    skills: "Skills",
    languages: "Languages",
  };

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between gap-4 pb-3">
        <CardTitle className="text-base flex items-center gap-2">
          <Icon name="GitCompareArrows" className="w-4 h-4 text-brand" />
          Before / After
          {totalChanges > 0 && (
            <Badge variant="brand" className="ml-1">{totalChanges} change{totalChanges !== 1 ? "s" : ""}</Badge>
          )}
        </CardTitle>
        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={() => setViewMode("side-by-side")}
            className={`px-2.5 py-1 text-xs font-medium rounded-md transition-colors ${
              viewMode === "side-by-side"
                ? "bg-primary text-primary-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground hover:bg-secondary"
            }`}
          >
            <Icon name="Columns2" className="w-3.5 h-3.5 inline mr-1" />
            Side by Side
          </button>
          <button
            type="button"
            onClick={() => setViewMode("unified")}
            className={`px-2.5 py-1 text-xs font-medium rounded-md transition-colors ${
              viewMode === "unified"
                ? "bg-primary text-primary-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground hover:bg-secondary"
            }`}
          >
            <Icon name="AlignLeft" className="w-3.5 h-3.5 inline mr-1" />
            Unified
          </button>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        <Tabs
          value={activeSection}
          onValueChange={(v) => setActiveSection(v as SectionKey)}
          className="w-full"
        >
          <div className="px-6">
            <TabsList className="w-full justify-start rounded-none border-b border-border bg-transparent p-0 h-auto">
              {(Object.keys(sectionLabel) as SectionKey[]).map((key) => {
                const count = counts[key];
                return (
                  <TabsTrigger
                    key={key}
                    value={key}
                    className="relative rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-3 py-2 text-xs font-medium data-[state=active]:text-foreground data-[state=active]:shadow-none bg-transparent hover:text-foreground"
                  >
                    {sectionLabel[key]}
                    {count > 0 && (
                      <span className="ml-1.5 inline-flex items-center justify-center w-4 h-4 rounded-full bg-brand/10 text-brand text-[10px] font-bold">
                        {count}
                      </span>
                    )}
                  </TabsTrigger>
                );
              })}
            </TabsList>
          </div>

          <ScrollArea className="max-h-[420px]">
            <div className="p-4">
              <TabsContent value="summary" className="mt-0">
                <SummaryDiff original={original} optimized={optimized} mode={viewMode} />
              </TabsContent>

              <TabsContent value="experience" className="mt-0">
                <ExperienceDiff original={original} optimized={optimized} mode={viewMode} />
              </TabsContent>

              <TabsContent value="education" className="mt-0">
                <EducationDiff original={original} optimized={optimized} mode={viewMode} />
              </TabsContent>

              <TabsContent value="skills" className="mt-0">
                <SkillsDiff original={original} optimized={optimized} mode={viewMode} />
              </TabsContent>

              <TabsContent value="languages" className="mt-0">
                <LanguagesDiff original={original} optimized={optimized} mode={viewMode} />
              </TabsContent>
            </div>
          </ScrollArea>
        </Tabs>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Icon } from "@/components/shared";
import type { ResumeData, ResumeLanguage } from "@/lib/types";
import { uid, useApp } from "@/lib/store";

/**
 * Safely render any value as a string. Prevents React error #31
 * ("Objects are not valid as a React child") when the AI returns an
 * object (e.g. { city: "Doha", country: "Qatar" }) where a string is
 * expected.
 */
function safeRender(v: any): string {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (Array.isArray(v)) return v.map((x) => safeRender(x)).filter(Boolean).join(", ");
  if (typeof v === "object") {
    const values = Object.values(v).filter((x) => x !== null && x !== undefined && x !== "");
    if (values.length > 0) return values.map((x) => safeRender(x)).join(", ");
    return "";
  }
  return String(v);
}

/**
 * Check if the resume's headline contains duplicate contact info
 * (email, phone, or location) that is already rendered separately
 * in the contact section. If so, skip rendering the headline
 * to avoid triplicate display.
 */
function headlineIsDuplicateContact(headline: string, contact: ResumeData["contact"]): boolean {
  if (!headline || !contact) return false;
  const hl = headline.toLowerCase();
  if (contact.email && hl.includes(contact.email.toLowerCase())) return true;
  if (contact.phone) {
    const phoneDigits = contact.phone.replace(/\D/g, "");
    if (phoneDigits.length >= 5 && hl.includes(phoneDigits)) return true;
  }
  if (contact.location && hl === contact.location.toLowerCase()) return true;
  return false;
}

/**
 * Detect whether the current device is a touch-only device (mobile/tablet without
 * a fine pointer). On touch devices we cannot rely on `:hover` to reveal the
 * edit pencil, so we show it persistently and also enable tap-anywhere-on-section
 * to open the editor.
 */
function useIsTouchDevice(): boolean {
  const [isTouch, setIsTouch] = useState(false);
  useEffect(() => {
    if (typeof window === "undefined") return;
    // Primary signal: the CSS media query `(hover: none) and (pointer: coarse)`
    // matches phones and tablets that lack a hover-capable pointer.
    const mql = window.matchMedia("(hover: none) and (pointer: coarse)");
    const update = () => setIsTouch(mql.matches || "ontouchstart" in window);
    update();
    mql.addEventListener?.("change", update);
    return () => mql.removeEventListener?.("change", update);
  }, []);
  return isTouch;
}

/**
 * EditableA4Preview — InfoHAS Pro template with live inline editing.
 *
 * Every section has a pencil icon that, on click, opens an editor for that section.
 * Photo frame is also clickable — opens file picker to upload a profile photo.
 *
 * On touch devices (mobile/tablet), the pencil is always visible and the entire
 * section is tappable to open the editor (since `:hover` does not work on touch).
 *
 * Used in the Optimizer "done" step so users can refine the AI-optimized resume
 * in place before exporting.
 */

interface EditableA4PreviewProps {
  resume: ResumeData;
  onChange: (patch: Partial<ResumeData>) => void;
  scale?: number;
  className?: string;
}

type EditTarget =
  | null
  | "header"
  | "summary"
  | "skills"
  | `experience:${string}`
  | `education:${string}`
  | "languages";

// Master layout colors — BLACK fallback
const BLACK_FALLBACK = "#000000";

export function EditableA4Preview({ resume, onChange, scale = 0.7, className }: EditableA4PreviewProps) {
  const [editing, setEditing] = useState<EditTarget>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const isTouch = useIsTouchDevice();
  const config = useApp((s) => s.optimizerDirective);

  const L = {
    fontFamily: config?.fontFamily || "'Times New Roman', 'Georgia', 'Cambria', serif",
    bodyFontSizePt: config?.bodyFontSizePt ?? 10.5,
    lineHeight: config?.lineHeight ?? 1.2,
    marginTopMm: config?.marginTopMm ?? 6.35,
    marginBottomMm: config?.marginBottomMm ?? 6.35,
    marginLeftMm: config?.marginLeftMm ?? 8.89,
    marginRightMm: config?.marginRightMm ?? 8.89,
    nameSizePt: config?.nameSizePt ?? 14,
    sectionTitleSizePt: config?.sectionTitleSizePt ?? 12,
    nameColor: config?.nameColor || "#8B0000",
    sectionTitleColor: config?.sectionTitleColor || "#8B0000",
    bodyTextColor: config?.bodyTextColor || "#000000",
    sectionGapMm: config?.sectionGapMm ?? 3,
    bulletIndentMm: config?.bulletIndentMm ?? 6.4,
  };

  const BLACK = L.bodyTextColor;

  // No local draft — the parent owns the state. Edits call onChange() directly,
  // which updates the parent's `resume` prop, which re-renders this component.
  const patch = (p: Partial<ResumeData>) => {
    onChange(p);
  };

  // Commit a draft (close editor)
  const commit = (p: Partial<ResumeData>) => {
    patch(p);
    setEditing(null);
  };

  const onPhotoUpload = (files: FileList | null) => {
    if (!files?.[0]) return;
    const file = files[0];
    if (file.size > 5 * 1024 * 1024) {
      alert("Photo too large. Maximum 5MB.");
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      patch({ photoUrl: reader.result as string });
    };
    reader.readAsDataURL(file);
    if (fileRef.current) fileRef.current.value = "";
  };

  return (
    <div className={className}>
      <input ref={fileRef} type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={(e) => onPhotoUpload(e.target.files)} />

      {/* Outer wrapper — occupies the SCALED layout space (210mm × scale × 297mm × scale)
          so the parent container sees a correctly-sized box. Without this, CSS transform: scale()
          only affects visual rendering, not layout, causing horizontal overflow on mobile. */}
      <div
        style={{
          width: `${210 * scale}mm`,
          height: `${297 * scale}mm`,
          position: "relative",
          overflow: "hidden",
          margin: "0 auto",
        }}
      >
        <div
          className="a4-page origin-top-left relative"
          style={{
            transform: `scale(${scale})`,
            transformOrigin: "top left",
            position: "absolute",
            top: 0,
            left: 0,
          }}
        >
          <div
            className="relative"
            style={{
              fontFamily: L.fontFamily,
              fontSize: `${L.bodyFontSizePt}pt`,
              lineHeight: L.lineHeight,
              padding: `${L.marginTopMm}mm ${L.marginRightMm}mm ${L.marginBottomMm}mm ${L.marginLeftMm}mm`,
              minHeight: "297mm",
              color: BLACK,
            }}
          >
          {/* ============ HEADER (editable) — two-column: 70% left, 30% right photo ============ */}
          <EditableBlock isEditing={editing === "header"} onEdit={() => setEditing("header")} label="Edit header" isTouch={isTouch}>
            <header className="relative" style={{ paddingRight: resume.photoUrl ? "36mm" : 0, minHeight: resume.photoUrl ? "42mm" : "auto" }}>
              {/* Photo — top-right, 30×40mm.
                  - If a photo exists: render it, tappable to replace.
                  - If NO photo exists: render a visible "Upload Photo" placeholder button
                    so mobile users have a clear tap target (the strict layout directive
                    forbids placeholder boxes in the final PDF, but this is the live editing
                    preview — the placeholder is hidden on export).
                  - On touch devices, the photo pencil is always visible; on desktop, hover-reveal. */}
              {resume.photoUrl ? (
                <button
                  onClick={() => fileRef.current?.click()}
                  className="group"
                  style={{
                    position: "absolute",
                    top: 0,
                    right: 0,
                    width: "30mm",
                    height: "40mm",
                    border: "0.5pt solid #999",
                    background: "transparent",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    overflow: "hidden",
                    cursor: "pointer",
                    boxSizing: "border-box",
                    padding: 0,
                  }}
                  title="Tap to change photo"
                >
                  <img src={resume.photoUrl} alt={resume.name} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center top" }} />
                  <div
                    className={"absolute top-0.5 right-0.5 w-5 h-5 rounded-full bg-brand text-white flex items-center justify-center transition " + (isTouch ? "opacity-100" : "opacity-0 group-hover:opacity-100")}
                    style={{ pointerEvents: "none" }}
                  >
                    <Icon name="Pencil" className="w-2.5 h-2.5" />
                  </div>
                </button>
              ) : (
                <button
                  onClick={() => fileRef.current?.click()}
                  type="button"
                  className="group"
                  style={{
                    position: "absolute",
                    top: 0,
                    right: 0,
                    width: "30mm",
                    height: "40mm",
                    border: "1pt dashed #999",
                    background: "#f5f5f5",
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    justifyContent: "center",
                    overflow: "hidden",
                    cursor: "pointer",
                    boxSizing: "border-box",
                    padding: "2mm",
                    gap: "1mm",
                  }}
                  title="Tap to upload photo"
                >
                  <Icon name="User" className="w-5 h-5 text-muted-foreground" />
                  <span style={{ fontSize: "7pt", color: "#666", textAlign: "center", lineHeight: 1.1 }}>Upload Photo</span>
                </button>
              )}

              {/* LEFT COLUMN — name, headline, contact, DOB (70% width, left-aligned, compact) */}
              <div style={{ color: L.nameColor, fontWeight: 700, fontSize: `${L.nameSizePt}pt`, letterSpacing: "0.3pt", marginBottom: "0.5mm", lineHeight: 1.1, textTransform: "uppercase" }}>
                {(resume.name || "YOUR NAME").toUpperCase()}
              </div>
              {resume.headline && !headlineIsDuplicateContact(resume.headline, resume.contact) && <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.5mm", lineHeight: 1.2 }}>{safeRender(resume.headline)}</div>}
              {L.contactSpacing === "single-line" ? (
                <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>
                  {[
                    safeRender(resume.contact.location),
                    safeRender(resume.contact.phone),
                    safeRender(resume.contact.email),
                    resume.dateOfBirth ? `DOB: ${safeRender(resume.dateOfBirth)}` : ""
                  ].filter(Boolean).join(" | ")}
                </div>
              ) : (
                <>
                  <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>
                    {[safeRender(resume.contact.location), safeRender(resume.contact.phone)].filter(Boolean).join(" | ")}
                  </div>
                  {resume.contact.email && <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>{safeRender(resume.contact.email)}</div>}
                  {resume.dateOfBirth && <div style={{ fontSize: `${L.bodyFontSizePt}pt`, color: BLACK, marginBottom: "0.3mm", lineHeight: 1.2 }}>Date of Birth: {safeRender(resume.dateOfBirth)}</div>}
                </>
              )}
            </header>
          </EditableBlock>

          {/* ============ BODY ============ */}
          {/* Compact gap from header to first section */}
          <div style={{ marginTop: "3mm" }}>
            {/* SUMMARY */}
            {resume.summary && (
              <EditableBlock isEditing={editing === "summary"} onEdit={() => setEditing("summary")} label="Edit summary" isTouch={isTouch}>
                <InfohasSection title="PROFESSIONAL PROFILE">
                  <p style={{ margin: 0, textAlign: "justify", color: BLACK, lineHeight: 1.2 }}>{safeRender(resume.summary)}</p>
                </InfohasSection>
              </EditableBlock>
            )}

            {/* EXPERIENCE — section header once, then all entries */}
            {resume.experience.length > 0 && (
              <>
                <SectionDividerInline title="PROFESSIONAL EXPERIENCE" />
                {resume.experience.map((e) => (
                  <EditableBlock
                    key={e.id}
                    isEditing={editing === `experience:${e.id}`}
                    onEdit={() => setEditing(`experience:${e.id}`)}
                    label="Edit experience"
                    isTouch={isTouch}
                  >
                    <div style={{ marginBottom: "1mm" }}>
                      <div style={{ marginBottom: "0.3mm", lineHeight: 1.2, display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: "2mm" }}>
                        <span style={{ flex: 1, minWidth: 0 }}>
                          <span style={{ fontWeight: 700, color: BLACK }}>{String(e.title || "")}</span>
                          {e.company && <span style={{ color: BLACK }}> | {String(e.company)}</span>}
                          {e.location && <span style={{ color: BLACK }}> | {safeRender(e.location)}</span>}
                        </span>
                        <span style={{ color: BLACK, whiteSpace: "nowrap", flexShrink: 0 }}>{fmtDateInfohas(e.startDate)}{e.endDate ? ` – ${fmtDateInfohas(e.endDate)}` : ""}</span>
                      </div>
                      <ul style={{ margin: 0, paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•", lineHeight: 1.2 }}>
                        {e.bullets.map((b, i) => (
                          <li key={i} style={{ marginBottom: 0, color: BLACK, textAlign: "justify", lineHeight: 1.2 }}>{safeRender(b)}</li>
                        ))}
                      </ul>
                    </div>
                  </EditableBlock>
                ))}
              </>
            )}

            {/* EDUCATION — section header once, then all entries */}
            {resume.education.length > 0 && (
              <>
                <SectionDividerInline title="EDUCATION" />
                {resume.education.slice(0, 3).map((ed) => (
                  <EditableBlock
                    key={ed.id}
                    isEditing={editing === `education:${ed.id}`}
                    onEdit={() => setEditing(`education:${ed.id}`)}
                    label="Edit education"
                    isTouch={isTouch}
                  >
                    <div style={{ marginBottom: "1mm", lineHeight: 1.2 }}>
                      <div style={{ lineHeight: 1.2, display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: "2mm" }}>
                        <span style={{ flex: 1, minWidth: 0 }}>
                          <span style={{ fontWeight: 700, color: BLACK }}>{safeRender(ed.degree)}</span>
                          {ed.institution && <span style={{ color: BLACK }}> | {safeRender(ed.institution)}</span>}
                          {ed.location && <span style={{ color: BLACK }}> | {safeRender(ed.location)}</span>}
                        </span>
                        {(ed.startDate || ed.endDate) && (
                          <span style={{ color: BLACK, whiteSpace: "nowrap", flexShrink: 0 }}>
                            {fmtDateInfohas(ed.startDate)} – {fmtDateInfohas(ed.endDate)}
                          </span>
                        )}
                      </div>
                  {ed.highlights && ed.highlights.length > 0 && (
                    <ul style={{ margin: "0.3mm 0 0 0", paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•", lineHeight: 1.2 }}>
                      {ed.highlights.map((h, i) => (
                        <li key={i} style={{ color: BLACK, lineHeight: 1.2, textAlign: "justify" }}>{safeRender(h)}</li>
                      ))}
                    </ul>
                  )}
                    </div>
                  </EditableBlock>
                ))}
              </>
            )}

            {/* KEY COMPETENCIES (moved after Education to match target format) */}
            {resume.skills.length > 0 && (
              <EditableBlock isEditing={editing === "skills"} onEdit={() => setEditing("skills")} label="Edit skills" isTouch={isTouch}>
                <InfohasSection title="KEY COMPETENCIES">
                  <ul style={{ margin: 0, paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•", lineHeight: 1.2 }}>
                    {groupSkillsByCategory(resume.skills).slice(0, 4).map((g, i) => (
                      <li key={i} style={{ marginBottom: 0, color: BLACK, lineHeight: 1.2, textAlign: "justify" }}>
                        <span style={{ fontWeight: 700 }}>{safeRender(g.category)}:</span> <span>{g.items.map((item: any) => safeRender(item)).join(", ")}.</span>
                      </li>
                    ))}
                  </ul>
                </InfohasSection>
              </EditableBlock>
            )}

            {/* LANGUAGES — single line format */}
            {resume.languages.length > 0 && (
              <EditableBlock isEditing={editing === "languages"} onEdit={() => setEditing("languages")} label="Edit languages" isTouch={isTouch}>
                <InfohasSection title="LANGUAGES">
                  <div style={{ color: BLACK, lineHeight: 1.2 }}>
                    • {resume.languages.map((l) => safeRender(l.name)).join(", ")}
                  </div>
                </InfohasSection>
              </EditableBlock>
            )}

            {/* CERTIFICATIONS */}
            {resume.certifications && resume.certifications.length > 0 && (
              <InfohasSection title="CERTIFICATIONS">
                <ul style={{ margin: 0, paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•", lineHeight: 1.2 }}>
                  {resume.certifications.map((cert) => (
                    <li key={cert.id} style={{ color: BLACK, lineHeight: 1.2 }}>
                      {safeRender(cert.name)}{cert.issuer ? ` — ${safeRender(cert.issuer)}` : ""}{cert.date ? ` (${cert.date})` : ""}
                    </li>
                  ))}
                </ul>
              </InfohasSection>
            )}

            {/* PROJECTS */}
            {resume.projects && resume.projects.length > 0 && (
              <InfohasSection title="PROJECTS">
                {resume.projects.slice(0, 3).map((proj) => (
                  <div key={proj.id} style={{ marginBottom: "0.5mm" }}>
                    <div style={{ fontWeight: 700, color: BLACK, lineHeight: 1.2 }}>
                      {safeRender(proj.name)}
                    </div>
                    {proj.description && (
                      <p style={{ margin: "0.2mm 0", color: BLACK, lineHeight: 1.2, textAlign: "justify" }}>
                        {safeRender(proj.description)}
                      </p>
                    )}
                    {proj.bullets && proj.bullets.length > 0 && (
                      <ul style={{ margin: 0, paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•", lineHeight: 1.2 }}>
                        {proj.bullets.map((b, i) => (
                          <li key={i} style={{ color: BLACK, lineHeight: 1.2 }}>{safeRender(b)}</li>
                        ))}
                      </ul>
                    )}
                  </div>
                ))}
              </InfohasSection>
            )}

            {/* DYNAMIC SECTIONS — renders any section type not covered by static fields above */}
            {resume.dynamicSections && resume.dynamicSections.length > 0 && resume.dynamicSections.map((ds) => (
              <InfohasSection key={ds.id} title={ds.title.toUpperCase()}>
                {ds.content && (
                  <p style={{ margin: 0, color: BLACK, lineHeight: 1.2, textAlign: "justify" }}>
                    {safeRender(ds.content)}
                  </p>
                )}
                {ds.bullets && ds.bullets.length > 0 && (
                  <ul style={{ margin: "0.3mm 0 0 0", paddingLeft: `${L.bulletIndentMm}mm`, listStyleType: "•", lineHeight: 1.2 }}>
                    {ds.bullets.map((b, i) => (
                      <li key={i} style={{ color: BLACK, lineHeight: 1.2 }}>{safeRender(b)}</li>
                    ))}
                  </ul>
                )}
              </InfohasSection>
            ))}

            {/* ADDITIONAL INFORMATION */}
            {resume.additionalInfo && (
              <InfohasSection title="ADDITIONAL INFORMATION">
                {resume.additionalInfo.split("\n").map((line, i) => (
                  line.trim() ? (
                    <p key={i} style={{ margin: 0, color: BLACK, lineHeight: 1.2, textAlign: "justify" }}>
                      {safeRender(line.trim())}
                    </p>
                  ) : null
                ))}
              </InfohasSection>
            )}
          </div>
        </div>
        </div>
      </div>

      {/* ============ EDITOR DRAWER ============ */}
      <AnimatePresence>
        {editing && (
          <EditorDrawer
            key={editing}
            target={editing}
            resume={resume}
            onClose={() => setEditing(null)}
            onCommit={commit}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

/** Wrapper that shows a pencil on hover (desktop) or persistently (touch) and toggles editing.
 *  On touch devices, tapping anywhere inside the section also opens the editor. */
function EditableBlock({
  isEditing,
  onEdit,
  label,
  children,
  isTouch = false,
}: {
  isEditing: boolean;
  onEdit: () => void;
  label: string;
  children: React.ReactNode;
  isTouch?: boolean;
}) {
  return (
    <div
      className="group relative"
      style={{
        outline: isEditing ? "1pt dashed #0563C1" : isTouch ? "1pt dashed transparent" : "none",
        outlineOffset: "1mm",
        transition: "outline 0.15s",
        cursor: isTouch ? "pointer" : "default",
      }}
      // On touch devices, tapping anywhere in the block opens the editor.
      // On desktop, we keep the click target limited to the pencil FAB so users
      // can still select/copy text from the resume body.
      onClick={isTouch && !isEditing ? onEdit : undefined}
    >
      {children}
      {/* Pencil FAB — hidden only while editing (the editor modal takes over).
          On touch devices it is always visible; on desktop it appears on hover. */}
      {!isEditing && (
        <button
          onClick={(e) => {
            // Stop propagation so the touch-mode parent onClick doesn't fire twice.
            e.stopPropagation();
            onEdit();
          }}
          title={label}
          aria-label={label}
          className={
            "absolute top-0 right-0 w-7 h-7 rounded-full bg-brand text-white flex items-center justify-center transition shadow-glow hover:scale-110 z-10 " +
            (isTouch
              ? "opacity-100" // always visible on mobile
              : "opacity-0 group-hover:opacity-100") // hover-reveal on desktop
          }
          style={{ transform: "translate(35%, -35%)" }}
        >
          <Icon name="Pencil" className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  );
}

/** Infohas section header - per master layout:
 * Configured BOLD UPPERCASE color, no underline, compact spacing. */
function InfohasSection({ title, children }: { title: string; children: React.ReactNode }) {
  const config = useApp((s) => s.optimizerDirective);
  const titleColor = config?.sectionTitleColor || "#8B0000";
  const fontSize = config?.sectionTitleSizePt ? `${config.sectionTitleSizePt}pt` : "12pt";
  const sectionGap = config?.sectionGapMm ? `${config.sectionGapMm}mm` : "3mm";

  return (
    <section style={{ marginBottom: sectionGap }}>
      <h2
        style={{
          color: titleColor,
          fontWeight: 700,
          fontSize: fontSize,
          letterSpacing: "0.3pt",
          margin: "0 0 1mm 0",
          paddingBottom: 0,
          borderBottom: "none",
          textTransform: "uppercase",
          lineHeight: 1.2,
        }}
      >
        {title}
      </h2>
      <div style={{ fontSize: "inherit", lineHeight: 1.2 }}>{children}</div>
    </section>
  );
}

/** Section header for grouped experience/education entries - Configured bold UPPERCASE color */
function SectionDividerInline({ title }: { title: string }) {
  const config = useApp((s) => s.optimizerDirective);
  const titleColor = config?.sectionTitleColor || "#8B0000";
  const fontSize = config?.sectionTitleSizePt ? `${config.sectionTitleSizePt}pt` : "12pt";
  const sectionGap = config?.sectionGapMm ? `${config.sectionGapMm}mm` : "3mm";

  return (
    <h2
      style={{
        color: titleColor,
        fontWeight: 700,
        fontSize: fontSize,
        letterSpacing: "0.3pt",
        margin: `${sectionGap} 0 1mm 0` /* compact gap */,
        paddingBottom: 0,
        borderBottom: "none",
        textTransform: "uppercase",
        lineHeight: 1.2,
      }}
    >
      {title}
    </h2>
  );
}

/** Inline editor drawer — slides up from bottom on desktop, full-screen on mobile */
function EditorDrawer({ target, resume, onClose, onCommit }: {
  target: EditTarget;
  resume: ResumeData;
  onClose: () => void;
  onCommit: (p: Partial<ResumeData>) => void;
}) {
  // local form state — keyed by target so it resets when target changes (controlled via key prop from parent)
  const [form, setForm] = useState<ResumeData>(resume);

  const save = () => {
    if (target === "header") {
      onCommit({
        name: form.name,
        headline: form.headline,
        dateOfBirth: form.dateOfBirth,
        contact: { ...form.contact },
      });
    } else if (target === "summary") {
      onCommit({ summary: form.summary });
    } else if (target === "skills") {
      onCommit({ skills: form.skills });
    } else if (target?.startsWith("experience:")) {
      onCommit({ experience: form.experience });
    } else if (target?.startsWith("education:")) {
      onCommit({ education: form.education });
    } else if (target === "languages") {
      onCommit({ languages: form.languages });
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[80] bg-background/80 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4"
      onClick={onClose}
    >
      <motion.div
        initial={{ y: 60, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: 60, opacity: 0 }}
        transition={{ type: "spring", damping: 26, stiffness: 280 }}
        className="bg-card rounded-t-2xl sm:rounded-2xl border border-border shadow-premium w-full sm:max-w-2xl max-h-[88vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-card border-b border-border p-4 flex items-center justify-between">
          <h3 className="font-display font-bold text-lg flex items-center gap-2">
            <Icon name="Pencil" className="w-4 h-4 text-brand" />
            {target === "header" && "Edit header & contact"}
            {target === "summary" && "Edit professional summary"}
            {target === "skills" && "Edit core competencies & skills"}
            {target === "languages" && "Edit languages"}
            {target?.startsWith("experience:") && "Edit experience entry"}
            {target?.startsWith("education:") && "Edit education entry"}
          </h3>
          <button onClick={onClose} className="w-8 h-8 rounded-full hover:bg-secondary flex items-center justify-center" aria-label="Close">
            <Icon name="X" className="w-4 h-4" />
          </button>
        </div>

        <div className="p-5 space-y-4">
          {target === "header" && (
            <div className="space-y-3">
              <div className="grid sm:grid-cols-2 gap-3">
                <Field label="Full name"><Input value={form.name} onChange={(v) => setForm({ ...form, name: v })} /></Field>
                <Field label="Headline"><Input value={form.headline ?? ""} onChange={(v) => setForm({ ...form, headline: v })} /></Field>
                <Field label="Location"><Input value={form.contact.location ?? ""} onChange={(v) => setForm({ ...form, contact: { ...form.contact, location: v } })} /></Field>
                <Field label="Phone"><Input value={form.contact.phone ?? ""} onChange={(v) => setForm({ ...form, contact: { ...form.contact, phone: v } })} /></Field>
                <Field label="Email"><Input value={form.contact.email ?? ""} onChange={(v) => setForm({ ...form, contact: { ...form.contact, email: v } })} /></Field>
                <Field label="Date of birth (DD/MM/YYYY)"><Input value={form.dateOfBirth ?? ""} onChange={(v) => setForm({ ...form, dateOfBirth: v })} placeholder="10/01/2005" /></Field>
              </div>
            </div>
          )}

          {target === "summary" && (
            <Field label="Professional summary (60-90 words)">
              <TextArea
                value={form.summary ?? ""}
                onChange={(v) => setForm({ ...form, summary: v })}
                rows={8}
                placeholder="Ambitious Retail Sales Professional with..."
              />
              <p className="text-xs text-muted-foreground mt-1">{(form.summary ?? "").split(/\s+/).filter(Boolean).length} words</p>
            </Field>
          )}

          {target === "skills" && (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <Label className="text-xs uppercase text-muted-foreground">Skill groups (Category | comma-separated skills)</Label>
                <button
                  onClick={() => setForm({ ...form, skills: [...form.skills, { id: uid("s"), name: "New skill", category: "New category" }] })}
                  className="text-xs px-2 py-1 rounded bg-brand text-white hover:bg-brand-dark flex items-center gap-1"
                >
                  <Icon name="Plus" className="w-3 h-3" /> Add skill
                </button>
              </div>
              {groupSkillsByCategory(form.skills).map((g, gi) => (
                <div key={gi} className="rounded-lg border border-border p-3 space-y-2">
                  <div className="flex gap-2">
                    <Input
                      value={g.category}
                      onChange={(v) => {
                        const next = form.skills.map((s) => s.category === g.category ? { ...s, category: v } : s);
                        setForm({ ...form, skills: next });
                      }}
                      placeholder="Category"
                    />
                    <button
                      onClick={() => setForm({ ...form, skills: form.skills.filter((s) => s.category !== g.category) })}
                      className="text-destructive hover:bg-destructive/10 px-2 rounded"
                    >
                      <Icon name="Trash2" className="w-4 h-4" />
                    </button>
                  </div>
                  <Input
                    value={g.items.join(", ")}
                    onChange={(v) => {
                      const items = v.split(",").map((x) => x.trim()).filter(Boolean);
                      // Replace this category's items: remove all old, add new
                      const others = form.skills.filter((s) => s.category !== g.category);
                      const newSkills = items.map((name) => ({ id: uid("s"), name, category: g.category }));
                      setForm({ ...form, skills: [...others, ...newSkills] });
                    }}
                    placeholder="Skill 1, Skill 2, Skill 3"
                  />
                </div>
              ))}
            </div>
          )}

          {target?.startsWith("experience:") && (() => {
            const id = target.split(":")[1];
            const e = form.experience.find((x) => x.id === id);
            if (!e) return null;
            return (
              <div className="space-y-3">
                <div className="grid sm:grid-cols-2 gap-3">
                  <Field label="Job title"><Input value={e.title} onChange={(v) => setForm({ ...form, experience: form.experience.map((x) => x.id === id ? { ...x, title: v } : x) })} /></Field>
                  <Field label="Company"><Input value={e.company} onChange={(v) => setForm({ ...form, experience: form.experience.map((x) => x.id === id ? { ...x, company: v } : x) })} /></Field>
                  <Field label="Location"><Input value={e.location ?? ""} onChange={(v) => setForm({ ...form, experience: form.experience.map((x) => x.id === id ? { ...x, location: v } : x) })} /></Field>
                  <Field label="Start (Mon YYYY)"><Input value={e.startDate} onChange={(v) => setForm({ ...form, experience: form.experience.map((x) => x.id === id ? { ...x, startDate: v } : x) })} placeholder="May 2024" /></Field>
                  <Field label="End"><Input value={e.endDate} onChange={(v) => setForm({ ...form, experience: form.experience.map((x) => x.id === id ? { ...x, endDate: v } : x) })} placeholder="Oct 2024 or Present" /></Field>
                </div>
                <Field label="Achievement bullets (one per line — start with action verbs)">
                  <TextArea
                    value={e.bullets.join("\n")}
                    onChange={(v) => setForm({ ...form, experience: form.experience.map((x) => x.id === id ? { ...x, bullets: v.split("\n") } : x) })}
                    rows={6}
                  />
                </Field>
              </div>
            );
          })()}

          {target?.startsWith("education:") && (() => {
            const id = target.split(":")[1];
            const ed = form.education.find((x) => x.id === id);
            if (!ed) return null;
            return (
              <div className="space-y-3">
                <div className="grid sm:grid-cols-2 gap-3">
                  <Field label="Degree"><Input value={ed.degree} onChange={(v) => setForm({ ...form, education: form.education.map((x) => x.id === id ? { ...x, degree: v } : x) })} /></Field>
                  <Field label="Institution"><Input value={ed.institution} onChange={(v) => setForm({ ...form, education: form.education.map((x) => x.id === id ? { ...x, institution: v } : x) })} /></Field>
                  <Field label="Location"><Input value={ed.location ?? ""} onChange={(v) => setForm({ ...form, education: form.education.map((x) => x.id === id ? { ...x, location: v } : x) })} /></Field>
                  <Field label="Start"><Input value={ed.startDate} onChange={(v) => setForm({ ...form, education: form.education.map((x) => x.id === id ? { ...x, startDate: v } : x) })} placeholder="2024" /></Field>
                  <Field label="End"><Input value={ed.endDate} onChange={(v) => setForm({ ...form, education: form.education.map((x) => x.id === id ? { ...x, endDate: v } : x) })} placeholder="2025" /></Field>
                </div>
                <Field label="Modules (one line, comma-separated)">
                  <Input
                    value={(ed.highlights ?? []).join(", ").replace(/^Modules: /, "")}
                    onChange={(v) => setForm({ ...form, education: form.education.map((x) => x.id === id ? { ...x, highlights: v.trim() ? [`Modules: ${v.replace(/^Modules: /, "")}`] : [] } : x) })}
                    placeholder="Customer Service, CRM, Communication"
                  />
                </Field>
              </div>
            );
          })()}

          {target === "languages" && (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <Label className="text-xs uppercase text-muted-foreground">Languages</Label>
                <button
                  onClick={() => setForm({ ...form, languages: [...form.languages, { id: uid("l"), name: "New language", proficiency: "fluent" } as ResumeLanguage & { note?: string }] })}
                  className="text-xs px-2 py-1 rounded bg-brand text-white hover:bg-brand-dark flex items-center gap-1"
                >
                  <Icon name="Plus" className="w-3 h-3" /> Add
                </button>
              </div>
              {form.languages.map((l, i) => (
                <div key={l.id} className="grid grid-cols-[1fr_1fr_2fr_auto] gap-2">
                  <Input
                    value={l.name}
                    onChange={(v) => setForm({ ...form, languages: form.languages.map((x, j) => j === i ? { ...x, name: v } : x) })}
                    placeholder="English"
                  />
                  <select
                    value={l.proficiency}
                    onChange={(e) => setForm({ ...form, languages: form.languages.map((x, j) => j === i ? { ...x, proficiency: e.target.value as any } : x) })}
                    className="h-9 px-2 rounded-md border border-input bg-background text-sm"
                  >
                    <option value="basic">Basic</option>
                    <option value="conversational">Conversational</option>
                    <option value="fluent">Fluent</option>
                    <option value="native">Native</option>
                  </select>
                  <Input
                    value={(l as any).note ?? ""}
                    onChange={(v) => setForm({ ...form, languages: form.languages.map((x, j) => j === i ? { ...x, ...({ note: v } as any) } : x) })}
                    placeholder="Optional note (e.g. 'Effective written communication')"
                  />
                  <button
                    onClick={() => setForm({ ...form, languages: form.languages.filter((_, j) => j !== i) })}
                    className="text-destructive hover:bg-destructive/10 px-2 rounded"
                  >
                    <Icon name="Trash2" className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="sticky bottom-0 bg-card border-t border-border p-4 flex justify-end gap-2">
          <Button onClick={onClose} variant="outline">Cancel</Button>
          <Button onClick={save} className="bg-brand hover:bg-brand-dark text-white gap-2">
            <Icon name="Save" className="w-4 h-4" /> Save changes
          </Button>
        </div>
      </motion.div>
    </motion.div>
  );
}

/** Lightweight styled input + textarea primitives (avoid shadcn import juggling here) */
function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-xs uppercase tracking-wide text-muted-foreground">{label}</Label>
      {children}
    </div>
  );
}
function Label({ className, children }: { className?: string; children: React.ReactNode }) {
  return <label className={`block font-medium ${className ?? ""}`}>{children}</label>;
}
function Input({ value, onChange, placeholder }: { value: string; onChange: (v: string) => void; placeholder?: string }) {
  return (
    <input
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring"
    />
  );
}
function TextArea({ value, onChange, rows, placeholder }: { value: string; onChange: (v: string) => void; rows?: number; placeholder?: string }) {
  return (
    <textarea
      value={value}
      onChange={(e) => onChange(e.target.value)}
      rows={rows ?? 4}
      placeholder={placeholder}
      className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm resize-none focus:outline-none focus:ring-2 focus:ring-ring"
    />
  );
}
function Button({ children, onClick, variant, className }: { children: React.ReactNode; onClick?: () => void; variant?: "outline" | "default"; className?: string }) {
  return (
    <button
      onClick={onClick}
      className={`px-4 h-9 rounded-md text-sm font-medium transition ${
        variant === "outline"
          ? "border border-border bg-card hover:bg-secondary"
          : "bg-brand text-white hover:bg-brand-dark"
      } ${className ?? ""}`}
    >
      {children}
    </button>
  );
}

function groupSkillsByCategory(skills: ResumeData["skills"]): { category: string; items: string[] }[] {
  const map = new Map<string, string[]>();
  for (const s of skills) {
    const cat = s.category || "General";
    if (!map.has(cat)) map.set(cat, []);
    map.get(cat)!.push(s.name);
  }
  return Array.from(map.entries()).map(([category, items]) => ({ category, items }));
}

function fmtDateInfohas(d?: string): string {
  if (!d) return "";
  if (/present/i.test(d)) return "Present";
  const m = d.match(/^(\d{4})-(\d{2})$/);
  if (m) {
    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return `${months[parseInt(m[2]) - 1] ?? m[2]} ${m[1]}`;
  }
  if (/^\d{4}$/.test(d)) return d;
  return d;
}

src/components/resume/RenderDocumentPrev:
// ============================================================================
// RenderDocumentPreview — renders RenderDocument (SSOT) as React A4 preview
// ============================================================================
// This is the SINGLE SOURCE OF TRUTH preview component. It consumes the same
// RenderDocument that the DOCX and PDF export paths consume, ensuring EXACT
// parity between what the user sees and what they export.
//
// ALL renderers (Preview, DOCX, PDF) now share:
//   1. toRenderDocument(resume) → RenderDocument
//   2. RenderDocumentPreview | exportResumeDOCXRenderDoc | exportResumePDFRenderDoc
//
// No template-specific rendering logic. No per-template section ordering.
// ============================================================================

"use client";

import React from "react";
import type {
  RenderDocument,
  RenderContentItem,
  RenderDocumentSection,
  ResumeLayoutModel,
} from "@/lib/types";

// ── Props ─────────────────────────────────────────────────────────────────
export interface RenderDocumentPreviewProps {
  rd: RenderDocument;
  scale?: number;
  className?: string;
}

// ── Root Component ────────────────────────────────────────────────────────
export function RenderDocumentPreview({
  rd,
  scale = 1,
  className,
}: RenderDocumentPreviewProps) {
  const L = rd.layout;
  const accentColor = L.sectionTitleColor || "#8B0000";
  const bodyColor = L.bodyTextColor || "#000000";

  const scaledWidthMm = 210 * scale;
  const scaledHeightMm = 297 * scale;

  const contentRef = React.useRef<HTMLDivElement>(null);
  const [overflows, setOverflows] = React.useState(false);
  const [fillPercent, setFillPercent] = React.useState(0);

  React.useEffect(() => {
    const el = contentRef.current;
    if (!el) return;

    const checkHeight = () => {
      const a4HeightPx = 297 * 3.7795275591;
      const actualHeight = el.scrollHeight || el.clientHeight || el.offsetHeight;
      const percent = (actualHeight / a4HeightPx) * 100;
      setFillPercent(Math.round(percent));
      setOverflows(actualHeight > a4HeightPx + 2); // 2px tolerance
    };

    checkHeight();
    const observer = new MutationObserver(checkHeight);
    observer.observe(el, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, [rd]);

  return (
    <div
      style={{
        width: `${scaledWidthMm}mm`,
        height: `${scaledHeightMm}mm`,
        position: "relative",
        overflow: "hidden",
      }}
    >
      <div
        ref={contentRef}
        className={`origin-top-left ${className ?? ""}`}
        style={{
          transform: `scale(${scale})`,
          transformOrigin: "top left",
          position: "absolute",
          top: 0,
          left: 0,
          width: "210mm",
          minHeight: "297mm",
          fontFamily: L.fontFamily || "'Times New Roman', serif",
          fontSize: `${L.bodyFontSizePt}pt`,
          lineHeight: L.lineHeightMm || 1.2,
          color: bodyColor,
          padding: `${L.marginTopMm}mm ${L.marginRightMm}mm ${L.marginBottomMm}mm ${L.marginLeftMm}mm`,
          backgroundColor: "#fff",
        }}
      >
        {/* ============ CONTACT BLOCK ============ */}
        <RenderContactBlock contact={rd.contact} layout={L} />

        {/* ============ SECTIONS ============ */}
        {rd.sections.map((section, idx) => (
          <RenderSection
            key={`${section.type}-${idx}`}
            section={section}
            layout={L}
            accentColor={accentColor}
          />
        ))}

        {/* ============ Page-Break Indicator Line ============ */}
        {overflows && (
          <div
            style={{
              position: "absolute",
              top: "297mm",
              left: 0,
              width: "100%",
              borderTop: "2px dashed #EF4444",
              zIndex: 49,
              pointerEvents: "none",
            }}
          />
        )}
      </div>

      {/* ============ Interactive Overflows Warning Badge ============ */}
      {overflows && (
        <div
          style={{
            position: "absolute",
            bottom: "8px",
            left: "50%",
            transform: "translateX(-50%)",
            backgroundColor: "rgba(239, 68, 68, 0.95)",
            color: "white",
            fontSize: "11px",
            fontWeight: "bold",
            padding: "4px 10px",
            borderRadius: "9999px",
            boxShadow: "0 4px 12px rgba(0, 0, 0, 0.15)",
            zIndex: 50,
            pointerEvents: "none",
            border: "1px solid rgb(248, 113, 113)",
            fontFamily: "sans-serif",
          }}
        >
          ⚠️ OVERFLOWS PAGE ({fillPercent}%)
        </div>
      )}
      {!overflows && fillPercent > 90 && (
        <div
          style={{
            position: "absolute",
            bottom: "8px",
            left: "50%",
            transform: "translateX(-50%)",
            backgroundColor: "rgba(245, 158, 11, 0.95)",
            color: "white",
            fontSize: "11px",
            fontWeight: "bold",
            padding: "4px 10px",
            borderRadius: "9999px",
            boxShadow: "0 4px 12px rgba(0, 0, 0, 0.15)",
            zIndex: 50,
            pointerEvents: "none",
            border: "1px solid rgb(251, 191, 36)",
            fontFamily: "sans-serif",
          }}
        >
          📏 FITS PAGE ({fillPercent}%)
        </div>
      )}
    </div>
  );
}

// ── Contact Block ─────────────────────────────────────────────────────────
function RenderContactBlock({
  contact,
  layout: L,
}: {
  contact: RenderDocument["contact"];
  layout: ResumeLayoutModel;
}) {
  const nameColor = L.nameColor || "#8B0000";
  const contactColor = L.contactColor || "#000000";
  const bodyColor = L.bodyTextColor || "#000000";
  const sectionGapMm = L.sectionGapMm ?? 3;

  return (
    <div style={{ marginBottom: `${sectionGapMm}mm` }}>
      {/* Name */}
      <h1
        style={{
          fontSize: `${L.nameSizePt}pt`,
          fontWeight: "bold",
          color: nameColor,
          textTransform: "uppercase",
          margin: 0,
          marginBottom: "2mm",
          letterSpacing: "0.5pt",
        }}
      >
        {contact.name || "YOUR NAME"}
      </h1>

      {/* Headline */}
      {contact.headline && (
        <p
          style={{
            margin: 0,
            marginBottom: "1mm",
            fontSize: `${L.bodyFontSizePt}pt`,
            color: bodyColor,
          }}
        >
          {contact.headline}
        </p>
      )}

      {/* Contact line */}
      <ContactLine contact={contact} color={contactColor} fontSize={L.bodyFontSizePt} />

      {/* Date of birth */}
      {contact.dateOfBirth && (
        <p
          style={{
            margin: 0,
            marginBottom: "0.5mm",
            fontSize: `${L.bodyFontSizePt}pt`,
            color: bodyColor,
          }}
        >
          Date Of Birth: {contact.dateOfBirth}
        </p>
      )}

      {/* Personal details */}
      {contact.personalDetails && renderPersonalDetails(contact.personalDetails, L.bodyFontSizePt, bodyColor)}
    </div>
  );
}

function ContactLine({
  contact,
  color,
  fontSize,
}: {
  contact: RenderDocument["contact"];
  color: string;
  fontSize: number;
}) {
  const parts: string[] = [];
  if (contact.phone) parts.push(contact.phone);
  if (contact.email) parts.push(contact.email);
  if (contact.location) parts.push(contact.location);
  if (parts.length === 0) return null;

  return (
    <p
      style={{
        margin: 0,
        marginBottom: "0.5mm",
        fontSize: `${fontSize}pt`,
        color,
      }}
    >
      {parts.join(" | ")}
    </p>
  );
}

function renderPersonalDetails(
  pd: Record<string, string>,
  fontSize: number,
  color: string,
): React.ReactNode {
  const entries = Object.entries(pd).filter(([, v]) => v?.trim());
  if (entries.length === 0) return null;

  return (
    <div>
      {entries.map(([label, value]) => (
        <p
          key={label}
          style={{
            margin: 0,
            marginBottom: "0.3mm",
            fontSize: `${fontSize}pt`,
            color,
          }}
        >
          {`${label.charAt(0).toUpperCase() + label.slice(1)} : ${value}`}
        </p>
      ))}
    </div>
  );
}

// ── Section ───────────────────────────────────────────────────────────────
function RenderSection({
  section,
  layout: L,
  accentColor,
}: {
  section: RenderDocumentSection;
  layout: ResumeLayoutModel;
  accentColor: string;
}) {
  const sectionGapMm = L.sectionGapMm ?? 3;
  const bodyColor = L.bodyTextColor || "#000000";

  return (
    <div style={{ marginBottom: `${sectionGapMm}mm` }}>
      {/* Section title */}
      {section.title && (
        <>
          <h2
            style={{
              fontSize: `${L.sectionTitleSizePt}pt`,
              fontWeight: "bold",
              color: accentColor,
              textTransform: "uppercase",
              margin: 0,
              marginBottom: "1mm",
              letterSpacing: "0.3pt",
            }}
          >
            {section.title}
          </h2>
          <hr
            style={{
              border: "none",
              borderTop: `1pt solid ${accentColor}`,
              margin: 0,
              marginBottom: "2mm",
            }}
          />
        </>
      )}

      {/* Section items */}
      {section.items.map((item, idx) => (
        <RenderContentItem
          key={idx}
          item={item}
          fontSize={L.bodyFontSizePt}
          color={bodyColor}
          accentColor={accentColor}
        />
      ))}
    </div>
  );
}

// ── Content Item Renderer ─────────────────────────────────────────────────
function RenderContentItem({
  item,
  fontSize,
  color,
  accentColor,
}: {
  item: RenderContentItem;
  fontSize: number;
  color: string;
  accentColor: string;
}) {
  switch (item.kind) {
    case "text":
      return (
        <p
          style={{
            margin: 0,
            marginBottom: "0.8mm",
            fontSize: `${fontSize}pt`,
            color,
            fontWeight: item.bold ? "bold" : "normal",
          }}
        >
          {item.text}
        </p>
      );

    case "bullets":
      return (
        <ul
          style={{
            margin: 0,
            marginBottom: "0.8mm",
            paddingLeft: `${fontSize * 1.2}pt`,
            listStyle: (item.level ?? 0) > 0 ? "circle" : "disc",
          }}
        >
          {item.bullets.map((b, i) => (
            <li
              key={i}
              style={{
                fontSize: `${fontSize}pt`,
                color,
                marginBottom: "0.5mm",
                lineHeight: 1.3,
              }}
            >
              {b}
            </li>
          ))}
        </ul>
      );

    case "table-row":
      return (
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "baseline",
            marginBottom: "0.5mm",
            width: "100%",
          }}
        >
          <span
            style={{
              fontWeight: item.cells?.[0]?.bold ? "bold" : "normal",
              fontSize: `${fontSize}pt`,
              color,
              textAlign: item.cells?.[0]?.align || "left",
            }}
          >
            {item.cells?.[0]?.text || ""}
          </span>
          <span
            style={{
              fontWeight: item.cells?.[1]?.bold ? "bold" : "normal",
              fontSize: `${fontSize}pt`,
              color,
              textAlign: item.cells?.[1]?.align || "right",
              whiteSpace: "nowrap",
              marginLeft: "4mm",
            }}
          >
            {item.cells?.[1]?.text || ""}
          </span>
        </div>
      );

    case "nested-bullets":
      return (
        <div style={{ marginBottom: "0.8mm" }}>
          {item.groups.map((group, gi) => (
            <p
              key={gi}
              style={{
                margin: 0,
                marginBottom: "0.5mm",
                fontSize: `${fontSize}pt`,
                color,
              }}
            >
              <span style={{ fontWeight: "bold" }}>{group.label}: </span>
              {group.items.join(", ")}
            </p>
          ))}
        </div>
      );

    default:
      return null;
  }
}

"use client";

// ============================================================================
// RenderNodePreview — renders RenderNode[] as A4 preview
// ============================================================================
// Consumes the RenderNode tree (the SSOT) directly. Every renderer uses the
// same tree — Preview, DOCX, PDF, HTML, TXT all see identical content.

import React from "react";
import type { RenderNode } from "@/lib/document-render-tree/types";

interface RenderNodePreviewProps {
  nodes: RenderNode[];
  className?: string;
  style?: React.CSSProperties;
}

/**
 * Render a single RenderNode to its visual representation.
 */
function RenderNodeElement({
  node,
  depth = 0,
}: {
  node: RenderNode;
  depth?: number;
}) {
  if (node.visibility === "hidden" || node.visibility === "collapsed") {
    return null;
  }

  const baseStyle: React.CSSProperties = {
    fontFamily: node.style.fontFamily || undefined,
    fontSize: node.style.fontSizePt ? `${node.style.fontSizePt}pt` : undefined,
    fontWeight: node.style.bold ? "bold" : undefined,
    fontStyle: node.style.italic ? "italic" : undefined,
    color: node.style.color || undefined,
    backgroundColor: node.style.backgroundColor || undefined,
    textAlign: node.style.textAlign || undefined,
    paddingTop: node.style.paddingTopMm ? `${node.style.paddingTopMm}mm` : undefined,
    paddingBottom: node.style.paddingBottomMm ? `${node.style.paddingBottomMm}mm` : undefined,
    paddingLeft: node.style.paddingLeftMm ? `${node.style.paddingLeftMm}mm` : undefined,
    paddingRight: node.style.paddingRightMm ? `${node.style.paddingRightMm}mm` : undefined,
    marginTop: node.style.marginTopMm ? `${node.style.marginTopMm}mm` : undefined,
    marginBottom: node.style.marginBottomMm ? `${node.style.marginBottomMm}mm` : undefined,
    marginLeft: node.style.marginLeftMm ? `${node.style.marginLeftMm}mm` : undefined,
    marginRight: node.style.marginRightMm ? `${node.style.marginRightMm}mm` : undefined,
  };

  switch (node.type) {
    case "document":
      return (
        <div
          style={{
            ...baseStyle,
            width: "210mm",
            minHeight: "297mm",
            padding: "6.35mm 8.89mm",
          }}
        >
          {node.children.length > 0
            ? node.children.map((child) => (
                <RenderNodeElement key={child.id} node={child} depth={depth} />
              ))
            : null}
        </div>
      );

    case "section-title":
      return (
        <div
          style={{
            ...baseStyle,
            fontSize: "11pt",
            fontWeight: "bold",
            textTransform: "uppercase",
            letterSpacing: "0.5px",
            borderBottom: "1px solid #2c3e50",
            paddingBottom: "0.5mm",
            marginTop: "3mm",
            marginBottom: "1mm",
          }}
        >
          {node.content}
        </div>
      );

    case "contact-line":
      return (
        <div style={baseStyle}>
          {node.content}
        </div>
      );

    case "text-line":
      return (
        <p style={{ ...baseStyle, margin: 0 }}>
          {node.content}
        </p>
      );

    case "bullet-item":
      return (
        <div
          style={{
            ...baseStyle,
            display: "flex",
            flexDirection: "row",
            alignItems: "flex-start",
            gap: "3mm",
            paddingLeft: node.style.paddingLeftMm
              ? `${node.style.paddingLeftMm}mm`
              : "6.4mm",
          }}
        >
          <span style={{ flexShrink: 0 }}>•</span>
          <span>{node.content}</span>
        </div>
      );

    case "table-row":
    case "table-cell":
      // Table cells from the same row are grouped by parentId
      return (
        <div style={baseStyle}>
          {node.content}
        </div>
      );

    case "nested-group-label":
      return (
        <div
          style={{
            ...baseStyle,
            fontWeight: "bold",
            marginTop: "1mm",
            marginBottom: "0.5mm",
          }}
        >
          {node.content}
        </div>
      );

    case "nested-group-item":
      return (
        <div
          style={{
            ...baseStyle,
            paddingLeft: node.style.paddingLeftMm
              ? `${node.style.paddingLeftMm}mm`
              : "6.4mm",
          }}
        >
          • {node.content}
        </div>
      );

    case "divider":
      return (
        <div
          style={{
            ...baseStyle,
            borderTop: node.style.borderBottom || "0.5px solid #ccc",
            marginTop: baseStyle.marginTop || "1.5mm",
            marginBottom: baseStyle.marginBottom || "1.5mm",
          }}
        />
      );

    default:
      return (
        <div style={baseStyle}>
          {node.content}
          {node.children.length > 0
            ? node.children.map((child) => (
                <RenderNodeElement key={child.id} node={child} depth={depth + 1} />
              ))
            : null}
        </div>
      );
  }
}

/**
 * RenderNodePreview — renders the full RenderNode tree as an A4 preview.
 */
export function RenderNodePreview({
  nodes,
  className,
  style,
}: RenderNodePreviewProps) {
  if (!nodes || nodes.length === 0) {
    return (
      <div className={className} style={{ padding: "20px", color: "#999" }}>
        No content to render
      </div>
    );
  }

  // Find document root or render all nodes as a document
  const docRoot = nodes.find((n) => n.type === "document");

  if (docRoot) {
    // Render children of document root
    return (
      <div className={className} style={style}>
        <div
          style={{
            width: "210mm",
            minHeight: "297mm",
            padding: `${docRoot.style.marginTopMm || 6.35}mm ${docRoot.style.marginRightMm || 8.89}mm`,
            backgroundColor: docRoot.style.backgroundColor || "#fff",
            fontFamily: docRoot.style.fontFamily || "Calibri, sans-serif",
            fontSize: docRoot.style.fontSizePt ? `${docRoot.style.fontSizePt}pt` : "10pt",
            color: docRoot.style.color || "#000",
            lineHeight: 1.15,
            margin: "0 auto",
            boxShadow: "0 1px 4px rgba(0,0,0,0.15)",
          }}
        >
          {docRoot.children.map((child) => (
            <RenderNodeElement key={child.id} node={child} />
          ))}
        </div>
      </div>
    );
  }

  // Fallback: render all nodes flat
  return (
    <div className={className} style={style}>
      <div
        style={{
          width: "210mm",
          minHeight: "297mm",
          padding: "6.35mm 8.89mm",
          backgroundColor: "#fff",
          fontFamily: "Calibri, sans-serif",
          fontSize: "10pt",
          lineHeight: 1.15,
          margin: "0 auto",
          boxShadow: "0 1px 4px rgba(0,0,0,0.15)",
        }}
      >
        {nodes.map((node) => (
          <RenderNodeElement key={node.id} node={node} />
        ))}
      </div>
    </div>
  );
}

src/components/shared/ATSScorePreview.ts:
"use client";

import { useState, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Badge, Icon } from "@/components/shared";
import { Button } from "@/components/ui/button";
import { Card, CardHeader, CardContent } from "@/components/ui/card";
import type { ResumeData, JobDescription } from "@/lib/types";
import { computeATSReadiness } from "@/components/optimizer/ATSScoreSimulator";

interface Props {
  resume: ResumeData;
  jd?: JobDescription | null;
  onAddKeyword?: (keyword: string, section: string) => void;
}

interface SectionFeedback {
  name: string;
  score: number;
  missingKeywords: string[];
  suggestions: string[];
}

function cn(...classes: (string | false | undefined | null)[]): string {
  return classes.filter(Boolean).join(" ");
}

export function ATSScoreInline({ resume, jd, onAddKeyword }: Props) {
  const [expanded, setExpanded] = useState(false);

  const score = useMemo(() => {
    if (!jd) return null;
    return computeATSReadiness(resume, jd);
  }, [resume, jd]);

  const sections: SectionFeedback[] = useMemo(() => {
    if (!score) return [];

    const summaryText = (resume.summary || "").toLowerCase();
    const skillsText = (resume.skills || []).map((s) => s.name).join(" ").toLowerCase();
    const expText = (resume.experience || []).flatMap((e) => e.bullets).join(" ").toLowerCase();

    const allKeywords = score.missingKeywords || [];

    return [
      {
        name: "Summary",
        score: score.sectionBreakdown?.summary?.score ?? 50,
        missingKeywords: allKeywords.filter((kw) => !summaryText.includes(kw.toLowerCase())).slice(0, 4),
        suggestions: score.sectionBreakdown?.summary?.suggestion ? [score.sectionBreakdown.summary.suggestion] : [],
      },
      {
        name: "Skills",
        score: score.sectionBreakdown?.skills?.score ?? 50,
        missingKeywords: allKeywords.filter((kw) => !skillsText.includes(kw.toLowerCase())).slice(0, 4),
        suggestions: score.sectionBreakdown?.skills?.suggestion ? [score.sectionBreakdown.skills.suggestion] : [],
      },
      {
        name: "Experience",
        score: score.sectionBreakdown?.experience?.score ?? 50,
        missingKeywords: allKeywords.filter((kw) => !expText.includes(kw.toLowerCase())).slice(0, 4),
        suggestions: score.sectionBreakdown?.experience?.suggestion ? [score.sectionBreakdown.experience.suggestion] : [],
      },
    ];
  }, [score, resume]);

  const hasJd = !!jd;
  const overall = score?.readinessScore ?? null;

  const scoreColor =
    overall !== null
      ? overall >= 80
        ? "text-emerald-600"
        : overall >= 50
          ? "text-amber-600"
          : "text-red-600"
      : "text-muted-foreground";

  if (!hasJd) return null;

  return (
    <Card className="border-muted mb-2">
      <CardHeader className="p-2.5 pb-1.5 flex flex-row items-center justify-between gap-2 cursor-pointer" onClick={() => setExpanded((v) => !v)}>
        <div className="flex items-center gap-2">
          <Icon name="Target" className="w-3.5 h-3.5 text-brand" />
          <span className="text-xs font-semibold flex items-center gap-1.5">
            ATS Score
            {overall !== null && (
              <span className={cn("text-sm", scoreColor)}>{overall}</span>
            )}
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          {overall !== null && overall >= 80 ? (
            <Badge variant="success" className="text-[9px] h-4">Excellent</Badge>
          ) : overall !== null && overall >= 50 ? (
            <Badge variant="warning" className="text-[9px] h-4">Needs Work</Badge>
          ) : overall !== null ? (
            <Badge variant="danger" className="text-[9px] h-4">Critical</Badge>
          ) : null}
          <button className="text-muted-foreground hover:text-foreground transition" aria-label={expanded ? "Collapse" : "Expand"}>
            <Icon name={expanded ? "ChevronUp" : "ChevronDown"} className="w-3 h-3" />
          </button>
        </div>
      </CardHeader>

      <AnimatePresence>
        {expanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden"
          >
            <CardContent className="p-2.5 pt-0 space-y-2">
              {sections.map((section) => (
                <div key={section.name}>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[10px] font-medium flex-1">{section.name}</span>
                    <div className="w-16 h-1.5 rounded-full bg-secondary overflow-hidden">
                      <div
                        className={cn(
                          "h-full rounded-full transition-all",
                          section.score >= 80
                            ? "bg-emerald-500"
                            : section.score >= 50
                              ? "bg-amber-400"
                              : "bg-red-400"
                        )}
                        style={{ width: `${Math.min(section.score, 100)}%` }}
                      />
                    </div>
                    <span
                      className={cn(
                        "text-[10px] font-semibold w-5 text-right",
                        section.score >= 80
                          ? "text-emerald-600"
                          : section.score >= 50
                            ? "text-amber-600"
                            : "text-red-600"
                      )}
                    >
                      {section.score}
                    </span>
                  </div>

                  {/* Actionable keyword chips */}
                  {section.missingKeywords.length > 0 && (
                    <div className="flex flex-wrap gap-1 ml-1">
                      {section.missingKeywords.map((kw) => (
                        <button
                          key={kw}
                          onClick={() => onAddKeyword?.(kw, section.name)}
                          className="text-[9px] px-1.5 py-0.5 rounded bg-amber-50 text-amber-700 border border-amber-200 
                            hover:bg-amber-100 hover:border-amber-300 transition-colors flex items-center gap-0.5"
                          title={`Add "${kw}" to ${section.name}`}
                        >
                          <Icon name="Plus" className="w-2 h-2" />
                          {kw}
                        </button>
                      ))}
                    </div>
                  )}

                  {/* Suggestions */}
                  {section.suggestions.length > 0 && (
                    <div className="text-[10px] text-muted-foreground flex gap-1 items-start ml-1">
                      <Icon name="Lightbulb" className="w-2.5 h-2.5 text-amber-500 shrink-0 mt-0.5" />
                      <span>{section.suggestions[0]}</span>
                    </div>
                  )}
                </div>
              ))}

              {/* Overall missing keywords summary */}
              {score && score.missingKeywords.length > 0 && (
                <div className="pt-1.5 border-t border-border/40">
                  <div className="text-[9px] uppercase tracking-wider text-muted-foreground mb-1">
                    All missing ({score.missingKeywords.length})
                  </div>
                  <div className="flex flex-wrap gap-1">
                    {score.missingKeywords.slice(0, 12).map((kw) => (
                      <button
                        key={kw}
                        onClick={() => onAddKeyword?.(kw, "Summary")}
                        className="text-[9px] px-1.5 py-0.5 rounded bg-red-50 text-red-600 border border-red-200
                          hover:bg-red-100 transition-colors"
                        title={`Add "${kw}" to Summary`}
                      >
                        {kw}
                      </button>
                    ))}
                    {score.missingKeywords.length > 12 && (
                      <span className="text-[9px] text-muted-foreground px-1 py-0.5">
                        +{score.missingKeywords.length - 12} more
                      </span>
                    )}
                  </div>
                </div>
              )}
            </CardContent>
          </motion.div>
        )}
      </AnimatePresence>
    </Card>
  );
}

src/components/shared/ErrorBoundary.tsx:
"use client";

import { Component, type ReactNode, type ErrorInfo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/shared";

// ============================================================================
// Types
// ============================================================================

export interface ErrorBoundaryProps {
  children: ReactNode;
  /** Human-friendly label for the crashed section (default: "This section") */
  label?: string;
  /** Optional custom fallback — overrides the default error UI */
  fallback?: ReactNode | ((error: Error, retry: () => void) => ReactNode);
  /** Called when an error is caught (for logging, telemetry, etc.) */
  onError?: (error: Error, info: ErrorInfo) => void;
  /** Reset the boundary when this key changes (useful for async data) */
  resetKey?: string | number | null;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

// ============================================================================
// Error Boundary Component
// ============================================================================

/**
 * ErrorBoundary — catches render crashes and shows a graceful fallback.
 *
 * Features:
 * - Animated fallback with icon + retry + details
 * - Auto-tracks resetKey for data-driven resets
 * - Optional `onError` callback for logging/reporting
 * - Custom fallback override (ReactNode or render function)
 * - Keyboard accessible (Retry on Enter when focused)
 *
 * Usage:
 *   <ErrorBoundary label="Builder">
 *     <Builder />
 *   </ErrorBoundary>
 */
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.warn(`[ErrorBoundary${this.props.label ? `: ${this.props.label}` : ""}]`, error, info);
    this.props.onError?.(error, info);
  }

  /** Reset the boundary from outside (via resetKey) */
  componentDidUpdate(prevProps: ErrorBoundaryProps) {
    if (
      this.state.hasError &&
      this.props.resetKey !== undefined &&
      this.props.resetKey !== prevProps.resetKey
    ) {
      this.reset();
    }
  }

  reset = () => {
    this.setState({ hasError: false, error: null });
  };

  /** Reload the entire module (more aggressive than retry) */
  handleReload = () => {
    // Clear any lingering state and force a fresh render
    this.reset();
    // If the error was in a data-dependent section, a full page reload
    // is the nuclear option — but we only do that after 3 failed retries.
    // For now, resetting the boundary is enough.
  };

  /** Report the error for diagnostics */
  reportError = () => {
    const label = this.props.label ?? "section";
    const errorMsg = this.state.error?.message ?? "Unknown error";
    // In production, this would POST to a telemetry endpoint
    console.info(`[ErrorBoundary] Reported: ${label} — ${errorMsg}`);
    // Fallback: copy error to clipboard for user bug reports
    const reportText = [
      `Error in: ${label}`,
      `Time: ${new Date().toISOString()}`,
      `Message: ${errorMsg}`,
      `Stack: ${this.state.error?.stack ?? "N/A"}`,
      `User Agent: ${navigator.userAgent}`,
    ].join("\n");
    navigator.clipboard.writeText(reportText).catch(() => {});
  };

  render() {
    if (!this.state.hasError) return this.props.children;

    const label = this.props.label ?? "This section";

    // Custom fallback (render function or node)
    if (this.props.fallback) {
      if (typeof this.props.fallback === "function") {
        return this.props.fallback(this.state.error!, this.reset);
      }
      return this.props.fallback;
    }

    return (
      <AnimatePresence mode="wait">
        <motion.div
          key="error"
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -4 }}
          transition={{ duration: 0.2 }}
          className="rounded-xl border border-destructive/30 bg-destructive/5 dark:bg-destructive/10 p-6"
        >
          {/* Error icon + header */}
          <div className="flex items-start gap-4">
            <div className="w-10 h-10 rounded-full bg-destructive/10 flex items-center justify-center shrink-0">
              <Icon name="AlertTriangle" className="w-5 h-5 text-destructive" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-display font-bold text-base text-foreground">
                {label} encountered an issue
              </h3>
              <p className="text-sm text-muted-foreground mt-1">
                Something unexpected happened while rendering this section.
                This is usually transient — a retry often resolves it.
              </p>
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex flex-wrap items-center gap-2 mt-4">
            <Button
              variant="default"
              size="sm"
              className="gap-1.5"
              onClick={this.reset}
            >
              <Icon name="RefreshCw" className="w-3.5 h-3.5" />
              Retry
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="gap-1.5"
              onClick={this.handleReload}
            >
              <Icon name="RotateCcw" className="w-3.5 h-3.5" />
              Reload module
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="gap-1.5"
              onClick={this.reportError}
            >
              <Icon name="Bug" className="w-3.5 h-3.5" />
              Report issue
            </Button>
          </div>

          {/* Error details (expandable) */}
          {this.state.error && (
            <details className="mt-4 group">
              <summary className="text-xs text-muted-foreground cursor-pointer hover:text-foreground transition-colors select-none">
                <Icon name="ChevronRight" className="w-3 h-3 inline mr-1 group-open:rotate-90 transition-transform" />
                Technical details
              </summary>
              <pre className="mt-2 p-3 rounded-lg bg-muted/60 text-[10px] leading-relaxed text-muted-foreground overflow-auto max-h-48 whitespace-pre-wrap break-all font-mono">
                {this.state.error.message}
                {"\n\n"}
                {this.state.error.stack}
              </pre>
            </details>
          )}
        </motion.div>
      </AnimatePresence>
    );
  }
}

src/components/shared/GlobalErrorCatcher:
"use client";

import { useEffect, useRef } from "react";
import { toast } from "sonner";
import { Icon } from "@/components/shared";
import { Button } from "@/components/ui/button";

/**
 * GlobalErrorCatcher — intercepts unhandled promise rejections and window
 * errors that fall through React's error boundaries, showing a non-blocking
 * toast so the user knows something happened without losing their work.
 *
 * Mount once at the app shell level. Errors are logged to console for
 * diagnostics but don't crash the entire UI.
 */
export function GlobalErrorCatcher() {
  const installed = useRef(false);

  useEffect(() => {
    if (installed.current) return;
    installed.current = true;

    const handleRejection = (event: PromiseRejectionEvent) => {
      const reason = event.reason;
      const message =
        reason instanceof Error ? reason.message : String(reason);

      console.warn("[GlobalErrorCatcher] Unhandled promise rejection:", reason);

      // Don't spam the user with too many toasts
      // Only show for meaningful (non-abort) errors
      if (
        message &&
        !message.includes("abort") &&
        !message.includes("AbortError")
      ) {
        toast.error("A background operation failed", {
          description: message.slice(0, 120),
          duration: 4000,
          action: {
            label: "Dismiss",
            onClick: () => {},
          },
        });
      }

      // Prevent default browser "Unhandled Promise Rejection" console noise
      // (we already logged it ourselves)
      event.preventDefault();
    };

    const handleError = (event: ErrorEvent) => {
      // Ignore extension errors and browser-internal noise
      if (!event.filename || event.filename.includes("extensions")) return;

      console.warn("[GlobalErrorCatcher] Uncaught error:", event.error ?? event.message);
    };

    window.addEventListener("unhandledrejection", handleRejection);
    window.addEventListener("error", handleError);

    return () => {
      window.removeEventListener("unhandledrejection", handleRejection);
      window.removeEventListener("error", handleError);
    };
  }, []);

  // This component renders nothing
  return null;
}

