"use client";

import { useState, useRef, useCallback, useEffect } from "react";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { toast } from "sonner";
import type { ResumeData } from "@/lib/types";

interface SmartTextareaProps {
  value: string;
  onChange: (value: string) => void;
  section: "summary" | "bullet" | "skill" | "education" | "language";
  placeholder?: string;
  className?: string;
  resume?: ResumeData | null;
  jobDescriptionText?: string;
  context?: string;
  rows?: number;
  disabled?: boolean;
}

type SuggestStatus = "idle" | "loading" | "error";

function sectionLabel(s: string) {
  const m: Record<string,string> = { summary:"Summary", bullet:"Bullet", skill:"Skill", education:"Education", language:"Language" };
  return m[s]||s;
}

/**
 * Build a context snippet for AI prompts — resume name, current role, JD keywords.
 */
function buildContext(resume?: ResumeData | null, jdText?: string): string {
  const parts: string[] = [];
  if (resume?.name) parts.push(`Candidate: ${resume.name}`);
  if (resume?.headline) parts.push(`Target role: ${resume.headline}`);
  if (resume?.summary) parts.push(`Current summary (context): ${resume.summary.slice(0, 200)}`);
  if (resume?.experience?.[0]) {
    const e = resume.experience[0];
    parts.push(`Recent role: ${e.title} at ${e.company}`);
    if (e.bullets.length > 0) parts.push(`Existing bullets: ${e.bullets.slice(0, 3).join(" | ")}`);
  }
  if (jdText) parts.push(`Job description keywords: ${jdText.slice(0, 300)}`);
  return parts.join("\n");
}

export function SmartTextarea({ value, onChange, section, placeholder, className, resume, jobDescriptionText, context, rows=3, disabled }: SmartTextareaProps) {
  const [suggestion, setSuggestion] = useState("");
  const [variants, setVariants] = useState<string[]>([]);
  const [currentVariant, setCurrentVariant] = useState(0);
  const [status, setStatus] = useState<SuggestStatus>("idle");
  const [showPopover, setShowPopover] = useState(false);
  const debRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const textareaRef = useRef<HTMLDivElement>(null);

  // Build full context for AI prompts
  const ctxMemo = buildContext(resume, jobDescriptionText);

  const callAI = async (prompt: string) => {
    try {
      const { ProviderRouter } = await import("@/lib/ai/services/router");
      const r = await ProviderRouter.chat({
        messages: [
          { role: "system", content: "You are a professional resume writer. Return ONLY the requested text." },
          { role: "user", content: prompt },
        ], maxTokens: 200, temperature: 0.7,
      }, { agentTask: "summary" });
      return (r.text||"").replace(/^["']|["']$/g,"").trim();
    } catch { return ""; }
  };

  /**
   * Fetch multiple suggestion variants from the AI.
   */
  const fetchVariants = useCallback(async (text: string, count = 3): Promise<string[]> => {
    const prompt = ctxMemo
      ? `Context:\n${ctxMemo}\n\n`
      : "";
    if (section === "summary") {
      return callAI(
        prompt + `I need to complete this resume summary: "${text}". ` +
        `Suggest ${count} different completions (15-25 words each) that are impactful and keyword-rich. ` +
        `Return as a JSON array of strings, NO markdown, NO numbering.`
      ).then(r => {
        try { const arr = JSON.parse(r); return Array.isArray(arr) ? arr.slice(0, count) : [r]; }
        catch { return r ? [r] : []; }
      });
    }
    if (section === "bullet") {
      return callAI(
        prompt + `I need to complete this resume bullet point: "${text}". ` +
        `Suggest ${count} different completions (10-20 words each) starting with an action verb. ` +
        `Return as a JSON array of strings, NO markdown, NO numbering.`
      ).then(r => {
        try { const arr = JSON.parse(r); return Array.isArray(arr) ? arr.slice(0, count) : [r]; }
        catch { return r ? [r] : []; }
      });
    }
    return callAI(
      `Complete this ${section} entry: "${text}". ` +
      `Suggest ${count} short completions. ` +
      `Return as a JSON array of strings, NO markdown.`
    ).then(r => {
      try { const arr = JSON.parse(r); return Array.isArray(arr) ? arr.slice(0, count) : [r]; }
      catch { return r ? [r] : []; }
    });
  }, [section, ctxMemo]);

  /**
   * Auto-complete: debounced, context-aware, multi-variant.
   */
  const onType = useCallback((text: string) => {
    onChange(text);
    setSuggestion("");
    setVariants([]);
    setShowPopover(false);
    if (debRef.current) clearTimeout(debRef.current);
    if (text.length < 15) return;
    debRef.current = setTimeout(async () => {
      setStatus("loading");
      const sug = await callAI(
        (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
        (section === "summary"
          ? `Complete this resume summary: "${text}". Add 10-20 more words. Return ONLY the completion.`
          : section === "bullet"
          ? `Complete this achievement bullet: "${text}". Add an action verb continuation with a metric. Return ONLY the completion.`
          : `Suggest completion for: "${text}". Return ONLY the completion.`)
      );
      if (sug && sug !== text) {
        setSuggestion(sug);
        setStatus("idle");
      } else {
        setStatus("idle");
      }
    }, 1200);
  }, [onChange, section, ctxMemo]);

  const acceptSug = () => {
    if (suggestion) {
      onChange(suggestion);
      setSuggestion("");
      setVariants([]);
      setShowPopover(false);
    }
  };

  const acceptVariant = (v: string) => {
    onChange(v);
    setSuggestion("");
    setVariants([]);
    setShowPopover(false);
  };

  /**
   * Generate new content from scratch (context-aware).
   */
  const onGenerate = async () => {
    setStatus("loading");
    const ctx = ctxMemo || (resume ? `Name: ${resume.name||''}. Role: ${resume.experience?.[0]?.title||''}` : '');
    if (section === "summary") {
      const gen = await callAI(
        (ctx ? `Context:\n${ctx}\n\n` : "") +
        `Generate a professional resume summary (60-80 words) for the candidate. ` +
        (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
        `Highlight years of experience, key skills, and measurable outcomes. Return ONLY the summary.`
      );
      if (gen) { onChange(gen); toast.success("Summary generated"); }
    } else if (section === "bullet") {
      const gen = await callAI(
        (ctx ? `Context:\n${ctx}\n\n` : "") +
        `Generate an achievement bullet for: "${context||''}". ` +
        (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
        `Start with a strong action verb, include a specific metric, 10-20 words. Return ONLY the bullet.`
      );
      if (gen) { onChange(gen); toast.success("Bullet generated"); }
    } else {
      const gen = await callAI(
        `Generate content for ${section} section. ${ctx}. ` +
        (jobDescriptionText ? `Make it highly relevant to the target job description. ` : "") +
        `Return ONLY the text.`
      );
      if (gen) { onChange(gen); toast.success(`${sectionLabel(section)} generated`); }
    }
    setStatus("idle");
  };

  /**
   * Regenerate with a fresh AI call (context-aware).
   */
  const onRegen = async () => {
    if (!value) return;
    setStatus("loading");
    const gen = await callAI(
      (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
      `Rewrite this to be more impactful and ATS-friendly: "${value}". ` +
      (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
      `Keep same length. Use active voice and specific metrics. Return ONLY the rewritten text.`
    );
    if (gen) { onChange(gen); toast.success(`${sectionLabel(section)} regenerated`); }
    setStatus("idle");
  };

  /**
   * Fix grammar, spelling, and autocomplete incomplete phrases.
   */
  const onFixAndPolish = async () => {
    if (!value) return;
    setStatus("loading");
    const gen = await callAI(
      (ctxMemo ? `Context:\n${ctxMemo}\n\n` : "") +
      `Fix any grammar, spelling, or sentence structure issues in this text: "${value}". ` +
      `If the text is incomplete or written as a shorthand note, complete it into a professional, high-impact resume statement. ` +
      (jobDescriptionText ? `Naturally weave in relevant keywords and skills from the target job description. ` : "") +
      `Ensure it starts with a strong action verb (if it is a bullet point) and has a clean, professional tone. Return ONLY the polished text.`
    );
    if (gen) {
      onChange(gen);
      toast.success("Phrase polished and completed!");
    }
    setStatus("idle");
  };

  /**
   * Show suggestion popover with variants.
   */
  const onShowSuggestions = async () => {
    if (!value || value.length < 10) {
      toast.info("Type at least 10 characters for suggestions");
      return;
    }
    if (showPopover) { setShowPopover(false); return; }
    setStatus("loading");
    const vs = await fetchVariants(value);
    if (vs.length > 0) {
      setVariants(vs);
      setCurrentVariant(0);
      setShowPopover(true);
      setStatus("idle");
    } else {
      setStatus("idle");
      toast.error("No suggestions generated");
    }
  };

  // Keyboard handler
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Tab → accept auto-complete suggestion
    if (e.key === "Tab" && suggestion) {
      e.preventDefault();
      acceptSug();
      return;
    }
    // Escape → dismiss popover/suggestion
    if (e.key === "Escape") {
      if (showPopover) { setShowPopover(false); return; }
      if (suggestion) { setSuggestion(""); return; }
    }
    // Ctrl+Space → show suggestions popover
    if (e.key === " " && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      onShowSuggestions();
      return;
    }
  };

  // Close popover on outside click
  useEffect(() => {
    if (!showPopover) return;
    const handler = (e: MouseEvent) => {
      if (textareaRef.current && !textareaRef.current.contains(e.target as Node)) {
        // Check if click was inside popover
        const popover = document.getElementById("smart-textarea-popover");
        if (popover && !popover.contains(e.target as Node)) {
          setShowPopover(false);
        }
      }
    };
    // Delay to avoid immediate close from trigger button
    const timer = setTimeout(() => document.addEventListener("mousedown", handler), 0);
    return () => {
      clearTimeout(timer);
      document.removeEventListener("mousedown", handler);
    };
  }, [showPopover]);

  return (
    <div className="relative group" ref={textareaRef}>
      <Textarea
        value={value}
        onChange={e => onType(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder={placeholder || ''}
        rows={rows}
        disabled={disabled}
        className={className}
      />

      {/* Auto-complete suggestion hint (inline, below text) */}
      {suggestion && status === "idle" && !showPopover && (
        <div
          className="absolute bottom-2 left-3 right-12 flex items-center gap-2 cursor-pointer z-10"
          onClick={acceptSug}
          role="button"
          tabIndex={0}
          onKeyDown={e => { if (e.key === "Enter") acceptSug(); }}
        >
          <span className="text-muted-foreground/50 text-sm truncate italic">{suggestion}</span>
          <Badge variant="outline" className="text-[9px] shrink-0">Tab ↵</Badge>
        </div>
      )}

      {/* Suggestion popover with multiple variants */}
      {showPopover && variants.length > 0 && (
        <div
          id="smart-textarea-popover"
          className="absolute bottom-full left-0 right-0 mb-1 z-50 rounded-lg border border-border bg-popover shadow-lg overflow-hidden"
        >
          <div className="p-2 space-y-1">
            <div className="flex items-center justify-between px-1 mb-1">
              <span className="text-[9px] uppercase text-muted-foreground font-semibold">
                Suggestions ({currentVariant + 1}/{variants.length})
              </span>
              <div className="flex gap-1">
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-5 w-5 p-0"
                  disabled={currentVariant === 0}
                  onClick={() => setCurrentVariant(v => Math.max(0, v - 1))}
                >
                  <Icon name="ChevronLeft" className="w-3 h-3" />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-5 w-5 p-0"
                  disabled={currentVariant === variants.length - 1}
                  onClick={() => setCurrentVariant(v => Math.min(variants.length - 1, v + 1))}
                >
                  <Icon name="ChevronRight" className="w-3 h-3" />
                </Button>
              </div>
            </div>
            <div className="rounded-md bg-muted/50 p-2 text-xs text-foreground/90 leading-relaxed">
              {variants[currentVariant]}
            </div>
            <div className="flex items-center justify-end gap-1.5 pt-1">
              <Button
                variant="ghost"
                size="sm"
                className="h-6 text-[10px]"
                onClick={() => setShowPopover(false)}
              >
                Dismiss
              </Button>
              <Button
                variant="default"
                size="sm"
                className="h-6 text-[10px] gap-1"
                onClick={() => acceptVariant(variants[currentVariant])}
              >
                <Icon name="Check" className="w-3 h-3" /> Accept
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Action buttons (top-right corner) */}
      <div className="absolute top-1 right-1 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        {/* Smart suggestions trigger */}
        {value && value.length >= 10 && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onShowSuggestions}
            disabled={status === "loading"}
            className="h-6 px-1.5 text-[10px] gap-1"
            title="Suggestions (Ctrl+Space)"
          >
            <Icon name="Lightbulb" className="w-3 h-3" />
          </Button>
        )}
        {/* Generate (when empty) */}
        {!value && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onGenerate}
            disabled={status === "loading"}
            className="h-6 px-2 text-[10px] gap-1 text-brand"
            title="AI generate"
          >
            {status === "loading"
              ? <Icon name="Loader2" className="w-3 h-3 animate-spin" />
              : <Icon name="Sparkles" className="w-3 h-3" />
            }
            Generate
          </Button>
        )}
        {/* Fix & Polish (when has value) */}
        {value && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onFixAndPolish}
            disabled={status === "loading"}
            className="h-6 px-1.5 text-[10px] gap-1 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50 dark:hover:bg-emerald-950/20"
            title="Fix grammar, spelling & autocomplete phrase"
          >
            {status === "loading"
              ? <Icon name="Loader2" className="w-3 h-3 animate-spin" />
              : <Icon name="CheckCheck" className="w-3 h-3" />
            }
          </Button>
        )}
        {/* Regenerate (when has value) */}
        {value && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onRegen}
            disabled={status === "loading"}
            className="h-6 px-1.5 text-[10px] gap-1"
            title="Regenerate"
          >
            {status === "loading"
              ? <Icon name="Loader2" className="w-3 h-3 animate-spin" />
              : <Icon name="RefreshCw" className="w-3 h-3" />
            }
          </Button>
        )}
      </div>
    </div>
  );
}

src/components/shared/SpellCheckPanel.ts:
"use client";

import { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import { type SectionSpelling, scanResume, totalMisspelled } from "@/lib/spellchecker";
import type { ResumeData } from "@/lib/types";

interface Props {
  resume: ResumeData;
  onFixWord?: (path: string, oldWord: string, newWord: string) => void;
  open: boolean;
  onToggle: () => void;
}

/**
 * SpellCheckPanel — scans the entire resume for spelling mistakes and
 * presents them in a searchable, actionable panel. Each issue shows the
 * misspelled word in context with clickable suggestions.
 */
export function SpellCheckPanel({ resume, onFixWord, open, onToggle }: Props) {
  const [sections] = useState<SectionSpelling[]>(() => scanResume(resume));
  const total = totalMisspelled(sections);

  if (!open) {
    // Just the badge button
    return (
      <Button
        variant={total > 0 ? "outline" : "ghost"}
        size="sm"
        onClick={onToggle}
        className={`gap-1.5 h-8 relative ${total > 0 ? "border-amber-400 text-amber-600 hover:bg-amber-50" : ""}`}
        title={total > 0 ? `${total} spelling issue${total > 1 ? "s" : ""} found` : "No spelling issues found"}
      >
        <Icon name="SpellCheck2" className="w-3.5 h-3.5" />
        <span className="hidden sm:inline">Spelling</span>
        {total > 0 && (
          <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-amber-400 text-white text-[10px] font-bold leading-none">
            {total}
          </span>
        )}
        {total === 0 && (
          <Icon name="Check" className="w-3 h-3 text-emerald-500" />
        )}
      </Button>
    );
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, height: 0 }}
        animate={{ opacity: 1, height: "auto" }}
        exit={{ opacity: 0, height: 0 }}
        className="overflow-hidden"
      >
        <Card className="border-amber-200 bg-amber-50/30">
          <CardHeader className="pb-2 flex flex-row items-center justify-between gap-2">
            <div>
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Icon name="SpellCheck2" className="w-4 h-4 text-amber-600" />
                Spell Check
                {total > 0 ? (
                  <Badge variant="danger" className="text-[10px]">
                    {total} issue{total > 1 ? "s" : ""}
                  </Badge>
                ) : (
                  <Badge variant="default" className="text-[10px] bg-emerald-500">
                    All clear
                  </Badge>
                )}
              </CardTitle>
              {total > 0 && (
                <p className="text-xs text-muted-foreground mt-0.5">
                  Click a suggestion to replace the word. Re-run after editing.
                </p>
              )}
            </div>
            <div className="flex gap-1">
              <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => {
                // Re-scan (force re-mount by toggling)
                onToggle();
                setTimeout(() => onToggle(), 50);
              }}>
                <Icon name="RefreshCw" className="w-3 h-3 mr-1" /> Re-scan
              </Button>
              <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onToggle}>
                <Icon name="X" className="w-3 h-3" />
              </Button>
            </div>
          </CardHeader>
          <CardContent className="pt-2">
            {total === 0 ? (
              <div className="flex items-center gap-2 py-3 text-sm text-emerald-600">
                <Icon name="CheckCircle2" className="w-4 h-4" />
                No spelling issues found. Your resume looks great!
              </div>
            ) : (
              <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
                {sections.map((section, si) => (
                  <div key={si}>
                    <div className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-1 mt-2 first:mt-0">
                      {section.label}
                    </div>
                    {section.issues.map((issue, ii) => (
                      <div
                        key={ii}
                        className="flex items-start gap-2 py-1.5 px-2 rounded hover:bg-amber-100/50 group"
                      >
                        <div className="min-w-0 flex-1">
                          <span className="text-sm font-mono bg-red-100 text-red-700 px-1 rounded line-through">
                            {issue.word}
                          </span>
                          <span className="text-xs text-muted-foreground ml-2 italic truncate block sm:inline">
                            {issue.context}
                          </span>
                        </div>
                        <div className="flex gap-1 flex-shrink-0 flex-wrap">
                          {issue.suggestions.length > 0 ? (
                            issue.suggestions.slice(0, 3).map((sug) => (
                              <button
                                key={sug}
                                className="text-xs px-2 py-0.5 rounded bg-white border border-emerald-200 text-emerald-700 hover:bg-emerald-50 hover:border-emerald-400 transition-colors whitespace-nowrap"
                                onClick={() => {
                                  if (onFixWord && issue.path) {
                                    onFixWord(issue.path, issue.word, sug);
                                  }
                                }}
                                title={`Replace "${issue.word}" with "${sug}"`}
                              >
                                {sug}
                              </button>
                            ))
                          ) : (
                            <span className="text-[10px] text-muted-foreground italic">No suggestions</span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
          {total > 0 && (
            <CardFooter className="pt-2 pb-3 px-4">
              <p className="text-[10px] text-muted-foreground">
                Suggestion quality is based on word-level checks — proper nouns, brand names, and technical
                terms may be flagged. Use your judgment when accepting suggestions.
              </p>
            </CardFooter>
          )}
        </Card>
      </motion.div>
    </AnimatePresence>
  );
}

src/components/shared/UndoRedoPanel.tsx:
"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge, Icon } from "@/components/shared";
import type { UndoRedoEntry } from "@/lib/builder-persistence";

interface Props {
  undoStack: UndoRedoEntry[];
  canUndo: boolean;
  canRedo: boolean;
  totalUndos: number;
  totalRedos: number;
  onUndo: () => boolean;
  onRedo: () => boolean;
  onSnapshot: (label?: string) => void;
  onJump: (index: number) => boolean;
  open: boolean;
  onToggle: () => void;
}

/**
 * UndoRedoPanel — shows the full edit history with session grouping,
 * undo/redo buttons, snapshot creation, and jump-to-any-point.
 */
export function UndoRedoPanel({
  undoStack,
  canUndo,
  canRedo,
  totalUndos,
  totalRedos,
  onUndo,
  onRedo,
  onSnapshot,
  onJump,
  open,
  onToggle,
}: Props) {
  const [snapshotLabel, setSnapshotLabel] = useState("");

  // Group entries by session (contiguous entries within same minute)
  const sessions: Array<{ label: string; entries: UndoRedoEntry[]; indices: number[] }> = [];
  let currentSession: typeof sessions[0] | null = null;

  undoStack.forEach((entry, i) => {
    const sessionGroup = entry.sessionId || `sess-${Math.floor(entry.timestamp / 60000)}`;
    if (!currentSession || currentSession.label !== sessionGroup) {
      currentSession = { label: sessionGroup, entries: [], indices: [] };
      sessions.push(currentSession);
    }
    currentSession.entries.push(entry);
    currentSession.indices.push(i);
  });

  const formatTime = (ts: number) => {
    const d = new Date(ts);
    const now = new Date();
    const isToday = d.toDateString() === now.toDateString();
    const time = d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    return isToday ? time : `${d.toLocaleDateString([], { month: "short", day: "numeric" })} ${time}`;
  };

  if (!open) {
    return (
      <Button
        variant="outline"
        size="sm"
        onClick={onToggle}
        className="gap-1.5 h-8 relative"
        title="Edit history"
      >
        <Icon name="History" className="w-3.5 h-3.5" />
        <span className="hidden sm:inline">History</span>
      </Button>
    );
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, height: 0 }}
        animate={{ opacity: 1, height: "auto" }}
        exit={{ opacity: 0, height: 0 }}
        className="overflow-hidden"
      >
        <Card className="border-muted">
          <CardHeader className="pb-2 flex flex-row items-center justify-between gap-2">
            <div>
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Icon name="History" className="w-4 h-4" />
                Edit History
                <Badge variant="outline" className="text-[10px]">
                  {undoStack.length} entries
                </Badge>
              </CardTitle>
            </div>
            <div className="flex gap-1">
              <Button
                variant="ghost"
                size="sm"
                className="h-7 text-xs"
                disabled={!canUndo}
                onClick={onUndo}
                title="Undo (Ctrl+Z)"
              >
                <Icon name="Undo2" className="w-3 h-3 mr-1" /> Undo
              </Button>
              <Button
                variant="ghost"
                size="sm"
                className="h-7 text-xs"
                disabled={!canRedo}
                onClick={onRedo}
                title="Redo (Ctrl+Shift+Z)"
              >
                <Icon name="Redo2" className="w-3 h-3 mr-1" /> Redo
              </Button>
              <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onToggle}>
                <Icon name="X" className="w-3 h-3" />
              </Button>
            </div>
          </CardHeader>
          <CardContent className="pt-2">
            {/* Snapshot creation */}
            <div className="flex gap-2 mb-3">
              <input
                type="text"
                placeholder="Snapshot label (e.g. 'Before major edit')..."
                value={snapshotLabel}
                onChange={(e) => setSnapshotLabel(e.target.value)}
                className="flex-1 h-8 px-2 text-xs rounded border border-input bg-background"
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    onSnapshot(snapshotLabel || undefined);
                    setSnapshotLabel("");
                  }
                }}
              />
              <Button
                variant="outline"
                size="sm"
                className="h-8 text-xs gap-1"
                onClick={() => {
                  onSnapshot(snapshotLabel || undefined);
                  setSnapshotLabel("");
                }}
              >
                <Icon name="Camera" className="w-3 h-3" /> Snapshot
              </Button>
            </div>

            {/* History list */}
            {undoStack.length === 0 ? (
              <div className="text-center py-6 text-muted-foreground text-sm">
                <Icon name="FileEdit" className="w-8 h-8 mx-auto mb-2 opacity-40" />
                No edits yet. Start editing your resume to build history.
              </div>
            ) : (
              <div className="space-y-1 max-h-[300px] overflow-y-auto pr-1">
                {[...undoStack].reverse().map((entry, reverseI) => {
                  const actualIndex = undoStack.length - 1 - reverseI;
                  const isLast = actualIndex === undoStack.length - 1;
                  return (
                    <div
                      key={`${entry.timestamp}-${actualIndex}`}
                      className={`flex items-center gap-2 py-1.5 px-2 rounded text-xs cursor-pointer
                        ${isLast ? "bg-brand/5 border border-brand/20" : "hover:bg-muted/50"}
                        transition-colors`}
                      onClick={() => onJump(actualIndex)}
                      title="Jump to this point in history"
                    >
                      <Icon
                        name={entry.label ? "Bookmark" : "FileEdit"}
                        className="w-3 h-3 flex-shrink-0 text-muted-foreground"
                      />
                      <span className="flex-1 truncate">
                        {entry.label || `Edit #${actualIndex + 1}`}
                      </span>
                      <span className="text-muted-foreground flex-shrink-0 ml-auto">
                        {formatTime(entry.timestamp)}
                      </span>
                      {entry.label && (
                        <Badge variant="default" className="text-[9px] bg-emerald-500">
                          Snapshot
                        </Badge>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
          <CardFooter className="pt-2 pb-3 px-4 flex justify-between text-[10px] text-muted-foreground">
            <span>
              Undos: {totalUndos} &middot; Redos: {totalRedos}
            </span>
            <span>
              History persists across page refreshes (IndexedDB)
            </span>
          </CardFooter>
        </Card>
      </motion.div>
    </AnimatePresence>
  );
}

