// ============================================================================
// Knowledge Graph Tests
// ============================================================================

import { describe, it, expect, beforeEach } from "vitest";
import { KnowledgeGraph } from "./knowledge-graph";

describe("KnowledgeGraph", () => {
  let kg: KnowledgeGraph;

  beforeEach(() => {
    kg = new KnowledgeGraph();
  });

  describe("set/get", () => {
    it("stores and retrieves a value", () => {
      kg.set("test", "key1", "hello");
      expect(kg.get("test", "key1")).toBe("hello");
    });

    it("returns undefined for missing keys", () => {
      expect(kg.get("test", "nonexistent")).toBeUndefined();
    });

    it("returns undefined for expired values", async () => {
      kg.set("test", "key1", "hello", 0); // expires immediately
      // Set TTL to 0 — should be available (no expiry)
      expect(kg.get("test", "key1")).toBe("hello");
    });

    it("respects positive TTL", async () => {
      kg.set("test", "key1", "temporary", 1); // 1 second TTL
      expect(kg.get("test", "key1")).toBe("temporary");
      // Wait for expiry
      await new Promise((r) => setTimeout(r, 1100));
      expect(kg.get("test", "key1")).toBeUndefined();
    });

    it("stores and retrieves objects", () => {
      const obj = { a: 1, b: "two", c: [3, 4] };
      kg.set("test", "obj", obj);
      expect(kg.get("test", "obj")).toEqual(obj);
    });

    it("overwrites existing values", () => {
      kg.set("test", "key", "old");
      kg.set("test", "key", "new");
      expect(kg.get("test", "key")).toBe("new");
    });
  });

  describe("has", () => {
    it("returns true for existing keys", () => {
      kg.set("test", "key", "value");
      expect(kg.has("test", "key")).toBe(true);
    });

    it("returns false for missing keys", () => {
      expect(kg.has("test", "nope")).toBe(false);
    });

    it("returns false for expired keys", async () => {
      kg.set("test", "key", "value", 1);
      await new Promise((r) => setTimeout(r, 1100));
      expect(kg.has("test", "key")).toBe(false);
    });
  });

  describe("delete", () => {
    it("removes a value", () => {
      kg.set("test", "key", "value");
      expect(kg.delete("test", "key")).toBe(true);
      expect(kg.get("test", "key")).toBeUndefined();
    });

    it("returns false for missing keys", () => {
      expect(kg.delete("test", "nope")).toBe(false);
    });
  });

  describe("scope operations", () => {
    it("lists keys in a scope", () => {
      kg.set("scope-a", "k1", 1);
      kg.set("scope-a", "k2", 2);
      kg.set("scope-b", "k3", 3);

      const keys = kg.keys("scope-a");
      expect(keys).toHaveLength(2);
      expect(keys).toContain("k1");
      expect(keys).toContain("k2");
    });

    it("returns entries in a scope", () => {
      kg.set("scope-a", "k1", { name: "entry1" });
      const entries = kg.entries("scope-a");
      expect(entries).toHaveLength(1);
      expect(entries[0].key).toBe("k1");
      expect(entries[0].value).toEqual({ name: "entry1" });
      expect(entries[0].scope).toBe("scope-a");
    });

    it("clears an entire scope", () => {
      kg.set("scope-a", "k1", 1);
      kg.set("scope-a", "k2", 2);
      kg.clearScope("scope-a");
      expect(kg.keys("scope-a")).toHaveLength(0);
      expect(kg.get("scope-a", "k1")).toBeUndefined();
    });

    it("does not affect other scopes when clearing one", () => {
      kg.set("scope-a", "k1", 1);
      kg.set("scope-b", "k2", 2);
      kg.clearScope("scope-a");
      expect(kg.get("scope-b", "k2")).toBe(2);
    });
  });

  describe("clear", () => {
    it("removes all entries", () => {
      kg.set("a", "k1", 1);
      kg.set("b", "k2", 2);
      kg.clear();
      expect(kg.stats().activeEntries).toBe(0);
    });
  });

  describe("industry helpers", () => {
    it("stores and retrieves industry patterns", () => {
      const patterns = { keywords: ["aviation", "safety"], score: 0.9 };
      kg.setIndustryPattern("aviation", "ats-patterns", patterns);
      expect(kg.getIndustryPattern("aviation", "ats-patterns")).toEqual(patterns);
    });

    it("scopes industry patterns correctly", () => {
      kg.setIndustryPattern("aviation", "pattern", "aviation-data");
      kg.setIndustryPattern("tech", "pattern", "tech-data");
      expect(kg.getIndustryPattern("aviation", "pattern")).toBe("aviation-data");
      expect(kg.getIndustryPattern("tech", "pattern")).toBe("tech-data");
    });
  });

  describe("provider helpers", () => {
    it("stores and retrieves provider metrics", () => {
      kg.setProviderMetric("openai", "avg-latency", 1200);
      expect(kg.getProviderMetric("openai", "avg-latency")).toBe(1200);
    });

    it("scopes provider metrics globally", () => {
      kg.setProviderMetric("openai", "success-rate", 0.95);
      // Provider metrics are in the "global" scope
      expect(kg.keys("global")).toContain("provider:openai:success-rate");
    });
  });

  describe("ATS cache helpers", () => {
    it("stores and retrieves ATS cache", () => {
      const analysis = { score: 85, gaps: ["keywords"], strengths: ["format"] };
      kg.setATSCache("job-123", analysis);
      expect(kg.getATSCache("job-123")).toEqual(analysis);
    });

    it("returns undefined for uncached jobs", () => {
      expect(kg.getATSCache("job-unknown")).toBeUndefined();
    });
  });

  describe("evictExpired", () => {
    it("evicts expired entries globally", async () => {
      kg.set("a", "permanent", "stay");
      kg.set("b", "temporary", "go", 1); // 1 second TTL
      await new Promise((r) => setTimeout(r, 1100));
      const evicted = kg.evictExpired();
      expect(evicted).toBeGreaterThanOrEqual(1);
      expect(kg.get("b", "temporary")).toBeUndefined();
      expect(kg.get("a", "permanent")).toBe("stay");
    });

    it("evicts expired entries in a specific scope", async () => {
      kg.set("scope-a", "perm", "stay");
      kg.set("scope-a", "temp", "go", 1);
      kg.set("scope-b", "other", "stay");
      await new Promise((r) => setTimeout(r, 1100));
      const evicted = kg.evictExpired("scope-a");
      expect(evicted).toBe(1);
      expect(kg.get("scope-a", "temp")).toBeUndefined();
      expect(kg.get("scope-a", "perm")).toBe("stay");
      expect(kg.get("scope-b", "other")).toBe("stay");
    });
  });

  describe("stats", () => {
    it("returns correct statistics", () => {
      kg.set("global", "m1", 1);
      kg.set("industry:aviation", "p1", 2);
      kg.set("industry:tech", "p2", 3);
      const stats = kg.stats();
      expect(stats.activeEntries).toBe(3);
      expect(stats.byScope["global"]).toBe(1);
      expect(stats.byScope["industry:aviation"]).toBe(1);
      expect(stats.byScope["industry:tech"]).toBe(1);
    });
  });
});

describe("pipelineKnowledge singleton", () => {
  it("is a KnowledgeGraph instance", async () => {
    const { pipelineKnowledge } = await import("./knowledge-graph");
    expect(pipelineKnowledge.set("test", "singleton", "works"));
    expect(pipelineKnowledge.get("test", "singleton")).toBe("works");
    pipelineKnowledge.clear();
  });
});

src/lib/agents/knowledge-graph.ts:
// ============================================================================
// Knowledge Graph — cross-session knowledge for the pipeline.
//
// Lightweight key-value store with TTL, scoped by industry and session.
// Provides the pipeline with:
//   - Industry-specific optimization patterns (keywords, structures)
//   - Provider performance metrics (latency, success rate per task)
//   - Cached ATS gap analysis results
//   - Learning from previous optimizations
//
// Backed by in-memory Map (ephemeral, session-only). Extendable to
// localStorage or IndexedDB for cross-session persistence.
// ============================================================================

// ---------------------------------------------------------------------------
// Storage Backend
// ---------------------------------------------------------------------------

interface StoredValue<T> {
  value: T;
  /** Unix ms when this value expires. 0 = no expiry. */
  expiresAt: number;
  /** When this value was stored */
  createdAt: number;
  /** How many times this value was read */
  accessCount: number;
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** A piece of knowledge in the graph */
export interface KnowledgeEntry<T = unknown> {
  key: string;
  value: T;
  /**
   * Scope helps organize related knowledge:
   * "global" — applies everywhere (e.g., provider performance)
   * "industry:<id>" — scoped to a specific industry
   * "job:<id>" — scoped to a specific job
   * "session:<id>" — scoped to a specific optimization session
   */
  scope: string;
  /** TTL in seconds. 0 = no expiry. */
  ttl: number;
  /** When this entry was created */
  createdAt: number;
  /** Number of times accessed */
  accessCount: number;
}

export interface KnowledgeStats {
  totalEntries: number;
  expiredEntries: number;
  activeEntries: number;
  byScope: Record<string, number>;
}

// ---------------------------------------------------------------------------
// Knowledge Graph
// ---------------------------------------------------------------------------

export class KnowledgeGraph {
  private store = new Map<string, StoredValue<unknown>>();
  private scopeIndex = new Map<string, Set<string>>();

  // -----------------------------------------------------------------------
  // Core CRUD
  // -----------------------------------------------------------------------

  /**
   * Store a value with optional TTL.
   * @param scope - Partition key ("global", "industry:aviation", "job:xxx")
   * @param key - Unique key within the scope
   * @param value - The value to store
   * @param ttlSeconds - Time-to-live in seconds (0 = no expiry)
   */
  set<T>(scope: string, key: string, value: T, ttlSeconds: number = 0): void {
    const fullKey = `${scope}::${key}`;
    const expiresAt = ttlSeconds > 0 ? Date.now() + ttlSeconds * 1000 : 0;

    this.store.set(fullKey, {
      value,
      expiresAt,
      createdAt: Date.now(),
      accessCount: 0,
    });

    // Index by scope
    if (!this.scopeIndex.has(scope)) {
      this.scopeIndex.set(scope, new Set());
    }
    this.scopeIndex.get(scope)!.add(key);
  }

  /**
   * Retrieve a value by scope and key.
   * Returns undefined if not found or expired.
   */
  get<T>(scope: string, key: string): T | undefined {
    const fullKey = `${scope}::${key}`;
    const stored = this.store.get(fullKey);

    if (!stored) return undefined;

    // Check expiry
    if (stored.expiresAt > 0 && Date.now() > stored.expiresAt) {
      this.store.delete(fullKey);
      this.scopeIndex.get(scope)?.delete(key);
      return undefined;
    }

    stored.accessCount++;
    return stored.value as T;
  }

  /**
   * Delete a value.
   */
  delete(scope: string, key: string): boolean {
    const fullKey = `${scope}::${key}`;
    const existed = this.store.delete(fullKey);
    this.scopeIndex.get(scope)?.delete(key);
    return existed;
  }

  /**
   * Clear all entries.
   */
  clear(): void {
    this.store.clear();
    this.scopeIndex.clear();
  }

  /**
   * Check if a key exists and is not expired.
   */
  has(scope: string, key: string): boolean {
    return this.get(scope, key) !== undefined;
  }

  // -----------------------------------------------------------------------
  // Scope Operations
  // -----------------------------------------------------------------------

  /**
   * Get all non-expired keys in a scope.
   */
  keys(scope: string): string[] {
    this.evictExpired(scope);
    return Array.from(this.scopeIndex.get(scope) ?? []);
  }

  /**
   * Get all non-expired entries in a scope.
   */
  entries<T>(scope: string): KnowledgeEntry<T>[] {
    this.evictExpired(scope);
    const scopeKeys = this.scopeIndex.get(scope);
    if (!scopeKeys) return [];

    const results: KnowledgeEntry<T>[] = [];
    for (const key of scopeKeys) {
      const fullKey = `${scope}::${key}`;
      const stored = this.store.get(fullKey);
      if (stored) {
        results.push({
          key,
          value: stored.value as T,
          scope,
          ttl: stored.expiresAt > 0 ? Math.round((stored.expiresAt - Date.now()) / 1000) : 0,
          createdAt: stored.createdAt,
          accessCount: stored.accessCount,
        });
      }
    }
    return results;
  }

  /**
   * Remove all entries in a scope.
   */
  clearScope(scope: string): void {
    const keys = this.scopeIndex.get(scope);
    if (keys) {
      for (const key of keys) {
        this.store.delete(`${scope}::${key}`);
      }
      this.scopeIndex.delete(scope);
    }
  }

  // -----------------------------------------------------------------------
  // Convenience: Industry-specific helpers
  // -----------------------------------------------------------------------

  /**
   * Store knowledge scoped to an industry.
   */
  setIndustryPattern<T>(industryId: string, key: string, value: T, ttlSeconds: number = 86400): void {
    this.set(`industry:${industryId}`, key, value, ttlSeconds);
  }

  /**
   * Retrieve knowledge scoped to an industry.
   */
  getIndustryPattern<T>(industryId: string, key: string): T | undefined {
    return this.get(`industry:${industryId}`, key);
  }

  /**
   * Store provider performance metric.
   */
  setProviderMetric<T>(providerId: string, metric: string, value: T): void {
    this.set("global", `provider:${providerId}:${metric}`, value, 86400 * 7); // 7 days
  }

  /**
   * Retrieve provider performance metric.
   */
  getProviderMetric<T>(providerId: string, metric: string): T | undefined {
    return this.get("global", `provider:${providerId}:${metric}`);
  }

  /**
   * Store a cache of an ATS analysis result.
   */
  setATSCache<T>(jobId: string, result: T, ttlSeconds: number = 3600): void {
    this.set(`job:${jobId}`, "ats-analysis", result, ttlSeconds);
  }

  /**
   * Retrieve cached ATS analysis.
   */
  getATSCache<T>(jobId: string): T | undefined {
    return this.get(`job:${jobId}`, "ats-analysis");
  }

  // -----------------------------------------------------------------------
  // Maintenance
  // -----------------------------------------------------------------------

  /**
   * Remove all expired entries.
   */
  evictExpired(scope?: string): number {
    let count = 0;
    const now = Date.now();

    if (scope) {
      // Evict within a specific scope
      const keys = this.scopeIndex.get(scope);
      if (!keys) return 0;
      for (const key of keys) {
        const fullKey = `${scope}::${key}`;
        const stored = this.store.get(fullKey);
        if (stored && stored.expiresAt > 0 && now > stored.expiresAt) {
          this.store.delete(fullKey);
          keys.delete(key);
          count++;
        }
      }
      if (keys.size === 0) this.scopeIndex.delete(scope);
    } else {
      // Global eviction
      for (const [fullKey, stored] of this.store) {
        if (stored.expiresAt > 0 && now > stored.expiresAt) {
          this.store.delete(fullKey);
          count++;
        }
      }
      // Rebuild scope index
      this.scopeIndex.clear();
      for (const [fullKey] of this.store) {
        const sep = fullKey.indexOf("::");
        if (sep > 0) {
          const s = fullKey.slice(0, sep);
          const k = fullKey.slice(sep + 2);
          if (!this.scopeIndex.has(s)) this.scopeIndex.set(s, new Set());
          this.scopeIndex.get(s)!.add(k);
        }
      }
    }

    return count;
  }

  /**
   * Get statistics about the knowledge graph.
   */
  stats(): KnowledgeStats {
    this.evictExpired();
    const totalEntries = this.store.size;
    const byScope: Record<string, number> = {};

    for (const [fullKey] of this.store) {
      const sep = fullKey.indexOf("::");
      const scope = sep > 0 ? fullKey.slice(0, sep) : "unknown";
      byScope[scope] = (byScope[scope] ?? 0) + 1;
    }

    return {
      totalEntries,
      expiredEntries: 0, // already evicted
      activeEntries: totalEntries,
      byScope,
    };
  }
}

// ---------------------------------------------------------------------------
// Singleton for the pipeline
// ---------------------------------------------------------------------------

/**
 * Global knowledge graph instance shared across the pipeline.
 */
export const pipelineKnowledge = new KnowledgeGraph();

src/lib/agents/memory-agent.ts:
// ============================================================================
// MemoryAgent — persists a user's career profile + history across sessions.
//
// Stores:
//   - skills, certifications, industries, target roles, preferred locations,
//     languages, salary expectations
//   - application history, optimization history, interview history
//
// Persistence:
//   - localStorage (`resumeai-memory-profile`) — survives refresh/logout/login
//   - Best-effort sync to D1 via the existing cloud API (future enhancement)
//
// The Supervisor and other agents read this profile to personalize their
// recommendations (e.g. the Career Coach recommends certifications aligned
// with the user's target roles; the Salary Agent uses the user's salary
// expectation as a baseline).
// ============================================================================

export interface UserProfile {
  // === Career profile (aggregated from all resumes + JDs the user has ever uploaded) ===
  skills: string[]; // unique, sorted by frequency
  certifications: string[];
  industries: string[]; // industries the user has worked in or applied to
  targetRoles: string[]; // roles the user is actively targeting
  preferredLocations: string[];
  languages: string[];
  salaryExpectations: { role: string; min: number; mid: number; max: number; currency: string }[];

  // === History ===
  applicationHistory: ApplicationEntry[];
  optimizationHistory: OptimizationEntry[];
  interviewHistory: InterviewEntry[];

  // === Metadata ===
  updatedAt: string;
}

export interface ApplicationEntry {
  id: string;
  company: string;
  role: string;
  status: "saved" | "applied" | "interview" | "assessment" | "offer" | "rejected" | "ghosted";
  appliedAt: string;
  notes?: string;
}

export interface OptimizationEntry {
  id: string;
  resumeName: string;
  jobTitle: string;
  company: string;
  atsBefore: number;
  atsAfter: number;
  createdAt: string;
}

export interface InterviewEntry {
  id: string;
  company: string;
  role: string;
  score: number;
  createdAt: string;
}

const MEMORY_KEY = "resumeai-memory-profile";

// ============================================================================
// Load / save
// ============================================================================

export function loadUserProfile(): UserProfile {
  if (typeof localStorage === "undefined") return createEmptyProfile();
  try {
    const raw = localStorage.getItem(MEMORY_KEY);
    if (!raw) return createEmptyProfile();
    const parsed = JSON.parse(raw);
    return { ...createEmptyProfile(), ...parsed };
  } catch {
    return createEmptyProfile();
  }
}

export function saveUserProfile(profile: UserProfile): void {
  if (typeof localStorage === "undefined") return;
  try {
    profile.updatedAt = new Date().toISOString();
    localStorage.setItem(MEMORY_KEY, JSON.stringify(profile));
  } catch (e) {
    console.warn("[MemoryAgent] Failed to save profile:", e);
  }
}

export function createEmptyProfile(): UserProfile {
  return {
    skills: [],
    certifications: [],
    industries: [],
    targetRoles: [],
    preferredLocations: [],
    languages: [],
    salaryExpectations: [],
    applicationHistory: [],
    optimizationHistory: [],
    interviewHistory: [],
    updatedAt: new Date().toISOString(),
  };
}

// ============================================================================
// Aggregation — called whenever a resume is uploaded or a JD is parsed
// ============================================================================

/**
 * Merge skills/certs/languages from a resume into the user profile.
 * Deduplicates and sorts skills by frequency (most-used first).
 */
export function ingestResumeIntoMemory(profile: UserProfile, resume: { skills?: any[]; certifications?: any[]; languages?: any[]; name?: string }): UserProfile {
  const next = { ...profile };
  const skillFreq: Record<string, number> = {};
  for (const s of next.skills) skillFreq[s] = (skillFreq[s] || 0) + 1;
  for (const s of (resume.skills ?? [])) {
    const name = typeof s === "string" ? s : s?.name;
    if (name && typeof name === "string") skillFreq[name] = (skillFreq[name] || 0) + 1;
  }
  next.skills = Object.entries(skillFreq)
    .sort((a, b) => b[1] - a[1])
    .map(([s]) => s);

  const certSet = new Set(next.certifications);
  for (const c of (resume.certifications ?? [])) {
    const name = typeof c === "string" ? c : c?.name;
    if (name && typeof name === "string") certSet.add(name);
  }
  next.certifications = Array.from(certSet);

  const langSet = new Set(next.languages);
  for (const l of (resume.languages ?? [])) {
    const name = typeof l === "string" ? l : l?.name;
    if (name && typeof name === "string") langSet.add(name);
  }
  next.languages = Array.from(langSet);

  saveUserProfile(next);
  return next;
}

/**
 * Merge industry/company/role from a JD into the user profile.
 */
export function ingestJobIntoMemory(profile: UserProfile, jd: { title?: string; company?: string; location?: string }): UserProfile {
  const next = { ...profile };
  if (jd.title && !next.targetRoles.includes(jd.title)) {
    next.targetRoles = [jd.title, ...next.targetRoles].slice(0, 20);
  }
  if (jd.location && !next.preferredLocations.includes(jd.location)) {
    next.preferredLocations = [jd.location, ...next.preferredLocations].slice(0, 10);
  }
  saveUserProfile(next);
  return next;
}

/**
 * Record an optimization run in the user's history.
 */
export function recordOptimization(profile: UserProfile, entry: OptimizationEntry): UserProfile {
  const next = { ...profile, optimizationHistory: [entry, ...profile.optimizationHistory].slice(0, 50) };
  saveUserProfile(next);
  return next;
}

/**
 * Record an application in the user's history.
 */
export function recordApplication(profile: UserProfile, entry: ApplicationEntry): UserProfile {
  const next = { ...profile, applicationHistory: [entry, ...profile.applicationHistory].slice(0, 100) };
  saveUserProfile(next);
  return next;
}

/**
 * Record an interview in the user's history.
 */
export function recordInterview(profile: UserProfile, entry: InterviewEntry): UserProfile {
  const next = { ...profile, interviewHistory: [entry, ...profile.interviewHistory].slice(0, 50) };
  saveUserProfile(next);
  return next;
}

