// ============================================================================
// PatchEngine — Unit Tests
// ============================================================================

import { describe, it, expect } from "vitest";
import type { ResumeData } from "../../types";
import {
  applyPatches,
  validatePatch,
  detectConflicts,
  resolveConflict,
  rollbackPatches,
  computeQualityScore,
  createPatchId,
} from "../patch-engine";
import type {
  AgentPatch,
