} from "../types";

// ── Helpers ───────────────────────────────────────────────────────────────
function makePatch(overrides: Partial<AgentPatch> & { sectionId: string; field: string; oldValue: string; newValue: string }): AgentPatch {
  return {
    patchId: createPatchId("test"),
    agentId: "test-agent",
