// ============================================================================
// Provider Cooldown — Rate-limit and error cooldown management
//
// Extracted from ai.ts for modularity.
// Manages sessionStorage/localStorage-based cooldown timers for AI providers
// that have been rate-limited (429), authentication-failed (401), or timed out.
// ============================================================================

"use client";

export const PUTER_COOLDOWN_KEY = "resumeai-puter-cooldown-until";
export const PUTER_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes

// ============================================================================
// Per-provider cooldown — prevents retry-storms when all external providers
// return 429 (rate limit) or 401 (billing required).
// Stored in sessionStorage so it resets on page refresh but persists during
// the same optimization session.
// ============================================================================
export const PROVIDER_COOLDOWN_PREFIX = "resumeai-provider-cooldown-";
export const PROVIDER_429_COOLDOWN_MS = 3 * 60 * 1000;  // 3 minutes for rate limits
export const PROVIDER_401_COOLDOWN_MS = 30 * 60 * 1000; // 30 minutes for billing failures (don't retry billing issues)
// NOTE: PROVIDER_TIMEOUT_COOLDOWN_MS is imported from pipeline-watchdog.ts (90s)
import { PROVIDER_TIMEOUT_COOLDOWN_MS } from "./pipeline-watchdog";

/** Returns true if a named provider is in cooldown. */
export function isProviderInCooldown(providerId: string): boolean {
  if (typeof window === "undefined") return false;
  try {
    const key = PROVIDER_COOLDOWN_PREFIX + providerId;
    const v = window.sessionStorage?.getItem(key);
    if (!v) return false;
    const until = parseInt(v, 10);
    if (Number.isNaN(until)) return false;
    if (Date.now() >= until) {
      window.sessionStorage.removeItem(key);
      return false;
    }
    return true;
  } catch {
    return false;
  }
}

/** Marks a provider as rate-limited (429) for PROVIDER_429_COOLDOWN_MS. */
export function markProvider429Cooldown(providerId: string): void {
  if (typeof window === "undefined") return;
  try {
    const key = PROVIDER_COOLDOWN_PREFIX + providerId;
    window.sessionStorage?.setItem(key, String(Date.now() + PROVIDER_429_COOLDOWN_MS));
    console.warn(`[AI] Provider "${providerId}" is rate-limited — entering 3-minute cooldown.`);
  } catch { /* ignore */ }
}

/** Marks a provider as billing-failed (401) for PROVIDER_401_COOLDOWN_MS. */
export function markProvider401Cooldown(providerId: string): void {
  if (typeof window === "undefined") return;
  try {
    const key = PROVIDER_COOLDOWN_PREFIX + providerId;
    window.sessionStorage?.setItem(key, String(Date.now() + PROVIDER_401_COOLDOWN_MS));
    console.warn(`[AI] Provider "${providerId}" returned 401 (billing/auth failure) — skipping for 30 minutes.`);
  } catch { /* ignore */ }
}

/**
 * Marks a provider as TIMED OUT for PROVIDER_TIMEOUT_COOLDOWN_MS (90s).
 *
 * Unlike 429/401 cooldowns (which signal "don't retry for a long time"),
 * a timeout cooldown is SHORT — just long enough to skip the same provider
 * on the NEXT pipeline step within the same optimization run. This prevents
 * the failure pattern where every step retries the same slow provider,
 * burning the entire pipeline budget on repeated 60s timeouts.
 */
export function markProviderTimeoutCooldown(providerId: string): void {
  if (typeof window === "undefined") return;
  try {
    const key = PROVIDER_COOLDOWN_PREFIX + providerId;
    window.sessionStorage?.setItem(key, String(Date.now() + PROVIDER_TIMEOUT_COOLDOWN_MS));
    console.warn(`[AI] Provider "${providerId}" timed out — skipping for ${PROVIDER_TIMEOUT_COOLDOWN_MS / 1000}s.`);
  } catch { /* ignore */ }
}

/** Returns true if the error looks like a timeout (AbortError or timeout message). */
export function isTimeoutError(err: any): boolean {
  if (!err) return false;
  if (err?.name === "AbortError") return true;
  const msg = (err?.message || String(err)).toLowerCase();
  return /timed out|timeout/i.test(msg);
}

/** Clears all provider cooldowns (e.g. on manual retry or settings change). */
export function clearAllProviderCooldowns(): void {
  if (typeof window === "undefined") return;
  try {
    const keysToRemove: string[] = [];
    for (let i = 0; i < window.sessionStorage.length; i++) {
      const k = window.sessionStorage.key(i);
      if (k && k.startsWith(PROVIDER_COOLDOWN_PREFIX)) keysToRemove.push(k);
    }
    keysToRemove.forEach((k) => window.sessionStorage.removeItem(k));
    console.info("[AI] All provider cooldowns cleared.");
  } catch { /* ignore */ }
}

/** Returns true if Puter is currently in cooldown (should be skipped). */
export function isPuterInCooldown(): boolean {
  if (typeof window === "undefined") return false;
  try {
    const v = window.localStorage?.getItem(PUTER_COOLDOWN_KEY);
    if (!v) return false;
    const until = parseInt(v, 10);
    if (Number.isNaN(until)) return false;
    if (Date.now() >= until) {
      // Cooldown expired — clear it
      window.localStorage.removeItem(PUTER_COOLDOWN_KEY);
      return false;
    }
    return true;
  } catch {
    return false;
  }
}

/** Marks Puter as in-cooldown for the next PUTER_COOLDOWN_MS. */
export function markPuterCooldown(): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage?.setItem(PUTER_COOLDOWN_KEY, String(Date.now() + PUTER_COOLDOWN_MS));
  } catch {
    // ignore — localStorage may be unavailable
  }
}

/**
 * Detects whether a Puter error indicates the user has hit their usage cap.
 * If so, we should enter cooldown to avoid retry-storms.
 */
export function isPuterQuotaError(err: any): boolean {
  const msg = (err?.message || String(err || "")).toLowerCase();
  return (
    /no usage left/i.test(msg) ||
    /usage.?limit/i.test(msg) ||
    /quota.?exceeded/i.test(msg) ||
    /too many requests/i.test(msg) ||
    /daily.?limit/i.test(msg) ||
    /rate.?limit/i.test(msg)
  );
}

/**
 * Detects "Failed to fetch" — the generic TypeError that fetch() throws when:
 *   - The network is offline
 *   - CORS blocks the request
 *   - The provider URL is wrong / unreachable
 *   - DNS resolution failed
 *   - The server is unreachable
 * This is NOT a transient error — retrying immediately will fail the same way.
 * The caller should fall through to the next provider rather than retry.
 */
export function isFailedToFetchError(err: any): boolean {
  const msg = (err?.message || String(err || "")).toLowerCase();
  return (
    /failed to fetch/i.test(msg) ||
    /networkerror/i.test(msg) ||
    /load failed/i.test(msg) ||
    err?.name === "TypeError"
  );
}

src/lib/provider-failover.ts:
// ============================================================================
// Provider Failover Chain
//
// Structured provider priority with exponential backoff:
//   Primary → Fallback 1 → Fallback 2 → ... → Local Engine
//
// Backoff: 2s, 5s, 10s on rate limits (429)
// Cooldown: 90s on timeouts, 30min on auth (401)
//
// Integrates with circuit breakers — skips tripped providers.
// ============================================================================

"use client";

import type { AIProvider } from "./types";
import { circuitBreakerSuccess, circuitBreakerFailure, circuitBreakerCooldown, isProviderAvailable, resetCircuitBreaker } from "./circuit-breaker";

// Compatibility wrappers — these functions were renamed during circuit-breaker refactoring
const isProviderTripped = (id: string) => !isProviderAvailable(id);
const recordProviderCircuitFailure = (id: string, reason: any) => circuitBreakerFailure(id, reason || "network");
const resetProviderCircuit = (id: string) => resetCircuitBreaker(id);
import { recordProviderFailure } from "./telemetry";

export interface FailoverResult {
  provider: AIProvider | null;
  providerIndex: number;
  attempted: string[];
  skipped: string[];
  reason: string;
}

/**
 * Default provider priority order.
 * The chain tries providers in this order, skipping tripped/inactive ones.
 */
export const DEFAULT_FAILOVER_ORDER = [
  "opencode",    // Primary: OpenCode (free models)
  "zencode",     // Fallback 1: ZenCode (free models)
  "nvidia",      // Fallback 2: Nvidia (Llama free)
  "google",      // Fallback 3: Google (Gemini Flash)
  "openrouter",  // Fallback 4: OpenRouter
  "mistral",     // Fallback 5: Mistral
  "puter",       // Fallback 6: Puter.js (browser auth)
  "zai",         // Fallback 7: Z.ai built-in
];

/**
 * Get the ordered failover chain for the current providers.
 * Filters out inactive providers and those with circuit breakers tripped.
 * Providers are ordered by DEFAULT_FAILOVER_ORDER, then by priority field.
 */
export function getFailoverChain(providers: AIProvider[]): AIProvider[] {
  const activeProviders = providers.filter(
    (p) => p.isActive &&
    // Skip if circuit breaker is tripped
    !isProviderTripped(p.name) &&
    // Skip if no API key (unless browser_auth like Puter)
    (p.apiKey || p.providerCategory === "browser_auth")
  );

  // Sort by failover order, then by priority
  const ordered: AIProvider[] = [];
  for (const type of DEFAULT_FAILOVER_ORDER) {
    const match = activeProviders.find((p) => p.type === type || p.id.includes(type));
    if (match && !ordered.includes(match)) {
      ordered.push(match);
    }
  }

  // Add any remaining active providers not in the default order
  for (const p of activeProviders) {
    if (!ordered.includes(p)) {
      ordered.push(p);
    }
  }

  return ordered;
}

/**
 * Calculate exponential backoff delay for a given attempt.
 * Returns: 2s, 5s, 10s for attempts 1, 2, 3+
 */
export function getBackoffDelay(attempt: number): number {
  const delays = [2000, 5000, 10000];
  return delays[Math.min(attempt - 1, delays.length - 1)] || 10000;
}

/**
 * Record a provider failure and determine if we should failover.
 * Returns true if we should try the next provider, false if we should retry.
 */
export function shouldFailover(
  providerName: string,
  error: { statusCode?: number; message?: string },
): { failover: boolean; delayMs: number; reason: string } {
  const msg = error.message || "";
  const status = error.statusCode;

  // 429 = Rate limited → backoff and retry same provider
  if (status === 429 || /rate.?limit/i.test(msg) || /429/.test(msg)) {
    recordProviderCircuitFailure(providerName, 180_000); // 3 min cooldown
    recordProviderFailure({
      providerName,
      errorType: "rate_limit",
      errorMessage: msg,
    });
    return { failover: true, delayMs: getBackoffDelay(1), reason: "Rate limited (429) — failover to next provider" };
  }

  // 401 = Auth failure → failover immediately, long cooldown
  if (status === 401 || /401/.test(msg) || /billing|payment|credits/i.test(msg)) {
    recordProviderCircuitFailure(providerName, 30 * 60 * 1000); // 30 min cooldown
    recordProviderFailure({
      providerName,
      errorType: "auth",
      errorMessage: msg,
    });
    return { failover: true, delayMs: 0, reason: "Auth failure (401) — failover immediately" };
  }

  // Timeout → failover with short delay
  if (/timeout|timed out|abort/i.test(msg)) {
    recordProviderCircuitFailure(providerName, 90_000); // 90s cooldown
    recordProviderFailure({
      providerName,
      errorType: "timeout",
      errorMessage: msg,
    });
    return { failover: true, delayMs: 1000, reason: "Timeout — failover to next provider" };
  }

  // Network error → failover
  if (/network|fetch|unreachable|connection/i.test(msg)) {
    recordProviderCircuitFailure(providerName, 60_000); // 60s cooldown
    recordProviderFailure({
      providerName,
      errorType: "network",
      errorMessage: msg,
    });
    return { failover: true, delayMs: 2000, reason: "Network error — failover to next provider" };
  }

  // Unknown error → failover
  recordProviderCircuitFailure(providerName, "network");
  recordProviderFailure({
    providerName,
    errorType: "unknown",
    errorMessage: msg,
  });
  return { failover: true, delayMs: 1000, reason: "Unknown error — failover to next provider" };
}

/**
 * Record a successful provider call — resets the circuit breaker.
 */
export function recordProviderSuccess(providerName: string): void {
  resetProviderCircuit(providerName);
}

/**
 * Get the list of currently available providers (not tripped, active, with keys).
 */
export function getAvailableProviders(providers: AIProvider[]): AIProvider[] {
  return getFailoverChain(providers);
}

/**
 * Get the list of currently unavailable providers (tripped or inactive).
 */
export function getUnavailableProviders(providers: AIProvider[]): { name: string; reason: string }[] {
  const unavailable: { name: string; reason: string }[] = [];

  for (const p of providers) {
    if (!p.isActive) {
      unavailable.push({ name: p.name, reason: "Inactive" });
    } else if (isProviderTripped(p.name)) {
      unavailable.push({ name: p.name, reason: "Circuit breaker tripped" });
    } else if (!p.apiKey && p.type !== "puter") {
      unavailable.push({ name: p.name, reason: "No API key" });
    }
  }

  return unavailable;
}

src/lib/provider-health-monitor.ts:
// ============================================================================
// Provider Health Monitor — per-provider latency, success rate, rate limit tracking
//
// Tracks every AI call per provider to build a runtime health profile.
// The Supervisor can use this to auto-select the best provider.
// Eliminates "all providers failed" situations by excluding degraded providers.
//
// Integrated with Agent Event Bus for real-time monitoring.
// ============================================================================

import { globalEventBus } from "./agent-event-bus";

export interface ProviderHealth {
  provider: string;
  /** Total calls made */
  totalCalls: number;
  /** Successful calls */
  successfulCalls: number;
  /** Failed calls */
  failedCalls: number;
  /** Rate-limited calls (429 responses) */
  rateLimitedCalls: number;
  /** Average latency in milliseconds */
  avgLatencyMs: number;
  /** Last latency in milliseconds */
  lastLatencyMs: number;
  /** Success rate 0-100 */
  successRate: number;
  /** Whether this provider is currently rate-limited */
  isRateLimited: boolean;
  /** Last call timestamp */
  lastCallAt: string;
  /** Health status */
  status: "healthy" | "degraded" | "unhealthy";
}

const providers = new Map<string, ProviderHealth>();

function initProvider(name: string): ProviderHealth {
  return {
    provider: name,
    totalCalls: 0,
    successfulCalls: 0,
    failedCalls: 0,
    rateLimitedCalls: 0,
    avgLatencyMs: 0,
    lastLatencyMs: 0,
    successRate: 100,
    isRateLimited: false,
    lastCallAt: new Date().toISOString(),
    status: "healthy",
  };
}

/**
 * Record a successful call to a provider.
 */
export function recordProviderSuccess(
  provider: string,
  latencyMs: number,
  tokensUsed?: number,
): void {
  let health = providers.get(provider);
  if (!health) {
    health = initProvider(provider);
    providers.set(provider, health);
  }

  health.totalCalls++;
  health.successfulCalls++;
  health.lastLatencyMs = latencyMs;
  health.lastCallAt = new Date().toISOString();

  // Exponential moving average for latency
  health.avgLatencyMs = health.avgLatencyMs === 0
    ? latencyMs
    : Math.round(health.avgLatencyMs * 0.7 + latencyMs * 0.3);

  health.successRate = Math.round((health.successfulCalls / health.totalCalls) * 100);
  health.status = health.successRate >= 90 ? "healthy" : health.successRate >= 70 ? "degraded" : "unhealthy";

  globalEventBus.emit({
    agent: "ProviderHealthMonitor",
    action: "call_success",
    resumeId: provider,
    duration: latencyMs,
    tokens: tokensUsed ?? 0,
    provider,
    success: true,
    metadata: { successRate: health.successRate, avgLatencyMs: health.avgLatencyMs },
  });
}

/**
 * Record a failed call to a provider.
 */
export function recordProviderFailure(
  provider: string,
  latencyMs: number,
  isRateLimit: boolean = false,
): void {
  let health = providers.get(provider);
  if (!health) {
    health = initProvider(provider);
    providers.set(provider, health);
  }

  health.totalCalls++;
  health.failedCalls++;
  health.lastLatencyMs = latencyMs;
  health.lastCallAt = new Date().toISOString();

  if (isRateLimit) {
    health.rateLimitedCalls++;
    health.isRateLimited = true;
    // Reset rate limit flag after 30 seconds
    setTimeout(() => {
      const current = providers.get(provider);
      if (current) current.isRateLimited = false;
    }, 30000);
  }

  health.successRate = Math.round(((health.totalCalls - health.failedCalls) / health.totalCalls) * 100);
  health.status = health.successRate >= 90 ? "healthy" : health.successRate >= 70 ? "degraded" : "unhealthy";

  globalEventBus.emit({
    agent: "ProviderHealthMonitor",
    action: "call_failed",
    resumeId: provider,
    duration: latencyMs,
    provider,
    success: false,
    metadata: { isRateLimit, successRate: health.successRate },
  });
}

/**
 * Get health for all providers, sorted by best success rate.
 */
export function getProviderHealth(): ProviderHealth[] {
  const all = Array.from(providers.values());
  return all.sort((a, b) => b.successRate - a.successRate);
}

/**
 * Get health for a specific provider.
 */
export function getProviderHealthByName(provider: string): ProviderHealth | null {
  return providers.get(provider) ?? null;
}

/**
 * Get the best available provider (highest success rate, not rate-limited).
 */
export function getBestProvider(): { provider: string; health: ProviderHealth } | null {
  const candidates = Array.from(providers.entries())
    .filter(([, h]) => !h.isRateLimited && h.status !== "unhealthy")
    .sort(([, a], [, b]) => b.successRate - a.successRate);

  if (candidates.length === 0) return null;
  const [provider, health] = candidates[0];
  return { provider, health };
}

/**
 * Clear all provider health data.
 */
export function clearProviderHealth(): void {
  providers.clear();
}

