// ============================================================================
// Enterprise QA Platform — Golden Resume Corpus
// ============================================================================
// Structured validation dataset of canonical resumes across all supported
// industries. Used for regression detection, pipeline validation, and
// semantic consistency checks.
// ============================================================================

import type { ResumeData } from "../types";

// ============================================================================
// Types
// ============================================================================

export interface GoldenResume {
  id: string;
  name: string;
  industry: string;
  description: string;
  expected: ResumeData;
  invariants: {
    names: string[];
    employers: string[];
    schools: string[];
    diplomas: string[];
    dates: string[];
    locations: string[];
    languages: string[];
    certifications: string[];
    projects: string[];
    awards: string[];
    expectedSectionCount: number;
  };
  tags: string[];
}

// ============================================================================
// Helper to generate sequential IDs
// ============================================================================
let _idCounter = 1;
function nextId(): string {
  return `golden-id-${String(_idCounter++).padStart(4, "0")}`;
}

// ============================================================================
// The Corpus
// ============================================================================

export const GOLDEN_CORPUS: GoldenResume[] = [];

function add(
  overrides: Partial<ResumeData>,
  invariants: {
    names: string[];
    employers: string[];
    schools: string[];
    diplomas: string[];
    dates: string[];
    locations: string[];
    languages: string[];
    certifications: string[];
    projects: string[];
    awards: string[];
    expectedSectionCount: number;
  },
  meta: { id: string; name: string; industry: string; description: string; tags: string[] },
): void {
  const base: ResumeData = {
    id: meta.id,
    name: meta.name,
    contact: { email: "", phone: "", location: "" },
    summary: "",
    experience: [],
    education: [],
    skills: [],
    languages: [],
    certifications: [],
    projects: [],
    achievements: [],
    template: "ats-professional",
    createdAt: "2026-01-01T00:00:00.000Z",
    updatedAt: "2026-01-01T00:00:00.000Z",
  };
  GOLDEN_CORPUS.push({
    id: meta.id,
    name: meta.name,
    industry: meta.industry,
    description: meta.description,
    expected: { ...base, ...overrides },
    invariants,
    tags: meta.tags,
  });
}

