// ResumeAI Pro — Relevance Scoring Engine
// Computes a 0-100 relevance score for a resume against a job intelligence.
// Score < 90 → regenerate (don't generate final PDF).
// Score >= 90 → generate final PDF.

"use client";

import type { ResumeData } from "./types";
import type { JobIntelligence } from "./job-intelligence";

export interface RelevanceScore {
  overall: number;          // 0-100
  skillMatch: number;       // 0-100
  experienceMatch: number;  // 0-100
  languageMatch: number;    // 0-100
  industryMatch: number;    // 0-100
  roleMatch: number;        // 0-100
  customerServiceMatch: number; // 0-100
  communicationMatch: number;   // 0-100
  salesMatch: number;       // 0-100
  // Detailed breakdown for debugging
  details: {
    matchedPriorityKeywords: string[];
    missingPriorityKeywords: string[];
    avoidKeywordsFound: string[];
    transferableSkillsDetected: string[];
  };
  // Whether the resume passes the relevance threshold
  passes: boolean;          // overall >= 90
}

/**
 * Compute the relevance score of a resume against a job intelligence.
 * This is a heuristic engine (no AI call) — fast and deterministic.
 */
export function computeRelevanceScore(resume: ResumeData, ji: JobIntelligence): RelevanceScore {
  // === 1. SKILL MATCH (weight: 25%) ===
  // How many of the job's required/priority skills are present in the resume?
  const resumeSkillsLower = (resume.skills || []).map((s) => s.name.toLowerCase());
  const resumeTextLower = buildResumeText(resume).toLowerCase();

  const matchedPriorityKeywords: string[] = [];
  const missingPriorityKeywords: string[] = [];
  for (const kw of ji.priorityKeywords) {
    const kwLower = kw.toLowerCase();
    const found = resumeSkillsLower.some((s) => s.includes(kwLower) || kwLower.includes(s)) || resumeTextLower.includes(kwLower);
    if (found) matchedPriorityKeywords.push(kw);
    else missingPriorityKeywords.push(kw);
  }
  const skillMatch = ji.priorityKeywords.length > 0
    ? Math.round((matchedPriorityKeywords.length / ji.priorityKeywords.length) * 100)
    : 50;

  // === 2. EXPERIENCE MATCH (weight: 15%) ===
  // Does the resume have enough years of experience?
  const resumeYears = estimateExperienceYears(resume);
  const experienceMatch = ji.requiredExperienceYears > 0
    ? Math.min(100, Math.round((resumeYears / ji.requiredExperienceYears) * 100))
    : 80; // no requirement → assume OK

  // === 3. LANGUAGE MATCH (weight: 10%) ===
  // Does the resume have the required languages?
  const resumeLanguagesLower = (resume.languages || []).map((l) => l.name.toLowerCase());
  const matchedLanguages = ji.requiredLanguages.filter((rl) =>
    resumeLanguagesLower.some((sl) => sl.includes(rl.toLowerCase()) || rl.toLowerCase().includes(sl))
  );
  const languageMatch = ji.requiredLanguages.length > 0
    ? Math.round((matchedLanguages.length / ji.requiredLanguages.length) * 100)
    : 80;

  // === 4. INDUSTRY MATCH (weight: 10%) ===
  // Does the resume mention the target industry?
  const industryKws = ji.requiredIndustryKnowledge.concat(ji.industry ? [ji.industry] : []);
  const industryMatch = industryKws.length > 0
    ? Math.min(100, Math.round(industryKws.filter((kw) => resumeTextLower.includes(kw.toLowerCase())).length / industryKws.length * 100))
    : 50;

  // === 5. ROLE MATCH (weight: 15%) ===
  // Does the resume's headline/title match the target role?
  const headlineLower = (resume.headline || "").toLowerCase();
  const roleTitleLower = ji.roleTitle.toLowerCase();
  const roleKeywords = roleTitleLower.split(/\s+/).filter((w) => w.length > 3);
  const matchedRoleKeywords = roleKeywords.filter((kw) => headlineLower.includes(kw) || resumeTextLower.includes(kw));
  const roleMatch = roleKeywords.length > 0
    ? Math.min(100, Math.round((matchedRoleKeywords.length / roleKeywords.length) * 100))
    : 50;

  // === 6. CUSTOMER SERVICE MATCH (weight: 10%) ===
  // Specific to customer-service roles (very common in aviation/retail/hospitality)
  const csKeywords = ["customer service", "customer support", "customer satisfaction", "customer experience", "client service", "passenger service", "guest service"];
  const csRequired = ji.businessFunction.toLowerCase().includes("customer") || ji.requiredCompetencies.some((c) => /customer/i.test(c));
  const csFound = csKeywords.filter((kw) => resumeTextLower.includes(kw));
  const customerServiceMatch = csRequired
    ? Math.min(100, Math.round((csFound.length / Math.min(csKeywords.length, 4)) * 100))
    : 80; // not required → neutral

  // === 7. COMMUNICATION MATCH (weight: 5%) ===
  const commKeywords = ["communication", "communicate", "verbal", "written", "interpersonal", "active listening"];
  const commFound = commKeywords.filter((kw) => resumeTextLower.includes(kw));
  const communicationMatch = Math.min(100, Math.round((commFound.length / commKeywords.length) * 100) + 40);

  // === 8. SALES MATCH (weight: 5%) ===
  const salesKeywords = ["sales", "selling", "cross-sell", "upsell", "upselling", "cross-selling", "revenue", "target"];
  const salesRequired = ji.businessFunction.toLowerCase().includes("sales") || ji.requiredCompetencies.some((c) => /sales/i.test(c));
  const salesFound = salesKeywords.filter((kw) => resumeTextLower.includes(kw));
  const salesMatch = salesRequired
    ? Math.min(100, Math.round((salesFound.length / salesKeywords.length) * 100) + 30)
    : 80; // not required → neutral

  // === AVOID KEYWORDS DETECTION ===
  const avoidKeywordsFound = ji.avoidKeywords.filter((kw) => resumeTextLower.includes(kw.toLowerCase()));

  // === TRANSFERABLE SKILLS DETECTION ===
  const transferableSkillsDetected = detectTransferableSkills(resumeTextLower);

  // === OVERALL SCORE (weighted average) ===
  const overall = Math.round(
    skillMatch * 0.25 +
    experienceMatch * 0.15 +
    languageMatch * 0.10 +
    industryMatch * 0.10 +
    roleMatch * 0.15 +
    customerServiceMatch * 0.10 +
    communicationMatch * 0.05 +
    salesMatch * 0.05 +
    5 // base bonus
  );

  // Penalize if avoid keywords are present (irrelevant keywords emphasized)
  const penalizedOverall = Math.max(0, overall - (avoidKeywordsFound.length * 5));

  return {
    overall: penalizedOverall,
    skillMatch,
    experienceMatch,
    languageMatch,
    industryMatch,
    roleMatch,
    customerServiceMatch,
    communicationMatch,
    salesMatch,
    details: {
      matchedPriorityKeywords,
      missingPriorityKeywords,
      avoidKeywordsFound,
      transferableSkillsDetected,
    },
    passes: penalizedOverall >= 90,
  };
}

/**
 * Build a single text blob from the resume for keyword matching.
 */
function buildResumeText(r: ResumeData): string {
  const parts: string[] = [];
  parts.push(r.name || "");
  parts.push(r.headline || "");
  parts.push(r.summary || "");
  for (const e of r.experience) {
    parts.push(e.title);
    parts.push(e.company);
    parts.push(e.bullets.join(" "));
  }
  for (const s of r.skills) parts.push(s.name);
  for (const ed of r.education) {
    parts.push(ed.degree);
    parts.push(ed.institution);
    if (ed.highlights) parts.push(ed.highlights.join(" "));
  }
  for (const l of r.languages) parts.push(l.name);
  return parts.filter(Boolean).join(" ");
}

/**
 * Estimate total years of experience from the resume.
 */
function estimateExperienceYears(r: ResumeData): number {
  let total = 0;
  for (const e of r.experience) {
    const start = parseYear(e.startDate);
    const end = e.endDate === "Present" || !e.endDate ? new Date().getFullYear() : parseYear(e.endDate);
    if (start && end && end >= start) total += (end - start);
  }
  return total;
}

function parseYear(s: string | undefined): number | null {
  if (!s) return null;
  const m = s.match(/(\d{4})/);
  return m ? parseInt(m[1], 10) : null;
}

/**
 * Detect transferable skills in the resume text.
 * These are skills that can be transferred from one role to another.
 */
function detectTransferableSkills(text: string): string[] {
  const transferable = [
    { skill: "Customer Support", patterns: ["customer service", "customer support", "passenger service", "guest service", "client service"] },
    { skill: "Communication", patterns: ["communication", "communicate", "verbal", "written", "interpersonal"] },
    { skill: "Problem Solving", patterns: ["problem solving", "problem resolution", "troubleshoot", "resolve"] },
    { skill: "Sales", patterns: ["sales", "selling", "cross-sell", "upsell", "revenue"] },
    { skill: "Teamwork", patterns: ["team", "collaborat", "cooperat"] },
    { skill: "Leadership", patterns: ["lead", "manage", "supervis", "direct"] },
    { skill: "Multilingual", patterns: ["bilingual", "multilingual", "fluent", "native speaker"] },
    { skill: "Fast-paced Environment", patterns: ["fast-paced", "fast paced", "high volume", "busy"] },
    { skill: "CRM", patterns: ["crm", "customer relationship management", "salesforce"] },
    { skill: "Complaint Resolution", patterns: ["complaint", "escalat", "service recovery"] },
  ];
  return transferable.filter((t) => t.patterns.some((p) => text.includes(p))).map((t) => t.skill);
}

src/lib/render-document.ts:
/**
 * render-document.ts — ResumeData → RenderDocument converter
 *
 * Converts the internal ResumeData into a canonical RenderDocument that all
 * renderers (Preview, DOCX, PDF) consume identically. This ensures section
 * order, content structure, and formatting are SINGLE SOURCE OF TRUTH.
 */
import type {
  ResumeData,
  RenderDocument,
  RenderDocumentSection,
  RenderContentItem,
  RenderSectionType,
  ResumeLayoutModel,
} from "./types";
import { getDefaultResumeLayout } from "./exporter";

/** Map from ResumeData's field names to canonical section types */
function detectSectionType(field: string): RenderSectionType {
  switch (field) {
    case "summary":
    case "professionalProfile":
      return "professionalProfile";
    case "experience":
      return "professionalExperience";
    case "education":
      return "education";
    case "skills":
      return "skills";
    case "languages":
      return "languages";
    case "additionalInfo":
      return "additionalInformation";
    case "projects":
      return "projects";
    case "certifications":
      return "certifications";
    default:
      return "skills";
  }
}

/** Section title overrides for rendered output */
const SECTION_TITLES: Record<RenderSectionType, string> = {
  personalInformation: "PERSONAL INFORMATION",
  professionalProfile: "PROFESSIONAL SUMMARY",
  professionalExperience: "PROFESSIONAL EXPERIENCE",
  education: "EDUCATION",
  skills: "CORE COMPETENCIES & SKILLS",
  languages: "LANGUAGES",
  additionalInformation: "ADDITIONAL INFORMATION",
  projects: "PROJECTS",
  certifications: "CERTIFICATIONS",
  dynamicSections: "",
};

function buildContactBlock(resume: ResumeData): RenderDocument["contact"] {
  // Sanitize headline: if it contains contact info (PHONE:, Email:, @, | ) clear it
  const rawHeadline = resume.headline || "";
  const hasContactPattern = /PHONE:|Email:|@|^\s*\+?\d{8,}|\s*\|\s*/.test(rawHeadline);
  const headline = hasContactPattern ? "" : rawHeadline;

  return {
    name: resume.name || "",
    headline,
    phone: resume.contact.phone,
    email: resume.contact.email,
    location: resume.contact.location,
    dateOfBirth: resume.dateOfBirth,
    personalDetails: resume.contact.personalDetails,
  };
}

function buildProfessionalProfile(resume: ResumeData): RenderDocumentSection | null {
  if (!resume.summary) return null;
  return {
    type: "professionalProfile",
    title: SECTION_TITLES.professionalProfile,
    items: [
      { kind: "text", text: resume.summary },
    ],
  };
}

function buildExperienceSection(resume: ResumeData): RenderDocumentSection | null {
  if (!resume.experience?.length) return null;
  const items: RenderContentItem[] = [];
  for (const exp of resume.experience) {
    // Title line with company, location, dates
    const leftSide = `${exp.title}${exp.company ? ` | ${exp.company}` : ""}${exp.location ? ` | ${exp.location}` : ""}`;
    const dateStr = exp.startDate && exp.endDate
      ? `${fmtInfohasRenderDate(exp.startDate)} – ${fmtInfohasRenderDate(exp.endDate)}`
      : (exp.startDate || exp.endDate ? fmtInfohasRenderDate(exp.startDate || exp.endDate) : "");
    items.push({
      kind: "table-row",
      cells: [
        { text: leftSide, bold: true, align: "left" },
        { text: dateStr, bold: true, align: "right" },
      ],
    });
    // Bullets
    if (exp.bullets?.length) {
      items.push({
        kind: "bullets",
        bullets: exp.bullets,
        level: 0,
      });
    }
  }
  return {
    type: "professionalExperience",
    title: SECTION_TITLES.professionalExperience,
    items,
  };
}

function buildEducationSection(resume: ResumeData): RenderDocumentSection | null {
  if (!resume.education?.length) return null;
  const items: RenderContentItem[] = [];
  for (const ed of resume.education) {
    const leftSide = `${ed.degree}${ed.field ? ` in ${ed.field}` : ""}${ed.institution ? ` | ${ed.institution}` : ""}${ed.location ? ` | ${ed.location}` : ""}`;
    const dateStr = ed.startDate && ed.endDate
      ? `${fmtInfohasRenderDate(ed.startDate)} – ${fmtInfohasRenderDate(ed.endDate)}`
      : (ed.startDate || ed.endDate ? fmtInfohasRenderDate(ed.startDate || ed.endDate) : "");
    items.push({
      kind: "table-row",
      cells: [
        { text: leftSide, bold: true, align: "left" },
        { text: dateStr, bold: true, align: "right" },
      ],
    });
    // Education highlights as bullets
    if (ed.highlights?.length) {
      items.push({
        kind: "bullets",
        bullets: ed.highlights,
        level: 0,
      });
    }
  }
  return {
    type: "education",
    title: SECTION_TITLES.education,
    items,
  };
}

function buildSkillsSection(resume: ResumeData): RenderDocumentSection | null {
  if (!resume.skills?.length) return null;
  // Group by category
  const categorized = new Map<string, string[]>();
  for (const s of resume.skills) {
    let cat = s.category?.trim();
    let name = s.name;
    // Fallback: if no explicit category, detect "Category: skill" pattern in name
    if (!cat) {
      const colonIdx = name.indexOf(":");
      if (colonIdx > 0 && colonIdx < 35) {
        cat = name.slice(0, colonIdx).trim();
        name = name.slice(colonIdx + 1).trim();
      } else {
        cat = "General";
      }
    }
    if (!categorized.has(cat)) categorized.set(cat, []);
    categorized.get(cat)!.push(name);
  }
  // Rename "General" category to the first non-General category if it only has one item
  // and that item looks like a category header
  const groups: { label: string; items: string[] }[] = [];
  for (const [category, skillNames] of categorized) {
    groups.push({ label: category, items: skillNames });
  }
  return {
    type: "skills",
    title: SECTION_TITLES.skills,
    items: [
      { kind: "nested-bullets", groups },
    ],
  };
}

function buildLanguagesSection(resume: ResumeData): RenderDocumentSection | null {
  if (!resume.languages?.length) return null;
  const items: RenderContentItem[] = [];
  for (const l of resume.languages) {
    const note = (l as any).note ? ` (${(l as any).note})` : "";
    items.push({
      kind: "text",
      text: `${l.name} – ${l.proficiency}${note}`,
    });
  }
  // Also render as a single bullet line if prefer compact
  return {
    type: "languages",
    title: SECTION_TITLES.languages,
    items: [
      {
        kind: "bullets",
        bullets: resume.languages.map(l => `${l.name} (${l.proficiency})`),
        level: 0,
      },
    ],
  };
}

function buildAdditionalInfoSection(resume: ResumeData): RenderDocumentSection | null {
  const items: RenderContentItem[] = [];

  // Render structured personal details as label: value lines
  const pd = resume.contact?.personalDetails;
  if (pd && Object.keys(pd).length > 0) {
    for (const [label, value] of Object.entries(pd)) {
      if (value?.trim()) {
        items.push({
          kind: "text" as const,
          text: `${label.charAt(0).toUpperCase() + label.slice(1)} : ${value}`,
        });
      }
    }
  }

  // Render free-text additionalInfo as paragraphs
  if (resume.additionalInfo) {
    const paragraphs = resume.additionalInfo.split("\n").map(l => l.trim()).filter(Boolean);
    for (const p of paragraphs) {
      items.push({ kind: "text" as const, text: p });
    }
  }

  if (items.length === 0) return null;
  return {
    type: "additionalInformation",
    title: "Additional Information",
    items,
  };
}

function buildProjectsSection(resume: ResumeData): RenderDocumentSection | null {
  if (!resume.projects?.length) return null;
  const items: RenderContentItem[] = [];
  for (const p of resume.projects) {
    items.push({
      kind: "table-row",
      cells: [
        { text: p.name, bold: true, align: "left" },
        { text: p.url ?? "", bold: false, align: "right" },
      ],
    });
    if (p.description) {
      items.push({ kind: "text", text: p.description });
    }
    if (p.bullets?.length) {
      items.push({ kind: "bullets", bullets: p.bullets });
    }
  }
  return {
    type: "projects",
    title: SECTION_TITLES.projects,
    items,
  };
}

function buildCertificationsSection(resume: ResumeData): RenderDocumentSection | null {
  if (!resume.certifications?.length) return null;
  const items: RenderContentItem[] = [];
  for (const c of resume.certifications) {
    const leftText = `${c.name}${c.issuer ? ` – ${c.issuer}` : ""}`;
    items.push({
      kind: "table-row",
      cells: [
        { text: leftText, bold: true, align: "left" },
        { text: c.date ?? "", bold: false, align: "right" },
      ],
    });
    if (c.url) {
      items.push({ kind: "text", text: c.url, italic: true });
    }
  }
  return {
    type: "certifications",
    title: SECTION_TITLES.certifications,
    items,
  };
}

/**
 * Build a RenderDocumentSection from dynamic sections that were preserved
 * or restored by the Dynamic Section Preservation Engine.
 */
function buildDynamicSections(resume: ResumeData): RenderDocumentSection | null {
  const dynamicSections = resume.dynamicSections;
  if (!dynamicSections || dynamicSections.length === 0) return null;

  const items: RenderContentItem[] = [];
  for (const ds of dynamicSections) {
    items.push({ kind: "text" as const, text: ds.title, bold: true });

    if (ds.bullets.length === 1 && ds.bullets[0].length > 60) {
      // Single long paragraph — render as text
      items.push({ kind: "text" as const, text: ds.bullets[0] });
    } else {
      // Multiple bullets — render as bullet list
      const bulletItems = ds.bullets.filter(b => b.trim().length > 0);
      if (bulletItems.length > 0) {
        items.push({ kind: "bullets" as const, bullets: bulletItems });
      }
    }
  }

  return {
    type: "dynamicSections",
    title: "",
    items,
  };
}

function fmtInfohasRenderDate(d?: string): string {
  if (!d) return "";
  if (/present/i.test(d)) return "Present";
  // "2024-05" → "May 2024"
  const m = d.match(/^(\d{4})-(\d{2})$/);
  if (m) {
    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return `${months[parseInt(m[2]) - 1] ?? m[2]} ${m[1]}`;
  }
  if (/^\d{4}$/.test(d)) return d;
  return d;
}

/**
 * Normalize a section title for deduplication comparison
 */
function normalizeSectionTitle(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 /** Known RenderSectionType values that correspond to structured resume fields.
  * Dynamic sections whose normalized title overlaps with any of these will be
  * skipped to prevent content duplication.
  */
 const STRUCTURED_SECTION_TITLES = new Set([
   "professional summary",
   "summary",
   "professional experience",
   "experience",
   "work experience",
   "education",
   "core competencies & skills",
   "skills",
   "core competencies",
   "key skills",
   "technical skills",
   "key competencies",
   "competencies",
   "languages",
   "additional information",
   "certifications",
   "projects",
   "personal information",
   "personal details",
   "contact",
   "contact information",
   "personal",
   "date of birth",
   "nationality",
 ]);

 /** Email, phone, and personal-information patterns for detecting contact content in dynamic sections */
 const PERSONAL_INFO_RE = /date\s*of\s*birth|dob\s*:|[\w.+-]+@[\w-]+\.[\w.-]+|[\+]?\d{8,}|\b\d{2}[\/\-]\d{2}[\/\-]\d{4}\b/i;

/**
 * Convert ResumeData → RenderDocument (single source of truth for all renderers)
 */
export function toRenderDocument(
  resume: ResumeData,
  layout?: ResumeLayoutModel,
): RenderDocument {
  const L = layout ?? getDefaultResumeLayout();

  const sections: RenderDocumentSection[] = [];

  // Track which section types have already been rendered to avoid dynamic section overlap
  const renderedNormalizedTitles = new Set<string>();

  const renderAndTrack = (builder: () => RenderDocumentSection | null): void => {
    const section = builder();
    if (section) {
      sections.push(section);
      const norm = normalizeSectionTitle(section.title);
      if (norm) renderedNormalizedTitles.add(norm);
    }
  };

  // 1. Standard structured sections (rendered according to layout sectionOrder)
  const builders: Record<string, () => RenderDocumentSection | null> = {
    summary: () => buildProfessionalProfile(resume),
    experience: () => buildExperienceSection(resume),
    education: () => buildEducationSection(resume),
    skills: () => buildSkillsSection(resume),
    languages: () => buildLanguagesSection(resume),
    additionalInfo: () => buildAdditionalInfoSection(resume),
    projects: () => buildProjectsSection(resume),
    certifications: () => buildCertificationsSection(resume),
  };

  const renderedSections = new Set<string>();
  const order = (L.sectionOrder && L.sectionOrder.length > 0)
    ? L.sectionOrder
    : ["summary", "skills", "experience", "education", "languages", "certifications", "projects", "additionalInfo"];

  for (const sectionKey of order) {
    const builder = builders[sectionKey];
    if (builder) {
      renderAndTrack(builder);
      renderedSections.add(sectionKey);
    }
  }

  // Fallback: render any sections that were missed/omitted in a custom order
  for (const [sectionKey, builder] of Object.entries(builders)) {
    if (!renderedSections.has(sectionKey)) {
      renderAndTrack(builder);
    }
  }

  // 2. Dynamic sections — only if they don't overlap with already-rendered content
  const dynamicSections = resume.dynamicSections || [];
  for (const ds of dynamicSections) {
    const normTitle = normalizeSectionTitle(ds.title);

    // Skip if the section was already rendered by a structured builder
    if (renderedNormalizedTitles.has(normTitle) || STRUCTURED_SECTION_TITLES.has(normTitle)) {
      continue;
    }

    // Also skip if the normalized title matches any structured section pattern
    // (e.g. "KEY COMPETENCIES" matches "CORE COMPETENCIES & SKILLS")
    const isStructuredOverlap = Array.from(STRUCTURED_SECTION_TITLES).some(t =>
      normTitle.includes(t) || t.includes(normTitle)
    );
    if (isStructuredOverlap) continue;

    // Skip dynamic sections whose content contains contact/personal information
    // (email, phone, date of birth) — these are already rendered via the contact block
    if (
      PERSONAL_INFO_RE.test(ds.content || "") ||
      PERSONAL_INFO_RE.test(ds.title)
    ) {
      continue;
    }

    // Skip empty-titled sections (likely dangling header fragments)
    if (!normTitle) continue;

    const items: RenderContentItem[] = [];
    if (ds.content) {
      items.push({ kind: "text", text: ds.content });
    }
    if (ds.bullets && ds.bullets.length > 0) {
      items.push({ kind: "bullets", bullets: ds.bullets, level: 0 });
    }
    if (items.length > 0) {
      sections.push({
        type: "dynamicSections" as RenderSectionType,
        title: ds.title.toUpperCase(),
        items,
      });
    }
  }

  // Estimate total chars
  let totalChars = 0;
  for (const s of sections) {
    for (const item of s.items) {
      if (item.kind === "text") totalChars += item.text.length;
      else if (item.kind === "bullets") totalChars += item.bullets.join(" ").length;
      else if (item.kind === "nested-bullets") {
        for (const g of item.groups) {
          totalChars += g.label.length + g.items.join(", ").length;
        }
      }
    }
  }

  return {
    template: resume.template,
    layout: L,
    contact: buildContactBlock(resume),
    sections,
    totalChars,
    hasAdditionalInfo: !!resume.additionalInfo,
  };
}

