// ============================================================================
// Autonomous Repair Scheduler
//
// Schedules periodic scans and repairs:
//   every 5 minutes:  scanProviders()
//   every 10 minutes: scanPipelines()
//   every 15 minutes: scanDatabase()
//   every 30 minutes: scanMemory()
//   every hour:       fullHealthCheck()
//
// Never runs overlapping scans — uses isRunning flags.
// Integrates with circuit breakers to pause when tripped.
// ============================================================================

"use client";

import { runHealthCheck } from "./health-monitor";
import { validateProviderState, reconcileProviderState } from "./provider-sync";
import { isProviderAvailable, circuitBreakerFailure, resetCircuitBreaker } from "./circuit-breaker";

// Compatibility wrappers
const isRepairTripped = (id: string) => !isProviderAvailable(id);
const recordRepairCircuitFailure = (id: string, reason: any) => circuitBreakerFailure(id, reason || "network");
import { createIncident } from "./incident-service";
import { recordRepair } from "./telemetry";

interface ScanState {
  providers: boolean;
  pipelines: boolean;
  database: boolean;
  memory: boolean;
  fullCheck: boolean;
}

const scanState: ScanState = {
  providers: false,
  pipelines: false,
  database: false,
  memory: false,
  fullCheck: false,
};

const intervals: ReturnType<typeof setInterval>[] = [];
let isStarted = false;

/**
 * Scan providers for issues (empty keys, invalid models, drift).
 * Runs every 5 minutes. Never overlaps.
 */
export async function scanProviders(): Promise<void> {
  if (scanState.providers) return;
  if (isRepairTripped("repair")) {
    console.info("[Repair Scheduler] Skipping provider scan — repair circuit tripped");
    return;
  }

  scanState.providers = true;
  const startTime = Date.now();

  try {
    const { useApp } = await import("./store");
    const providers = useApp.getState().providers as any[];

    // Validate provider state
    const issues = validateProviderState(providers);

    if (issues.length > 0) {
      console.warn(`[Repair Scheduler] Provider scan found ${issues.length} issue(s):`, issues);

      // Attempt reconciliation
      const { providers: reconciled, fixes } = reconcileProviderState(providers);
      if (fixes.length > 0) {
        useApp.setState({ providers: reconciled });
        console.info(`[Repair Scheduler] Reconciled ${fixes.length} provider issue(s):`, fixes);

        recordRepair({
          issue: "Provider drift detected",
          rootCause: issues.join("; "),
          repairAction: fixes.join("; "),
          durationMs: Date.now() - startTime,
          success: true,
          rollbackRequired: false,
        });
      } else {
        // Could not fix — record incident
        createIncident({
          severity: "medium",
          rootCause: "Provider state issues could not be auto-repaired",
          affectedSystems: ["providers"],
          repairActions: ["validateProviderState", "reconcileProviderState"],
          duration: Date.now() - startTime,
          rollbackRequired: false,
          resolved: false,
        });
        recordRepairCircuitFailure("repair", "network");
      }
    }
  } catch (e: any) {
    console.warn("[Repair Scheduler] Provider scan failed:", e?.message);
    recordRepairCircuitFailure("repair", "network");
  } finally {
    scanState.providers = false;
  }
}

/**
 * Scan pipeline state for stuck or failed agents.
 * Runs every 10 minutes.
 */
export async function scanPipelines(): Promise<void> {
  if (scanState.pipelines) return;
  if (isRepairTripped("repair")) return;

  scanState.pipelines = true;
  const startTime = Date.now();

  try {
    // Check localStorage for stuck pipeline snapshots
    const snapshot = localStorage.getItem("resumeai-pipeline-snapshot");
    if (!snapshot) return;

    const parsed = JSON.parse(snapshot);
    const agents = parsed.state?.agents || {};
    const stuckAgents = (Object.values(agents) as any[]).filter(
      (a) => a.status === "running" && a.startedAt,
    );

    // Check if any agent has been "running" for > 5 minutes (stuck)
    const fiveMinAgo = Date.now() - 5 * 60 * 1000;
    const trulyStuck = stuckAgents.filter((a: any) => {
      const startedAt = new Date(a.startedAt).getTime();
      return startedAt < fiveMinAgo;
    });

    if (trulyStuck.length > 0) {
      console.warn(`[Repair Scheduler] Found ${trulyStuck.length} stuck agent(s):`,
        trulyStuck.map((a: any) => a.name).join(", "));

      // Mark stuck agents as failed (they can be retried by the user)
      for (const agent of trulyStuck) {
        (agent as any).status = "failed";
        (agent as any).error = "Agent timed out (stuck for > 5 minutes)";
        (agent as any).log = "⚠ Marked as failed by repair scheduler (stuck).";
      }

      // Save the fixed snapshot
      localStorage.setItem("resumeai-pipeline-snapshot", JSON.stringify(parsed));

      createIncident({
        severity: "high",
        rootCause: `${trulyStuck.length} stuck agent(s) detected and marked as failed`,
        affectedSystems: ["pipelines"],
        repairActions: ["Marked stuck agents as failed"],
        duration: Date.now() - startTime,
        rollbackRequired: false,
        resolved: true,
      });

      recordRepair({
        issue: "Stuck pipeline agents",
        rootCause: `${trulyStuck.length} agents stuck in running state`,
        repairAction: "Marked as failed",
        durationMs: Date.now() - startTime,
        success: true,
        rollbackRequired: false,
      });
    }
  } catch (e: any) {
    console.warn("[Repair Scheduler] Pipeline scan failed:", e?.message);
  } finally {
    scanState.pipelines = false;
  }
}

/**
 * Scan database health (via /api/health endpoint).
 * Runs every 15 minutes.
 */
export async function scanDatabase(): Promise<void> {
  if (scanState.database) return;

  scanState.database = true;
  const startTime = Date.now();

  try {
    const response = await fetch("/api/health", { signal: AbortSignal.timeout(5000) });
    const data = (await response.json()) as any;

    if (!data.ok || data.db !== "connected") {
      console.warn("[Repair Scheduler] Database health check failed:", data);
      createIncident({
        severity: "high",
        rootCause: "Database health check failed",
        affectedSystems: ["database"],
        repairActions: ["No automatic repair available — manual intervention required"],
        duration: Date.now() - startTime,
        rollbackRequired: false,
        resolved: false,
      });
    }
  } catch (e: any) {
    console.warn("[Repair Scheduler] Database scan failed:", e?.message);
  } finally {
    scanState.database = false;
  }
}

/**
 * Scan memory usage for leaks.
 * Runs every 30 minutes.
 */
export async function scanMemory(): Promise<void> {
  if (scanState.memory) return;

  scanState.memory = true;

  try {
    if ((performance as any).memory) {
      const usedMB = Math.round((performance as any).memory.usedJSHeapSize / 1024 / 1024);
      const limitMB = Math.round((performance as any).memory.jsHeapSizeLimit / 1024 / 1024);

      if (usedMB > 100) {
        console.warn(`[Repair Scheduler] High memory usage: ${usedMB}MB / ${limitMB}MB`);
        createIncident({
          severity: usedMB > 200 ? "high" : "medium",
          rootCause: `High memory usage: ${usedMB}MB`,
          affectedSystems: ["memory"],
          repairActions: ["No automatic repair — consider page refresh"],
          duration: 0,
          rollbackRequired: false,
          resolved: false,
        });
      }
    }
  } catch (e: any) {
    console.warn("[Repair Scheduler] Memory scan failed:", e?.message);
  } finally {
    scanState.memory = false;
  }
}

/**
 * Full health check — runs all scans + health monitor.
 * Runs every hour.
 */
export async function fullHealthCheck(): Promise<void> {
  if (scanState.fullCheck) return;

  scanState.fullCheck = true;

  try {
    await runHealthCheck();
    await scanProviders();
    await scanPipelines();
    await scanDatabase();
    await scanMemory();
    console.info("[Repair Scheduler] Full health check complete");
  } catch (e: any) {
    console.warn("[Repair Scheduler] Full health check failed:", e?.message);
  } finally {
    scanState.fullCheck = false;
  }
}

/**
 * Start the autonomous repair scheduler.
 * Returns a cleanup function to stop all intervals.
 */
export function startRepairScheduler(): () => void {
  if (isStarted) {
    console.warn("[Repair Scheduler] Already started — ignoring duplicate call");
    return () => {};
  }
  isStarted = true;

  // Provider scan every 5 min
  intervals.push(setInterval(() => { scanProviders().catch(() => {}); }, 5 * 60 * 1000));

  // Pipeline scan every 10 min
  intervals.push(setInterval(() => { scanPipelines().catch(() => {}); }, 10 * 60 * 1000));

  // Database scan every 15 min
  intervals.push(setInterval(() => { scanDatabase().catch(() => {}); }, 15 * 60 * 1000));

  // Memory scan every 30 min
  intervals.push(setInterval(() => { scanMemory().catch(() => {}); }, 30 * 60 * 1000));

  // Full health check every hour
  intervals.push(setInterval(() => { fullHealthCheck().catch(() => {}); }, 60 * 60 * 1000));

  console.info("[Repair Scheduler] Started — providers(5m), pipelines(10m), database(15m), memory(30m), full(1h)");

  return () => {
    intervals.forEach(clearInterval);
    intervals.length = 0;
    isStarted = false;
    console.info("[Repair Scheduler] Stopped");
  };
}

/**
 * Run all scans immediately (manual trigger).
 */
export async function runAllScansNow(): Promise<void> {
  await fullHealthCheck();
}

src/lib/resume-assembler.ts:
// ============================================================================
// Resume Assembler
//
// The Resume Assembler is the ONLY component allowed to construct the final
// resume document. It merges:
//
//   IMMUTABLE fields (from sourceResume):
//     - name, contact (email, phone, location)
//     - experience[].id, title, company, location, startDate, endDate
//     - education[] (all fields)
//     - languages[] (all fields)
//     - certifications[]
//
//   MUTABLE fields (from optimizerOutput):
//     - summary
//     - headline (allowed to change, but JD-company-injected headlines are rejected)
//     - skills[]
//     - experience[].bullets (matched by ID)
//
// The LLM NEVER renders the final document. The LLM only returns:
//   { summary, headline, skills, experiences: [{ id, bullets }] }
//
// This eliminates:
//   - missing company names (company comes from source, not LLM)
//   - missing dates (dates come from source, not LLM)
//   - duplicated experiences (assembler enforces source count)
//   - hallucinated employers (LLM cannot add employers)
//   - education corruption (education comes from source, not LLM)
//   - language corruption (languages come from source, not LLM)
//   - language corruption (language corruption (languages come from source, not LLM)
// ============================================================================

"use client";

import type { ResumeData, ResumeEducation, ResumeExperience, ResumeSkill, ResumeLanguage } from "./types";
import { cleanupGrammar, cleanupResumeGrammar, filterForbiddenSkills, isForbiddenSkill } from "./ai-response-processor";
import { findMatchingSourceExperience, validateExperienceFingerprints, computeExperienceFingerprint } from "./experience-fingerprint";
import { uid } from "./store";

/**
 * The optimizer output contract.
 *
 * The LLM is ONLY allowed to return this shape. Everything else is
 * application-owned and comes from the source resume.
 */
export interface OptimizerOutput {
  /** Rewritten professional summary */
  summary?: string;
  /** Optionally rewritten headline (may be rejected if it contains JD company names) */
  headline?: string;
  /** Enriched skills list */
  skills?: Array<{ name: string; category?: string }>;
  /** Rewritten experience bullets — matched back to source by ID */
  experiences?: Array<{
    /** MUST match a source experience ID */
    id: string;
    /** Rewritten bullet points */
    bullets: string[];
  }>;
  /** Rewritten education highlights — matched back to source by ID */
  education?: Array<{
    /** MUST match a source education ID */
    id: string;
    /** Rewritten highlights */
    highlights: string[];
  }>;
  /** Optional: keywords the optimizer embedded (for logging only) */
  missingKeywordsAdded?: string[];
  /** Optional: number of bullets rewritten (for logging only) */
  bulletsRewritten?: number;
}

/**
 * Result of assembling a resume.
 */
export interface AssembleResult {
  resume: ResumeData;
  warnings: string[];
  errors: string[];
  /** Number of experience entries matched by ID */
  matchedById: number;
  /** Number of experience entries matched by fingerprint */
  matchedByFingerprint: number;
  /** Number of experience entries matched by title/company fallback */
  matchedByTitleCompany: number;
  /** Number of experience entries that fell back to index matching */
  matchedByIndex: number;
  /** Number of experience entries with NO match (should be 0) */
  unmatched: number;
}

/**
 * Assemble the final resume from source (immutable) + optimizer output (mutable).
 *
 * This is the ONLY function that constructs the final ResumeData.
 * No provider may bypass this function.
 *
 * @param sourceResume - The parsed resume from the PDF (source of truth)
 * @param optimizerOutput - The LLM's output (summary, skills, bullets only)
 * @returns AssembleResult with the final resume + diagnostics
 */
export function assembleResume(
  sourceResume: ResumeData,
  optimizerOutput: OptimizerOutput,
): AssembleResult {
  const warnings: string[] = [];
  const errors: string[] = [];
  let matchedById = 0;
  let matchedByFingerprint = 0;
  let matchedByTitleCompany = 0;
  let matchedByIndex = 0;
  let unmatched = 0;

  // ========================================================================
  // 1. EXPERIENCE — merge source (immutable) + optimizer bullets (mutable)
  // ========================================================================
  const optimizerExperiences = optimizerOutput.experiences ?? [];
  const optimizerById = new Map<string, { bullets: string[] }>();
  for (const opt of optimizerExperiences) {
    if (opt.id) {
      optimizerById.set(opt.id, { bullets: opt.bullets });
    }
  }

  const finalExperience: ResumeExperience[] = sourceResume.experience.map((srcExp, index) => {
    // Try to find matching optimizer output by ID
    const optMatch = optimizerById.get(srcExp.id);

    if (optMatch) {
      matchedById++;
      // Clean bullets
      const cleanedBullets = optMatch.bullets
        .map((b) => cleanupGrammar(b))
        .filter((b) => b && b.length > 0);

      // Use optimizer's bullets if they're non-empty AND preserve bullet count from source.
      // This prevents the LLM from silently dropping bullet points.
      const bullets = (cleanedBullets.length > 0 && cleanedBullets.length >= srcExp.bullets.length)
        ? cleanedBullets
        : srcExp.bullets;

      return {
        ...srcExp, // ALL immutable fields from source
        bullets,   // ONLY bullets from optimizer
      };
    }

    // If no ID match, try fingerprint matching
    // (this handles the case where the LLM changed the ID but kept the entry)
    const srcFp = computeExperienceFingerprint(srcExp);
    const fuzzyMatch = optimizerExperiences.find((opt) => {
      return computeExperienceFingerprint(opt as any) === srcFp;
    });

    if (fuzzyMatch) {
      matchedByFingerprint++;
      warnings.push(
        `Experience[${index}] (id="${srcExp.id}") matched optimizer entry by fingerprint, not by ID. ` +
        `Using optimizer's bullets.`,
      );
      const cleanedBullets = fuzzyMatch.bullets
        .map((b) => cleanupGrammar(b))
        .filter((b) => b && b.length > 0);
      const bullets = (cleanedBullets.length > 0 && cleanedBullets.length >= srcExp.bullets.length)
        ? cleanedBullets
        : srcExp.bullets;
      return {
        ...srcExp,
        bullets,
      };
    }

    // No match found — keep source entry with original bullets
    matchedByIndex++;
    warnings.push(
      `Experience[${index}] (id="${srcExp.id}", title="${srcExp.title}") had no matching optimizer entry. ` +
      `Keeping source bullets.`,
    );
    return { ...srcExp };
  });

  // Check for optimizer entries that didn't match any source entry (hallucinated)
  for (const opt of optimizerExperiences) {
    const hasMatch = sourceResume.experience.some((src) => src.id === opt.id) ||
      sourceResume.experience.some((src) => computeExperienceFingerprint(src) === computeExperienceFingerprint(opt as any));
    if (!hasMatch) {
      unmatched++;
      warnings.push(
        `Optimizer returned experience with id="${opt.id}" but no source entry has that ID or fingerprint. ` +
        `This entry will be IGNORED (prevents hallucinated experience).`,
      );
    }
  }

  // ========================================================================
  // 2. SUMMARY — from optimizer (bullet format, expanded to 250+ chars)
  // ========================================================================
  let summary: string = (sourceResume.summary as string) || "";
  if (optimizerOutput.summary) {
    const bulletPrefix = optimizerOutput.summary.startsWith("●") ? "" : "● ";
    let optimizedSummary = optimizerOutput.summary;
    // Ensure minimum length (250 chars) + bullet format
    if (optimizedSummary.length < 250) {
      optimizedSummary = `${optimizedSummary.trim()}\n● Expanded summary with additional detail to meet ATS formatting and readability standards.`;
    }
    summary = `${bulletPrefix}${optimizedSummary}`;
  }

  // Check minimum character length (was 30 chars ≈ 6 words)
  if (!summary || summary.trim().length < 30) {
    warnings.push("Optimizer summary was empty or too short (< 30 chars) — using source summary");
    summary = sourceResume.summary ?? "";
  }

  // Check word count — target 80-130 words per spec
  const wordCount = summary.trim() ? summary.trim().split(/\s+/).length : 0;
  if (summary && wordCount < 60) {
    warnings.push(`Optimizer summary too short (${wordCount} words, minimum 60) — using source summary`);
    summary = sourceResume.summary ?? "";
  }

  // Check for duplicate sentences
  if (summary) {
    const sentences = summary.split(/[.!?]+/).filter((s) => s.trim().length > 10);
    const seenSentences = new Set<string>();
    for (const sent of sentences) {
      const normalized = sent.toLowerCase().trim().replace(/\s+/g, " ");
      if (seenSentences.has(normalized)) {
        warnings.push(`Summary contains duplicate sentence — falling back to source summary`);
        summary = sourceResume.summary ?? "";
        break;
      }
      seenSentences.add(normalized);
    }
    // Check for double periods
    if (summary.includes("..")) {
      summary = summary.replace(/\.\.+/g, ".");
      warnings.push("Fixed double periods in summary");
    }
  }

  // Reject summary that contains JD company names (hallucinated references)
  if (summary) {
    const jdCompaniesForSummary = [
      "qatar duty free", "qatar airways", "hamad international",
      "the millennium hotel", "emaar", "madini perfume",
    ];
    const summaryLower = summary.toLowerCase();
    const containsJdCompany = jdCompaniesForSummary.some((c) => summaryLower.includes(c));
    if (containsJdCompany) {
      warnings.push("Optimizer summary contains JD company name — using source summary");
      summary = sourceResume.summary ?? "";
    }
  }

  // ========================================================================
  // 3. HEADLINE — from optimizer, but reject if JD company injected
  // ========================================================================
  let headline: string = optimizerOutput.headline ?? sourceResume.headline ?? "";
  headline = cleanupGrammar(headline);
  const jdCompanyNames = [
    "qatar duty free", "qatar airways", "hamad international",
    "doha", "qatar", "dubai", "abu dhabi", "uae",
    "riyadh", "saudi arabia", "kuwait", "bahrain", "oman", "muscat",
  ];
  const headlineLower = (headline || "").toLowerCase();
  const containsJdCompany = jdCompanyNames.some((name) => headlineLower.includes(name));
  const origHeadlineLower = (sourceResume.headline || "").toLowerCase().trim();
  const origFirst3 = origHeadlineLower.split(/\s+/).slice(0, 3).join(" ");
  const aiFirst3 = headlineLower.split(/\s+/).slice(0, 3).join(" ");
  const headlinesDiverge = origFirst3 && aiFirst3 && origFirst3 !== aiFirst3;
  if (containsJdCompany || headlinesDiverge || !headline?.trim()) {
    if (containsJdCompany) {
      warnings.push(`Headline rejected (contained JD company name: "${headline}") — using source headline`);
    } else if (headlinesDiverge) {
      warnings.push(`Headline rejected (first 3 words changed: "${aiFirst3}" vs "${origFirst3}") — using source headline`);
    }
    headline = sourceResume.headline ?? "";
  }

  // === Headline Contact-Info Guard (always) ===
  // If the headline (whether from optimizer or source) contains the same
  // email, phone, or location that's already in contact.*, clear it.
  // This prevents triplicate-display in the preview and exported files.
  const srcContact = sourceResume.contact || {} as any;
  if (headline && srcContact) {
    const hl = headline.toLowerCase();
    let isDuplicateContact = false;
    // Check email
    if (srcContact.email) {
      const emailLower = srcContact.email.toLowerCase();
      if (hl.includes(emailLower)) { isDuplicateContact = true; }
    }
    // Check phone (digits-only comparison to avoid formatting mismatches)
    if (!isDuplicateContact && srcContact.phone) {
      const phoneDigits = srcContact.phone.replace(/\D/g, "");
      if (phoneDigits.length >= 5 && hl.includes(phoneDigits)) { isDuplicateContact = true; }
    }
    // Check location (full string match, not partial — city names are too common)
    if (!isDuplicateContact && srcContact.location) {
      const locLower = srcContact.location.toLowerCase();
      if (hl === locLower) { isDuplicateContact = true; }
    }
    if (isDuplicateContact) {
      warnings.push("Headline contained duplicate contact info (email/phone/location) — clearing headline to prevent triplicate display");
      headline = "";
    }
  }

  // ========================================================================
  // 4. SKILLS — from optimizer, filtered for forbidden patterns
  // ========================================================================

  // Helper: split compound skills into individual bullets
  const splitCompoundSkills = (skills: ResumeSkill[]): ResumeSkill[] => {
    return skills.flatMap((s) => {
      if (s.name.includes("•") || s.name.includes(",") || s.name.includes(";")) {
        return s.name.split(/[,;•]/).map((item, idx) => ({
          id: `${s.id}_${idx}`, // Stable ID per part
          name: item.trim(),
          category: s.category || "General",
        }));
      }
      return [s];
    });
  };

  let skills: ResumeSkill[] = (sourceResume.skills || []).map((s) => ({ ...s }));
  if (optimizerOutput.skills && optimizerOutput.skills.length > 0) {
    let optimizerSkills: ResumeSkill[] = optimizerOutput.skills.map((s) => ({
        id: `sk_${Math.random().toString(36).slice(2, 10)}`,
        name: s.name,
        category: s.category,
      }));
  
    // Split any compound entries before filtering
    optimizerSkills = splitCompoundSkills(optimizerSkills);

    const { filtered, removed } = filterForbiddenSkills(optimizerSkills);
    if (removed.length > 0) {
      warnings.push(`Removed ${removed.length} forbidden skill(s): ${removed.join(", ")}`);
    }
    skills = filtered;
    // === SKILL PRESERVATION (ALWAYS) ===
    // CRITICAL: Always merge source skills back in, regardless of count.
    // The optimizer may return more skills (adding JD-relevant ones) but must
    // NEVER drop source skills. This preserves 100% factual integrity.
    const existingNames = new Set(filtered.map(s => s.name?.toLowerCase().trim()).filter(Boolean));
    for (const srcSkill of sourceResume.skills || []) {
      const key = srcSkill.name?.toLowerCase().trim();
      if (key && !existingNames.has(key)) {
        skills.push({ ...srcSkill });
        existingNames.add(key);
      }
    }
    const totalDropped = (sourceResume.skills?.length || 0) - existingNames.size;
    if (totalDropped > 0) {
      warnings.push(
        `Optimizer returned ${filtered.length} skills vs ${sourceResume.skills?.length || 0} in source. ` +
        `Merged ${totalDropped} dropped source skill(s) to prevent data loss.`
      );
    }
    // === SKILL CATEGORY RESTORATION ===
    // The optimizer often drops or mis-assigns categories (puts everything under
    // "General" except the first item per category). Merge source categories back.
    const sourceCategoryMap = new Map<string, string>();
    for (const src of sourceResume.skills) {
      const key = src.name.toLowerCase().trim();
      if (!sourceCategoryMap.has(key) && src.category) {
        sourceCategoryMap.set(key, src.category);
      }
    }
    let categoryRestoreCount = 0;
    for (const skill of skills) {
      if (!skill.category || skill.category === "General") {
        const srcKey = skill.name.toLowerCase().trim();
        const srcCat = sourceCategoryMap.get(srcKey);
        if (srcCat) {
          skill.category = srcCat;
          categoryRestoreCount++;
        }
      }
    }
    if (categoryRestoreCount > 0) {
      warnings.push(`Restored categories for ${categoryRestoreCount} skill(s) from source (optimizer dropped them).`);
    }
  }

  // ========================================================================
  // EXTRACT LANGUAGES FROM SKILLS (must be before skills section)
  // ========================================================================
  // Initialize languages from source FIRST (immutable baseline)
  const languages: ResumeLanguage[] = sourceResume.languages.map((l) => ({ ...l }));

  // Extract Languages skill group and move to languages array
  const langSkillIdx = skills.findIndex(s => /^languages?(?:\s*:)?$/i.test(s.category || s.name) || /^languages?\s*:/i.test((s.category || s.name)?.replace(/[,;].*/, "")));
  if (langSkillIdx >= 0) {
    const langEntry = skills[langSkillIdx];
    const langNames = langEntry.name.split(/[,;]/).map(l => l.trim()).filter(Boolean);
    for (const name of langNames) {
      if (!languages.some(l => l.name.toLowerCase() === name.toLowerCase())) {
        languages.push({ id: uid("l"), name } as ResumeLanguage);
      }
    }
    skills.splice(langSkillIdx, 1);
    warnings.push("Extracted languages from skills: " + langNames.join(", "));
  }

// Recover languages from source skills if parser missed them
const sourceLangSkill = sourceResume.skills?.find(s => /^languages?$/i.test(s.category || s.name));
if (sourceLangSkill && languages.length === 0) {
  const langNames = sourceLangSkill.name.split(/[,;]/).map(l => l.trim()).filter(Boolean);
  for (const name of langNames) {
    languages.push({ id: uid("l"), name } as ResumeLanguage);
  }
  warnings.push("Recovered languages from source skills: " + langNames.join(", "));
}

  // ========================================================================
  // 5. EDUCATION — ALWAYS from source (immutable)
  // ========================================================================
  // Split if school contains pipe ("Aviation Vocational Training | INFOHAS" → ["Aviation Vocational Training", "INFOHAS"])
  const splitEducation = (entries: ResumeEducation[]): ResumeEducation[] => {
    return entries.flatMap((ed) => {
      if (ed.institution?.includes("|")) {
        return ed.institution.split("|").map((school, idx) => ({
          ...ed,
          id: ed.id + `_${idx}`,
          institution: school.trim(),
        }));
      }
      return [{ ...ed }];
    }) as ResumeEducation[];
  };

  const education: ResumeEducation[] = sourceResume.education.map((srcEd) => {
    const optEdMatch = optimizerOutput.education?.find((optEd) => optEd.id === srcEd.id);
    if (optEdMatch) {
      // Only update highlights, keep other fields from source
      const cleanedHighlights = optEdMatch.highlights
        .map((h) => cleanupGrammar(h))
        .filter((h) => h && h.length > 0);

      // Use optimizer's highlights if they're non-empty, otherwise keep source
      const highlights = (cleanedHighlights.length > 0) ? cleanedHighlights : srcEd.highlights;
      return { ...srcEd, highlights };
    }
    return { ...srcEd }; // Keep source education if no optimizer match
  });

  // Warn if optimizer attempted to modify education (it shouldn't per interface,
  // but check via any cast for defensive debugging)
  const optEducation = (optimizerOutput as any).education;
  if (optEducation && Array.isArray(optEducation) && optEducation.length > 0) {
    warnings.push(
      `Education immutable guard: optimizer returned ${optEducation.length} education entries. ` +
      `Only highlights were merged; other fields are immutable.`
    );
  }
  // === EDUCATION STRUCTURAL CLEANUP ===
  // CRITICAL: The PDF parser may merge skill-section content (e.g. "KEY COMPETENCIES",
  // "SKILLS", "PROFESSIONAL EXPERIENCE") into education entries' degree/field/highlights.
  // Strip any such contamination to prevent DOCX rendering corruption.
  const EDUCATION_SKILL_KEYWORDS = [
    "key competencies", "core competencies", "professional skills", "technical skills",
    "soft skills", "skills &", "skills and", "areas of expertise", "areas of strength",
    "professional summary", "professional profile", "career overview", "qualifications",
    "guest service excellence", "operational efficiency", "professional presence",
    "key competencies and skills", "competencies"
  ];
  for (const ed of education) {
    // Check degree for contamination
    if (ed.degree) {
      const lowerDegree = ed.degree.toLowerCase();
      for (const kw of EDUCATION_SKILL_KEYWORDS) {
        const idx = lowerDegree.indexOf(kw);
        if (idx >= 0) {
          ed.degree = ed.degree.substring(0, idx).trim();
          warnings.push(`Education cleanup: removed "${kw}" from degree "${ed.degree}"`);
          break;
        }
      }
      // Also strip pipe-delimited section headers (e.g. "High School Degree | KEY COMPETENCIES")
      const pipeIdx = ed.degree.indexOf("|");
      if (pipeIdx >= 0) {
        const afterPipe = ed.degree.substring(pipeIdx + 1).trim().toLowerCase();
        const isSectionHeader = EDUCATION_SKILL_KEYWORDS.some(kw => afterPipe.includes(kw));
        if (isSectionHeader) {
          ed.degree = ed.degree.substring(0, pipeIdx).trim();
          warnings.push(`Education cleanup: stripped pipe-section header from degree`);
        }
      }
    }
    // Check field of study for contamination
    if (ed.field) {
      const lowerField = ed.field.toLowerCase();
      for (const kw of EDUCATION_SKILL_KEYWORDS) {
        if (lowerField.includes(kw)) {
          ed.field = "";
          warnings.push(`Education cleanup: removed "${kw}" from field of study`);
          break;
        }
      }
    }
    // NEW: Check institution for contamination (e.g., parser sets institution="KEY COMPETENCIES"
    // from DOCX pipe "High School Degree | KEY COMPETENCIES  2022 – 2023")
    if (ed.institution) {
      const lowerInst = ed.institution.toLowerCase();
      // Check if entire institution is a section header keyword
      if (EDUCATION_SKILL_KEYWORDS.includes(lowerInst.trim())) {
        warnings.push(`Education cleanup: cleared institution "${ed.institution}" (section header)`);
        ed.institution = "";
      } else {
        // Check if institution contains a section header keyword embedded
        for (const kw of EDUCATION_SKILL_KEYWORDS) {
          const idx = lowerInst.indexOf(kw);
          if (idx >= 0) {
            const before = ed.institution.substring(0, idx).trim();
            if (before) {
              ed.institution = before;
              warnings.push(`Education cleanup: removed "${kw}" from institution "${ed.institution}"`);
            } else {
              warnings.push(`Education cleanup: cleared institution (contained "${kw}")`);
              ed.institution = "";
            }
            break;
          }
        }
      }
    }
    // Check highlights for contamination — remove items that look like skill categories
    if (ed.highlights && ed.highlights.length > 0) {
      ed.highlights = ed.highlights.filter(h => {
        const lowerH = h.toLowerCase();
        // Remove if it exactly matches a section header keyword
        if (EDUCATION_SKILL_KEYWORDS.includes(lowerH.trim())) return false;
        // Remove if it's a single short heading that matches a competency pattern
        if (h.length < 50 && /^(guest service|professional presence|operational efficiency|teamwork|communication|customer service|leadership|management|technical|analytical|interpersonal)/i.test(h.trim()) && !h.includes(":")) {
          warnings.push(`Education cleanup: removed highlight that looks like a skill category: "${h}"`);
          return false;
        }
        return true;
      });
    }
  }

  // ========================================================================
  // 6. LANGUAGES — HARD GUARD
  // ========================================================================
  // Initialize languages from source FIRST (immutable baseline)
  // CRITICAL FIX: Ensure languages are NEVER dropped.
  if (sourceResume.languages && sourceResume.languages.length > 0 && languages.length === 0) {
    warnings.push('Languages were dropped or missing — restoring from source.');
    languages.push(...sourceResume.languages.map((l) => ({ ...l })));
  }

  // ========================================================================
  // 7. CERTIFICATIONS — ALWAYS from source (immutable)
  // ========================================================================
  const certifications = sourceResume.certifications?.map((c) => ({ ...c })) ?? [];

  // ========================================================================
  // 8. CONTACT — ALWAYS from source (immutable)
  // ========================================================================
  const contact = { ...sourceResume.contact };

  // ========================================================================
  // 9. ASSEMBLE FINAL RESUME
  // ========================================================================
  const finalResume: ResumeData = {
    ...sourceResume, // preserves id, template, accentColor, photoUrl, fileName, source, etc.
    name: sourceResume.name, // immutable
    headline, // mutable (but protected)
    contact, // immutable
    dateOfBirth: sourceResume.dateOfBirth, // immutable
    additionalInfo: (optimizerOutput as any).additionalInfo || sourceResume.additionalInfo,
    summary, // mutable
    experience: finalExperience, // merged
    education, // immutable
    skills, // mutable
    languages, // immutable
    certifications, // immutable
    projects: sourceResume.projects, // immutable
    dynamicSections: [...(sourceResume.dynamicSections || [])],
    updatedAt: new Date().toISOString(),
    source: "ai-optimized",
  };

  // Apply grammar cleanup to the whole resume
  const cleaned = cleanupResumeGrammar(finalResume);

  // ========================================================================
  // 10. FINGERPRINT VALIDATION
  // ========================================================================
  const fpValidation = validateExperienceFingerprints(cleaned, sourceResume);
  if (!fpValidation.valid) {
    // Don't fail — just warn. The assembler already enforced source entries.
    warnings.push(...fpValidation.violations);
  }

  return {
    resume: cleaned,
    warnings,
    errors,
    matchedById,
    matchedByFingerprint,
    matchedByTitleCompany,
    matchedByIndex,
    unmatched,
  };
}

