        if (typeof localStorage !== "undefined") {
          try {
            const existing = JSON.parse(localStorage.getItem("resumeai-review-reports-backup") || "[]");
            const updated = existing.map((r: any) => r.id === id ? { ...r, ...patch, updatedAt: new Date().toISOString() } : r);
            localStorage.setItem("resumeai-review-reports-backup", JSON.stringify(updated));
          } catch (syncErr) { console.warn("[store] Operation failed:", syncErr instanceof Error ? syncErr.message : syncErr); }
        }
      },
      removeReviewReport: (id) => {
        set((s) => ({ reviewReports: s.reviewReports.filter((r) => r.id !== id) }));
        if (typeof localStorage !== "undefined") {
          try {
            const existing = JSON.parse(localStorage.getItem("resumeai-review-reports-backup") || "[]");
            localStorage.setItem("resumeai-review-reports-backup", JSON.stringify(existing.filter((x: any) => x.id !== id)));
          } catch (syncErr) { console.warn("[store] Operation failed:", syncErr instanceof Error ? syncErr.message : syncErr); }
        }
      },

      // === AI PROVIDERS — sync to D1 ===
      addProvider: (p) => {
        set((s) => ({ providers: [...s.providers, p] }));
        cloudApiSafe(createProvider)(p).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        // [PROVIDER SYNC] Sync with hash guard — only update if content actually changed
        try {
          import("./provider-sync").then(({ syncProviderConfigs, calculateProviderHash }) => {
            const currentProviders = get().providers as any[];
            const currentHash = calculateProviderHash(currentProviders);
            const lastHash = get()._lastProviderHash;
            if (currentHash !== lastHash) {
              const { providers: syncedProviders } = syncProviderConfigs(currentProviders);
              const syncedJson = JSON.stringify(syncedProviders);
              const currentJson = JSON.stringify(currentProviders);
              if (currentJson !== syncedJson) {
                set({ providers: syncedProviders, _lastProviderHash: calculateProviderHash(syncedProviders) });
              }
            }
          }).catch(() => {});
        } catch { /* non-fatal */ }
      },
      updateProvider: (id, patch) => {
        set((s) => ({ providers: s.providers.map((p) => (p.id === id ? { ...p, ...patch, updatedAt: new Date().toISOString() } : p)) }));
        cloudApiSafe(updateProvider)(id, patch).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        // [PROVIDER SYNC] Sync with hash guard — only update if content actually changed
        try {
          import("./provider-sync").then(({ syncProviderConfigs, calculateProviderHash }) => {
            const currentProviders = get().providers as any[];
            const currentHash = calculateProviderHash(currentProviders);
            const lastHash = get()._lastProviderHash;
            if (currentHash !== lastHash) {
              const { providers: syncedProviders, result } = syncProviderConfigs(currentProviders);
              const syncedJson = JSON.stringify(syncedProviders);
              const currentJson = JSON.stringify(currentProviders);
              if (currentJson !== syncedJson) {
                set({ providers: syncedProviders, _lastProviderHash: calculateProviderHash(syncedProviders) });
                if (result.repaired > 0 || result.backfilled > 0) {
                  console.info(`[PROVIDER SYNC] Provider updated. ${result.repaired} repaired, ${result.backfilled} backfilled.`);
                }
              }
            }
          }).catch(() => {});
        } catch { /* non-fatal */ }
      },
      removeProvider: (id) => {
        // Track deleted provider in localStorage to prevent seed backfill
        if (typeof window !== "undefined") {
          try {
            const deleted = JSON.parse(localStorage.getItem("resumeai-deleted-providers") || "[]");
            if (!deleted.includes(id)) {
              localStorage.setItem("resumeai-deleted-providers", JSON.stringify([...deleted, id]));
            }
          } catch (e) { console.warn("[store] Failed to save deleted provider to localStorage:", e); }
        }
        set((s) => ({
          providers: s.providers.filter((p) => p.id !== id),
          providerLogs: s.providerLogs.filter((l) => l.providerId !== id),
          providerSettings: {
            ...s.providerSettings,
            defaultProviderId: s.providerSettings.defaultProviderId === id ? null : s.providerSettings.defaultProviderId,
            fallbackProviderIds: s.providerSettings.fallbackProviderIds.filter((fid) => fid !== id),
          },
        }));
        cloudApiSafe(deleteProvider)(id).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },
      duplicateProvider: (id) => {
        const src = get().providers.find((p) => p.id === id);
        if (!src) return null;
        const newId = uid("p");
        const copy: AIProvider = {
          ...src,
          id: newId,
          name: `${src.name} (copy)`,
          isDefault: false,
          isBuiltIn: false,
          isActive: false,
          status: "untested",
          usage: { requests: 0, tokens: 0, errors: 0, avgLatencyMs: 0, cost: 0 },
          lastUsedAt: undefined,
        };
        set((s) => ({ providers: [...s.providers, copy] }));
        cloudApiSafe(createProvider)(copy).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        return newId;
      },
      setDefaultProvider: (id) => {
        set((s) => ({
          providers: s.providers.map((p) => ({ ...p, isDefault: p.id === id })),
          providerSettings: { ...s.providerSettings, defaultProviderId: id },
        }));
        // Update all providers in D1 (isDefault changed for multiple)
        get().providers.forEach((p) => cloudApiSafe(updateProvider)(p.id, { isDefault: p.id === id }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); }));
      },
      toggleFallback: (id) => {
        set((s) => {
          const isIn = s.providerSettings.fallbackProviderIds.includes(id);
          return {
            providers: s.providers.map((p) => (p.id === id ? { ...p, isFallback: !isIn } : p)),
            providerSettings: {
              ...s.providerSettings,
              fallbackProviderIds: isIn
                ? s.providerSettings.fallbackProviderIds.filter((fid) => fid !== id)
                : [...s.providerSettings.fallbackProviderIds, id],
            },
          };
        });
        const p = get().providers.find((x) => x.id === id);
        if (p) cloudApiSafe(updateProvider)(id, { isFallback: p.isFallback }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },
      reorderFallback: (id, direction) => {
        set((s) => {
          const ids = [...s.providerSettings.fallbackProviderIds];
          const i = ids.indexOf(id);
          if (i < 0) return s;
          const j = direction === "up" ? i - 1 : i + 1;
          if (j < 0 || j >= ids.length) return s;
          [ids[i], ids[j]] = [ids[j], ids[i]];
          return { providerSettings: { ...s.providerSettings, fallbackProviderIds: ids } };
        });
      },
      openFallbackOffer: (choices, currentProviderId) => set({
        fallbackOfferOpen: true,
        fallbackOfferChoices: choices,
        fallbackOfferCurrentProviderId: currentProviderId,
      }),
      closeFallbackOffer: () => set({
        fallbackOfferOpen: false,
        fallbackOfferChoices: [],
        fallbackOfferCurrentProviderId: null,
      }),
      addProviderLog: (l) => {
        set((s) => ({
          providerLogs: [l, ...s.providerLogs].slice(0, 1000),
          providers: s.providers.map((p) =>
            p.id === l.providerId
              ? {
                  ...p,
                  lastUsedAt: l.createdAt,
                  status: l.status === "success" ? "healthy" : l.status === "timeout" || l.status === "rate_limited" ? "degraded" : "down",
                  usage: {
                    ...p.usage,
                    requests: p.usage.requests + 1,
                    tokens: p.usage.tokens + (l.inputTokens ?? 0) + (l.outputTokens ?? 0),
                    errors: p.usage.errors + (l.status === "success" ? 0 : 1),
                    avgLatencyMs: Math.round((p.usage.avgLatencyMs * p.usage.requests + l.latencyMs) / (p.usage.requests + 1)),
                    cost: p.usage.cost + (l.inputTokens ?? 0) * (p.costPerInputToken ?? 0) + (l.outputTokens ?? 0) * (p.costPerOutputToken ?? 0),
                  },
                }
              : p
          ),
        }));
      },
      clearProviderLogs: (providerId) =>
        set((s) => ({
          providerLogs: providerId ? s.providerLogs.filter((l) => l.providerId !== providerId) : [],
        })),
      updateProviderSettings: (patch) => {
        set((s) => ({ providerSettings: { ...s.providerSettings, ...patch } }));
        // === PERSIST to D1 via branding endpoint ===
        const settings = get().providerSettings;
        cloudApiSafe(updateBranding)({
          providerSettings: settings,
        }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        // === ALSO backup to localStorage (survives even when D1 is down) ===
        if (typeof localStorage !== "undefined") {
          try {
            localStorage.setItem("resumeai-provider-settings", JSON.stringify(settings));
          } catch (syncErr) { console.warn("[store] Operation failed:", syncErr instanceof Error ? syncErr.message : syncErr); }
        }
      },

      addPrompt: (p) => {
        set((s) => ({ prompts: [...s.prompts, p] }));
        cloudApiSafe(createPrompt)(p).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },
      updatePrompt: (id, patch) => {
        set((s) => ({
          prompts: s.prompts.map((p) => (p.id === id ? { ...p, ...patch, version: p.version + 1 } : p)),
        }));
        cloudApiSafe(updatePrompt)(id, patch).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },
      removePrompt: (id) => {
        set((s) => ({ prompts: s.prompts.filter((p) => p.id !== id) }));
        cloudApiSafe(deletePrompt)(id).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },

      updateBranding: (patch) => {
        set((s) => ({ branding: { ...s.branding, ...patch } }));
        cloudApiSafe(updateBranding)({ ...get().branding, ...patch }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },
      updateFlag: (k, v) => {
        set((s) => ({ flags: { ...s.flags, [k]: v } }));
        cloudApiSafe(updateFlag)(k, v).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },
      updateOptimizerDirective: (patch) => {
        set((s) => ({ optimizerDirective: { ...s.optimizerDirective, ...patch } }));
        // Sync to D1 via the branding/settings endpoint (stored as a JSON blob)
        // We reuse the updateBranding cloud API since optimizerDirective is a
        // settings blob like branding. The cloud API stores it under a
        // dedicated key in the settings table.
        cloudApiSafe(cloudApi.updateBranding as any)({ optimizerDirective: { ...get().optimizerDirective, ...patch } }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Optimizer directive updated", category: "admin", details: Object.keys(patch).join(", "), severity: "info" });
      },
      resetOptimizerDirective: () => {
        set({ optimizerDirective: SEED_OPTIMIZER_DIRECTIVE });
        cloudApiSafe(cloudApi.updateBranding as any)({ optimizerDirective: SEED_OPTIMIZER_DIRECTIVE }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Optimizer directive reset to defaults", category: "admin", details: "All parameters restored to factory defaults", severity: "warning" });
      },
      updateFallbackChain: (patch) => {
        set((s) => ({ fallbackChain: { ...s.fallbackChain, ...patch } }));
        // Sync to D1 via the branding/settings endpoint (stored as a JSON blob)
        cloudApiSafe(cloudApi.updateBranding as any)({ fallbackChain: { ...get().fallbackChain, ...patch } }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Fallback chain updated", category: "admin", details: `${(patch.entries ?? []).length} entries, enabled=${patch.enabled ?? get().fallbackChain.enabled}`, severity: "info" });
      },
      resetFallbackChain: () => {
        set({ fallbackChain: SEED_FALLBACK_CHAIN });
        cloudApiSafe(cloudApi.updateBranding as any)({ fallbackChain: SEED_FALLBACK_CHAIN }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Fallback chain reset to defaults", category: "admin", details: "All fallback entries restored to factory defaults", severity: "warning" });
      },
      // === Pipeline Orchestration Actions ===
      updatePipelineProfile: (id, patch) => {
        set((s) => ({
          pipelineProfiles: s.pipelineProfiles.map((p) =>
            p.id === id ? { ...p, ...patch, updatedAt: new Date().toISOString() } : p,
          ),
        }));
        cloudApiSafe(cloudApi.updateBranding as any)({ pipelineProfiles: get().pipelineProfiles }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Pipeline profile updated", category: "admin", details: `Profile ${id}: ${Object.keys(patch).join(", ")}`, severity: "info" });
      },
      addPipelineProfile: (profile) => {
        set((s) => ({ pipelineProfiles: [...s.pipelineProfiles, profile] }));
        cloudApiSafe(cloudApi.updateBranding as any)({ pipelineProfiles: get().pipelineProfiles }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Pipeline profile added", category: "admin", details: `Profile: ${profile.name} (${profile.type})`, severity: "info" });
      },
      removePipelineProfile: (id) => {
        const profile = get().pipelineProfiles.find((p) => p.id === id);
        if (profile?.isBuiltIn) {
          console.warn("[store] Cannot remove built-in profile");
          return;
        }
        set((s) => ({ pipelineProfiles: s.pipelineProfiles.filter((p) => p.id !== id) }));
        cloudApiSafe(cloudApi.updateBranding as any)({ pipelineProfiles: get().pipelineProfiles }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Pipeline profile removed", category: "admin", details: `Profile: ${id}`, severity: "warning" });
      },
      selectPipelineProfile: (id) => {
        set({ selectedProfileId: id });
        cloudApiSafe(cloudApi.updateBranding as any)({ selectedProfileId: id }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        const profile = get().pipelineProfiles.find((p) => p.id === id);
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Pipeline profile selected", category: "admin", details: `Selected: ${profile?.name || id}`, severity: "info" });
      },
      updateAgentConfig: (agentType, patch) => {
        set((s) => ({
          agentConfigs: s.agentConfigs.map((a) =>
            a.agentType === agentType ? { ...a, ...patch, updatedAt: new Date().toISOString() } : a,
          ),
        }));
        cloudApiSafe(cloudApi.updateBranding as any)({ agentConfigs: get().agentConfigs }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Agent config updated", category: "admin", details: `Agent: ${agentType}, fields: ${Object.keys(patch).join(", ")}`, severity: "info" });
      },
      updatePromptVersion: (id, patch) => {
        set((s) => ({
          promptVersions: s.promptVersions.map((p) =>
            p.id === id ? { ...p, ...patch, lastModified: new Date().toISOString() } : p,
          ),
        }));
        cloudApiSafe(cloudApi.updateBranding as any)({ promptVersions: get().promptVersions }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Prompt version updated", category: "admin", details: `Prompt: ${id}`, severity: "info" });
      },
      addPromptVersion: (prompt) => {
        set((s) => ({ promptVersions: [...s.promptVersions, prompt] }));
        cloudApiSafe(cloudApi.updateBranding as any)({ promptVersions: get().promptVersions }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Prompt version added", category: "admin", details: `Prompt: ${prompt.name} v${prompt.version}`, severity: "info" });
      },
      resetPipelineOrchestration: () => {
        set({
          pipelineProfiles: SEED_PIPELINE_PROFILES,
          selectedProfileId: SEED_PIPELINE_PROFILES.find((p) => p.isDefault)?.id || SEED_PIPELINE_PROFILES[0]?.id || "",
          agentConfigs: SEED_AGENT_CONFIGS,
          promptVersions: SEED_PROMPT_VERSIONS,
        });
        cloudApiSafe(cloudApi.updateBranding as any)({
          pipelineProfiles: SEED_PIPELINE_PROFILES,
          selectedProfileId: get().selectedProfileId,
          agentConfigs: SEED_AGENT_CONFIGS,
          promptVersions: SEED_PROMPT_VERSIONS,
        }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "Pipeline orchestration reset to defaults", category: "admin", details: "All profiles, agents, and prompts restored to factory defaults", severity: "warning" });
      },
      updateAIDevSettings: (patch) => {
        set((s) => ({ aiDevSettings: { ...s.aiDevSettings, ...patch } }));
        // Persist to localStorage so settings survive browser refresh
        try { localStorage.setItem("resumeai-ai-dev-settings", JSON.stringify({ ...get().aiDevSettings, ...patch })); } catch {}
        cloudApiSafe(cloudApi.updateBranding as any)({ aiDevSettings: { ...get().aiDevSettings, ...patch } }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
        useApp.getState().log({ actor: get().user?.email ?? "admin", action: "AI Dev Agent settings updated", category: "admin", details: Object.keys(patch).join(", "), severity: "info" });
      },
      addSnapshot: (snapshot) => {
        set((s) => ({ snapshots: [...s.snapshots, snapshot] }));
        try {
          const existing = JSON.parse(localStorage.getItem("resumeai-snapshots") || "[]");
          existing.push(snapshot);
          if (existing.length > 50) existing.splice(0, existing.length - 50);
          localStorage.setItem("resumeai-snapshots", JSON.stringify(existing));
        } catch {}
      },
      restoreSnapshot: (snapshotId) => {
        const snapshot = get().snapshots.find((s) => s.snapshotId === snapshotId);
        if (!snapshot) return null;
        return JSON.parse(JSON.stringify(snapshot.fullResume));
      },
      clearSnapshots: (resumeId) => {
        set((s) => ({
          snapshots: resumeId
            ? s.snapshots.filter((sn) => sn.resumeId !== resumeId)
            : [],
        }));
        try {
          if (resumeId) {
            const existing = JSON.parse(localStorage.getItem("resumeai-snapshots") || "[]");
            localStorage.setItem("resumeai-snapshots",
              JSON.stringify(existing.filter((s: ResumeSnapshot) => s.resumeId !== resumeId)));
          } else {
            localStorage.removeItem("resumeai-snapshots");
          }
        } catch {}
      },
      addAIDevHistory: (entry) => {
        const full: AIDevAgentHistory = {
          ...entry,
          id: uid("h"),
          createdAt: new Date().toISOString(),
        };
        set((s) => ({ aiDevHistory: [full, ...s.aiDevHistory].slice(0, 200) }));
      },
      addAIDevReport: (report) => {
        const full: AIDevReport = {
          ...report,
          id: uid("rpt"),
          createdAt: new Date().toISOString(),
        };
        set((s) => ({ aiDevReports: [full, ...s.aiDevReports].slice(0, 100) }));
      },
      // AI Workspace (Builder Agent) actions
      addAITask: (task) => {
        const now = new Date().toISOString();
        const full: AITask = { ...task, id: uid("t"), createdAt: now, updatedAt: now };
        set((s) => ({ aiTasks: [full, ...s.aiTasks].slice(0, 100) }));
      },
      updateAITask: (id, patch) => {
        set((s) => ({
          aiTasks: s.aiTasks.map((t) => (t.id === id ? { ...t, ...patch, updatedAt: new Date().toISOString() } : t)),
        }));
      },
      removeAITask: (id) => {
        set((s) => ({ aiTasks: s.aiTasks.filter((t) => t.id !== id) }));
      },
      addAIPatch: (patch) => {
        const full: AIWorkspacePatch = { ...patch, id: uid("p"), createdAt: new Date().toISOString() };
        set((s) => ({ aiPatches: [full, ...s.aiPatches].slice(0, 100) }));
      },
      updateAIPatch: (id, patch) => {
        set((s) => ({ aiPatches: s.aiPatches.map((p) => (p.id === id ? { ...p, ...patch } : p)) }));
      },
      addAIRollback: (rollback) => {
        const full: AIRollback = { ...rollback, id: uid("rb"), rolledBackAt: new Date().toISOString() };
        set((s) => ({ aiRollbacks: [full, ...s.aiRollbacks].slice(0, 50) }));
      },
      setAIHealingIssues: (issues) => {
        set({ aiHealingIssues: issues });
      },
      updateAIHealingIssue: (id, patch) => {
        set((s) => ({
          aiHealingIssues: s.aiHealingIssues.map((issue) =>
            issue.id === id ? { ...issue, ...patch } : issue
          ),
        }));
      },
      setAIHealingReport: (report) => {
        set({ aiHealingReport: report });
      },
      setAIHealingProgress: (progress) => {
        set({ aiHealingProgress: progress });
      },

      log: (entry) => {
        set((s) => ({
          logs: [
            { id: uid("l"), timestamp: new Date().toISOString(), ...entry },
            ...s.logs,
          ].slice(0, 500),
        }));
        cloudApiSafe(createAuditLog)({ id: uid("l"), timestamp: new Date().toISOString(), ...entry }).catch((e) => { console.warn("[store] Cloud sync failed:", e instanceof Error ? e.message : e); });
      },
      clearLogs: () => set({ logs: [] }),

      incUsage: (k) =>
        set((s) => {
          if (!s.user) return s;
          // Defensive: usage may be undefined if user was created without it
          const currentUsage = s.user.usage || { resumesGenerated: 0, atsChecks: 0, coverLetters: 0, interviewPreps: 0, downloads: 0 };
          const currentValue = (currentUsage as any)[k] || 0;
          return { user: { ...s.user, usage: { ...currentUsage, [k]: currentValue + 1 } } };
        }),
    })
);

export { BRAND };
export { uid };

if (typeof window !== "undefined") {
  (window as any).useApp = useApp;
}

