  autoFixed: number;
  needsReview: number;
  failed: number;
  filesChanged: number;
  testsPassed: number;
  buildStatus: "PASS" | "FAIL";
}

// ============================================================================
// RenderDocument — SINGLE SOURCE OF TRUTH for all renderers (Preview, DOCX, PDF)
// ============================================================================
// Every renderer consumes this interface. No renderer may create its own
// structure, section ordering, or formatting decisions.
// ============================================================================

export type RenderSectionType =
  | "personalInformation"
  | "professionalProfile"
  | "professionalExperience"
  | "education"
  | "skills"
  | "languages"
  | "additionalInformation"
  | "projects"
  | "certifications"
  | "dynamicSections";

export interface RenderDocumentSection {
  type: RenderSectionType;
  title: string;
  /** Ordered list of paragraph-like content items */
  items: RenderContentItem[];
}

export type RenderContentItem =
  | RenderTextLine
  | RenderBulletList
  | RenderNestedBulletList
  | RenderTableRow;

export interface RenderTextLine {
  kind: "text";
  text: string;
  bold?: boolean;
  italic?: boolean;
  fontSizePt?: number;
}

export interface RenderBulletList {
  kind: "bullets";
  bullets: string[];
  level?: number; // 0 = top-level, 1 = nested
}

export interface RenderNestedBulletList {
  kind: "nested-bullets";
  groups: { label: string; items: string[] }[];
}

export interface RenderTableRow {
  kind: "table-row";
  cells: { text: string; bold?: boolean; align?: "left" | "right" }[];
}

export interface RenderContactBlock {
  name: string;
  headline?: string;
  phone?: string;
  email?: string;
  location?: string;
  dateOfBirth?: string;
  /** Structured personal details rendered as label-value pairs */
  personalDetails?: Record<string, string>;
}

export interface RenderDocument {
  /** Metadata */
  template: ResumeTemplate;
  layout: ResumeLayoutModel;
  /** Contact block — rendered once at the top */
  contact: RenderContactBlock;
  /** Canonical section order — renderers iterate this array */
  sections: RenderDocumentSection[];
  /** Total estimated character count for one-page enforcement */
  totalChars: number;
  /** Whether additionalInfo was present in source */
  hasAdditionalInfo: boolean;
}

/** Canonical section order blueprint */
export const CANONICAL_SECTION_ORDER: RenderSectionType[] = [
  "professionalProfile",
  "professionalExperience",
  "education",
  "skills",
  "languages",
  "additionalInformation",
  "projects",
  "certifications",
];

/**
 * Optimization pipeline stages — used by Session Checkpoint & Recovery system.
 */
export type OptimizationStage =
  | "parsing"
  | "summary"
  | "experience"
  | "education"
  | "skills"
  | "languages"
  | "assembly";

// ====================================================================
// Preservation Architecture v2 — Section Fingerprints & Snapshot
// ====================================================================

/**
 * Fingerprint for a single section — computed from canonical resume fields.
 * Enables before/after comparison in the Guardian and Supervisor.
 */
export interface SectionFingerprint {
  /** Stable section type (e.g. "professionalExperience", "education", "languages") */
  sectionType: string;
  /** Number of top-level entities in this section (e.g. experience entries, languages) */
  entityCount: number;
  /** Total text content character count (bullets + highlights + names) */
  contentCount: number;
  /** Total bullet/highlight items across all entities */
  bulletCount: number;
  /** FNV-1a hash of the canonical serialized content for this section alone */
  hash: string;
}

/**
 * Immutable snapshot created immediately after parsing.
 * Represents the CANONICAL, UNALTERABLE source of truth.
 * The optimizer may ONLY modify optimizable fields; the snapshot
 * is used by the Merge Engine and Guardian to enforce preservation.
 */
export interface PreservationSnapshot {
  /** When this snapshot was created */
  createdAt: string;
  /** Source file name (if from upload) or "manual" */
  source: string;
  /** Total section count (every section type that has >= 1 entity) */
  sectionCount: number;
  /** Per-section fingerprints for comparison */
  sections: SectionFingerprint[];
  /** Complete entity IDs for every entity in the resume */
  entityIds: {
    experience: string[];
    education: string[];
    skills: string[];
    languages: string[];
    projects: string[];
    certifications: string[];
    dynamicSections: string[];
  };
  /** Immutable fields — NEVER modified by optimization */
  immutable: {
    name: string;
    email?: string;
    phone?: string;
    employerNames: string[];
    institutionNames: string[];
    degreeNames: string[];
    languageNames: string[];
    experienceDates: Array<{ id: string; startDate: string; endDate: string }>;
    educationDates: Array<{ id: string; startDate: string; endDate: string }>;
    certificationNames: string[];
    projectNames: string[];
  };
  /** Optimizable fields — initial values for reference */
  optimizable: {
    summaryLength: number;
    headlineLength: number;
    bulletCount: number;
    highlightCount: number;
    skillCategoryCount: number;
  };
}

